/* generado por prompts/herramientas/clave-mejoras-datos.js; no editar a mano */
(window.CLAVE_ARTF=window.CLAVE_ARTF||{})[1]=[["Artículos 5 y 6 — Crímenes de la competencia de la Corte y genocidio · R19 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R19</span>","<p data-ex=\"*\" data-r=\"R19\"><span class=\"ex-sello ex-sello-r\">R19</span> <b>Art. 5.</b> 1. <mark class=\"m-destacable\">La competencia de</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">limitará</mark> <mark class=\"m-personalizado\">a los <u class=\"m-clave\">crímenes más graves</u> de trascendencia para la comunidad internacional en su conjunto</mark>. <mark class=\"m-personalizado\">La</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">tendrá</mark> competencia <span class=\"ex-plg\"><span class=\"ex-plg-t\">, de conformidad con el presente Estatuto,</span></span> respecto de los siguientes crímenes: a) <mark class=\"m-resp\" data-q=\"1-95\">El crimen de genocidio</mark>; b) <mark class=\"m-resp\" data-q=\"1-95,1-ia-3740\">Los crímenes de lesa humanidad</mark>; c) <mark class=\"m-resp\" data-q=\"1-95\">Los crímenes de guerra</mark>; d) <mark class=\"m-resp r-ia\" data-q=\"1-ia-3634\">El crimen de agresión</mark>.</p><p data-ex=\"EXOF\"><b>Art. 6.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">A los efectos del presente Estatuto,</span></span> <mark class=\"m-accion\">se entenderá por «genocidio»</mark> <mark class=\"m-personalizado\">cualquiera de los actos</mark> mencionados <mark class=\"m-personalizado\">a continuación</mark>, perpetrados con la <mark class=\"m-personalizado\"><u class=\"m-clave\">intención</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">de</u> destruir</mark> <mark class=\"m-personalizado\">total o</mark> <mark class=\"m-destacable\">parcialmente</mark> <mark class=\"m-personalizado\">a un</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3635\">grupo nacional, étnico, racial o religioso</mark> <mark class=\"m-personalizado\">como tal:</mark> a) <mark class=\"m-personalizado\">matanza de miembros del grupo;</mark> b) <mark class=\"m-personalizado\"><u class=\"m-clave\">lesión</u> grave a la integridad física o mental</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de los miembros del grupo</span></span>; c) <mark class=\"m-personalizado\">sometimiento intencional del grupo a <u class=\"m-clave\">condiciones de</u> existencia que hayan de acarrear su</mark> destrucción física <span class=\"ex-plg\"><span class=\"ex-plg-t\">, total o parcial</span></span>; d) <mark class=\"m-personalizado\">medidas destinadas a <u class=\"m-clave\">impedir nacimientos</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en el seno del grupo</span></span>; e) <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"1-147,1-ia-3638\">traslado por la fuerza de niños del grupo a otro grupo</mark>.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3636,1-ia-3637\">🎯 2 preguntas</mark></p>"],["Artículos 7 y 8 — Lesa humanidad y crímenes de guerra <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p><b>Art. 7.</b> 1. A los efectos del presente Estatuto, <mark class=\"m-accion\">se entenderá</mark> por <mark class=\"m-accion\">«crimen de lesa humanidad»</mark> <mark class=\"m-personalizado\">cualquiera de los actos siguientes</mark> <span class=\"m-caja\">cuando</span> se cometa <mark class=\"m-personalizado\">como parte de un</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3639\">ataque generalizado o sistemático contra una población civil y con conocimiento de dicho ataque</mark>: <mark class=\"m-resp ex-q\" data-q=\"1-148\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>d)</b> <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"1-201\">Deportación o <u class=\"m-clave\">traslado forzoso</u> de población</mark>;</mark></p><p><b>g)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Violación,</u> esclavitud sexual, prostitución forzada, embarazo forzado, esterilización forzada o cualquier otra</mark> forma de <mark class=\"m-personalizado\">violencia sexual <mark class=\"m-resp r-ia\" data-q=\"1-ia-3642\">de gravedad comparable</mark>;</mark></p><p data-ex=\"*\"><b>h)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Persecución</u> de un <u class=\"m-clave\">grupo</u> o colectividad <u class=\"m-clave\">con identidad</u> propia</mark> fundada <mark class=\"m-personalizado\">en <u class=\"m-clave\">motivos</u> políticos,</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">raciales,</mark></span> <mark class=\"m-personalizado\">nacionales, étnicos, culturales, religiosos, de género</mark> definido en el párrafo 3, u <mark class=\"m-personalizado\"><u class=\"m-clave\">otros</u> motivos</mark> universalmente reconocidos como <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"1-202\">inaceptables</mark> con arreglo al derecho internacional, en conexión con cualquier acto mencionado</mark> en el presente párrafo o con cualquier crimen de la competencia de la <mark class=\"m-autoridad\">Corte;</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3643\">🎯 1 pregunta</mark></p><p><b>j)</b> <mark class=\"m-personalizado\">El <mark class=\"m-resp r-ia\" data-q=\"1-ia-3644\">crimen de «apartheid»</mark>.</mark></p><p data-ex=\"EXOF\"><b>a)</b> Por «ataque contra una población civil» <mark class=\"m-accion\">se entenderá</mark> una <mark class=\"m-personalizado\">línea de conducta</mark> que implique la <mark class=\"m-autoridad\"><u class=\"m-clave\">comisión</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">múltiple de</u> actos mencionados en el párrafo 1 contra una <u class=\"m-clave\">población</u> civil,</mark> de conformidad con <mark class=\"m-resp\" data-q=\"1-ia-3645,1-168\">la política de un Estado o de una organización de cometer ese ataque o para promover esa política</mark>;</p><p><b>b)</b> El <mark class=\"m-autoridad\">«exterminio»</mark> <mark class=\"m-accion\">comprenderá</mark> la <mark class=\"m-personalizado\"><u class=\"m-clave\">imposición</u> intencional de condiciones de vida,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">entre otras, la <mark class=\"m-personalizado\">privación</mark> del acceso a <mark class=\"m-personalizado\">alimentos o medicinas encaminadas</mark> a causar <mark class=\"m-personalizado\">la <mark class=\"m-resp r-ia\" data-q=\"1-ia-3646\">destrucción de parte de una población</mark>;</mark></span></span></p><p><b>c)</b> Por <mark class=\"m-autoridad\">«esclavitud»</mark> <mark class=\"m-accion\">se entenderá</mark> el <span class=\"ex-plg\"><span class=\"ex-plg-t\">ejercicio de los atributos del <mark class=\"m-personalizado\">derecho <u class=\"m-clave\">de propiedad</u> sobre una persona,</mark> o de algunos de ellos, <mark class=\"m-personalizado\">incluido</mark> el ejercicio de esos</span></span> atributos en el <span class=\"m-circulo\"><mark class=\"m-personalizado\">tráfico</mark></span> <mark class=\"m-personalizado\">de personas, en particular</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3647\">mujeres y niños</mark>;</p><p><b>d)</b> Por <mark class=\"m-autoridad\">«deportación o <u class=\"m-clave\">traslado forzoso de</u> población»</mark> <mark class=\"m-accion\">se entenderá</mark> el <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">desplazamiento forzoso</mark> de las personas</span></span> <mark class=\"m-personalizado\">afectadas, por expulsión u otros actos coactivos, de la zona</mark> en que estén <mark class=\"m-personalizado\">legítimamente presentes,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3648\">sin motivos autorizados por el derecho internacional</mark>; <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3640\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>e)</b> Por <mark class=\"m-autoridad\">«tortura»</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-personalizado\">causar intencionalmente <u class=\"m-clave\">dolor o sufrimientos</u> graves, ya sean físicos <u class=\"m-clave\">o mentales,</u></mark> a una persona que el acusado tenga <span class=\"m-circulo\"><mark class=\"m-personalizado\">bajo su</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">custodia</u> o control; sin embargo,</mark> no <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">entenderá</mark> por tortura <mark class=\"m-resp r-ia\" data-q=\"1-ia-3649\">el dolor o los sufrimientos que se deriven únicamente de sanciones lícitas o que sean consecuencia normal o fortuita de ellas</mark>; <mark class=\"m-resp ex-q\" data-q=\"1-203\">🎯 1 pregunta</mark></p><p><b>f)</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Por <mark class=\"m-autoridad\">«embarazo forzado»</mark> <mark class=\"m-accion\">se entenderá</mark> el <mark class=\"m-personalizado\">confinamiento ilícito de una mujer a la que se ha dejado embarazada por la fuerza, con la intención de modificar la composición étnica de una población</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> de cometer <mark class=\"m-personalizado\">otras violaciones graves</mark> del derecho internacional.</span></span> En modo alguno <mark class=\"m-accion\">se entenderá</mark> que esta definición afecta <mark class=\"m-resp r-ia\" data-q=\"1-ia-3641,1-ia-3650\">a las normas de derecho interno relativas al embarazo</mark>;</p><p><b>g)</b> Por <mark class=\"m-autoridad\">«persecución»</mark> <mark class=\"m-accion\">se entenderá</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">la <mark class=\"m-personalizado\">privación intencional y grave de derechos fundamentales en contravención del derecho internacional en razón de la identidad</mark> del grupo o de la colectividad.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3701\">🎯 1 pregunta</mark></p><p><b>h)</b> Por el <mark class=\"m-personalizado\">crimen de</mark> <mark class=\"m-autoridad\">«apartheid»</mark> se <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">entenderán</mark> los <mark class=\"m-personalizado\">actos inhumanos</mark> de carácter similar a los mencionados en el párrafo 1 cometidos en el contexto de un</span></span> <mark class=\"m-personalizado\">régimen institucionalizado de opresión y dominación sistemáticas de un grupo racial sobre uno o más grupos</mark> raciales y con <mark class=\"m-personalizado\">la intención de</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3702\">mantener ese régimen</mark>;</p><p><b>i)</b> Por <mark class=\"m-autoridad\">«desaparición forzada de personas» se</mark> <mark class=\"m-accion\">entenderá</mark> <mark class=\"m-autoridad\">la aprehensión, la detención o el secuestro de personas por un Estado</mark> o <span class=\"ex-plg\"><span class=\"ex-plg-t\">una organización política o con su autorización, apoyo o aquiescencia, seguido de la negativa a admitir tal privación de libertad o dar información sobre la suerte o el <mark class=\"m-personalizado\">paradero</mark> de</span></span> esas personas, con la <mark class=\"m-personalizado\">intención de dejarlas fuera del amparo de la ley</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3703\">por un período prolongado</mark>.</p><p><b>3.</b> A los efectos del presente Estatuto, <mark class=\"m-accion\">se entenderá</mark> que el <mark class=\"m-personalizado\">término «género» se refiere a</mark> <mark class=\"m-resp\" data-q=\"1-21\">los dos sexos, masculino y femenino, en el contexto de la sociedad</mark>. El término «género» <mark class=\"m-resp r-ia\" data-q=\"1-ia-3704\">no tendrá más acepción que la que antecede</mark>.</p><p><b>Art. 8.</b> 1. <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">competencia</mark> respecto de los <mark class=\"m-personalizado\">crímenes de guerra, en particular,</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">cuando se</mark></span> cometan <mark class=\"m-resp r-ia\" data-q=\"1-ia-3705,1-ia-3707\">como parte de un plan o política o como parte de la comisión en gran escala de tales crímenes</mark>.</p><p data-ex=\"EX\"><b>a)</b> Infracciones graves de los Convenios de <mark class=\"m-destacable\">Ginebra</mark> de 12 de agosto de 1949, a saber, cualquiera de los siguientes <mark class=\"m-personalizado\">actos contra <u class=\"m-clave\">personas o bienes protegidos</u></mark> por las disposiciones del Convenio de Ginebra pertinente:</p><p><b>v)</b> El hecho de <mark class=\"m-personalizado\">forzar a un prisionero de guerra o a otras</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">personas protegidas <mark class=\"m-personalizado\">a servir en las fuerzas</mark> de una Potencia <mark class=\"m-personalizado\">enemiga;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3706\">🎯 1 pregunta</mark></p><p><b>viii)</b> <mark class=\"m-personalizado\">La <mark class=\"m-resp r-ia\" data-q=\"1-ia-3708\">toma <u class=\"m-clave\">de</u> rehenes</mark>;</mark></p><p data-ex=\"*\"><b>b)</b> <mark class=\"m-personalizado\">Otras violaciones graves de las leyes y usos</mark> aplicables en los <mark class=\"m-personalizado\">conflictos armados <u class=\"m-clave\">internacionales</u></mark> dentro del marco establecido de derecho internacional, a saber, <mark class=\"m-personalizado\">cualquiera de los actos siguientes:</mark> <mark class=\"m-resp ex-q\" data-q=\"1-204\">🎯 1 pregunta</mark></p><p><b>ii)</b> <mark class=\"m-personalizado\">Dirigir</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">intencionalmente</mark></span> <mark class=\"m-personalizado\">ataques</mark> contra <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">bienes civiles,</mark> es decir, bienes que no son <mark class=\"m-personalizado\">objetivos militares;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3709\">🎯 1 pregunta</mark></p><p><b>iv)</b> <mark class=\"m-personalizado\">Lanzar un ataque intencionalmente, a sabiendas de que</mark> <mark class=\"m-accion\">causará</mark> <mark class=\"m-personalizado\">pérdidas incidentales de</mark> vidas, lesiones <span class=\"ex-plg\"><span class=\"ex-plg-t\">a <mark class=\"m-personalizado\">civiles o</mark> daños <mark class=\"m-personalizado\">a bienes</mark> de carácter <mark class=\"m-personalizado\">civil o daños extensos, duraderos y graves al medio ambiente natural</mark> que serían</span></span> manifiestamente <mark class=\"m-personalizado\">excesivos</mark> en relación con <mark class=\"m-resp r-ia\" data-q=\"1-ia-3710\">la ventaja militar concreta y directa de conjunto que se prevea</mark>;</p><p><b>v)</b> <mark class=\"m-personalizado\">Atacar o bombardear,</mark> por cualquier medio, <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">ciudades, aldeas,</mark> viviendas o edificios que <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u> estén defendidos <u class=\"m-clave\">y</u> que <u class=\"m-clave\">no</u></mark> sean <mark class=\"m-personalizado\">objetivos militares;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3711\">🎯 1 pregunta</mark></p><p><b>vi)</b> <mark class=\"m-personalizado\">Causar la muerte o lesiones a</mark> un combatiente que haya <mark class=\"m-personalizado\">depuesto las armas</mark> <mark class=\"m-destacable\">o</mark> que, al <mark class=\"m-personalizado\">no tener medios</mark> para defenderse, <mark class=\"m-personalizado\">se haya <mark class=\"m-resp r-ia\" data-q=\"1-ia-3712\">rendido a discreción</mark>;</mark></p><p><b>ix)</b> <mark class=\"m-personalizado\">Dirigir intencionalmente ataques contra edificios</mark> dedicados a <mark class=\"m-personalizado\">la religión, la educación, las artes, las ciencias o la beneficencia, los monumentos históricos, los hospitales</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y los lugares en que se agrupa a enfermos y heridos, <mark class=\"m-personalizado\">siempre que no</mark> sean <mark class=\"m-personalizado\">objetivos militares;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3714\">🎯 1 pregunta</mark></p><p><b>xii)</b> <mark class=\"m-personalizado\">Declarar que no se</mark> <mark class=\"m-accion\">dará</mark> <mark class=\"m-personalizado\">cuartel;</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3715\">🎯 1 pregunta</mark></p><p><b>xv)</b> <mark class=\"m-personalizado\">Obligar a los nacionales</mark> de la parte <mark class=\"m-personalizado\">enemiga a participar en <u class=\"m-clave\">operaciones</u> bélicas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">dirigidas <mark class=\"m-personalizado\">contra su propio país, aunque hubieran <u class=\"m-clave\">estado</u> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3716\">al servicio del beligerante antes del inicio de la guerra</mark>;</mark></span></span></p><p><b>xix)</b> <mark class=\"m-personalizado\">Emplear balas que se ensanchan o aplastan</mark> fácilmente en el <span class=\"ex-plg\"><span class=\"ex-plg-t\">cuerpo <mark class=\"m-personalizado\">humano, como</mark> balas de <mark class=\"m-personalizado\">camisa dura que no recubra totalmente la</mark> parte interior <mark class=\"m-personalizado\">o que tenga incisiones;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3717\">🎯 1 pregunta</mark></p><p><b>xx)</b> <mark class=\"m-personalizado\">Emplear armas, proyectiles, materiales y métodos de guerra</mark> que, por su <span class=\"ex-plg\"><span class=\"ex-plg-t\">propia naturaleza, <mark class=\"m-personalizado\">causen daños superfluos o sufrimientos innecesarios o surtan efectos <u class=\"m-clave\">indiscriminados</u> en violación del derecho</mark> internacional de los conflictos armados, <mark class=\"m-personalizado\">a condición</mark> de que esas armas o esos proyectiles, materiales o métodos de guerra, <mark class=\"m-personalizado\">sean objeto de una prohibición completa</mark> y estén incluidos en un anexo del presente Estatuto en virtud de una enmienda aprobada de conformidad con las disposiciones que, sobre el particular, figuran en los artículos 121 y 123;</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3718\">🎯 1 pregunta</mark></p><p><b>xxii)</b> <mark class=\"m-personalizado\">Cometer actos de violación, esclavitud sexual, prostitución forzada, embarazo forzado,</mark> definido en el <span class=\"ex-plg\"><span class=\"ex-plg-t\">apartado f) del párrafo 2 del artículo 7, <mark class=\"m-personalizado\">esterilización forzada y cualquier otra</mark> forma de violencia sexual que <span class=\"m-caja\">también</span> <mark class=\"m-personalizado\">constituya una infracción grave de los Convenios de Ginebra;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3719\">🎯 1 pregunta</mark></p><p><b>xxvi)</b> <mark class=\"m-resp\" data-q=\"1-149,1-ia-3720\">Reclutar o alistar a niños menores de quince años en las fuerzas armadas nacionales</mark> o utilizarlos para participar activamente en las <mark class=\"m-personalizado\">hostilidades;</mark></p><p><b>xxix)</b> Emplear armas láser específicamente concebidas, <span class=\"ex-plg\"><span class=\"ex-plg-t\">como única o una más de sus</span></span> funciones de combate, para causar <mark class=\"m-resp r-ia\" data-q=\"1-ia-3721\">ceguera permanente a la vista no amplificada</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">es decir, al ojo descubierto o al ojo provisto de dispositivos correctores de la vista.</span></span></p><p><b>c)</b> <mark class=\"m-personalizado\">En caso de <u class=\"m-clave\">conflicto</u> armado</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">que no sea de índole internacional,</u></mark> <mark class=\"m-personalizado\">las violaciones <u class=\"m-clave\">graves</u> del artículo 3</mark> común a <span class=\"ex-plg\"><span class=\"ex-plg-t\">los cuatro <mark class=\"m-personalizado\">Convenios de Ginebra</mark> de 12 <span class=\"m-circulo\">de</span> agosto de 1949, a saber, cualquiera de los siguientes actos cometidos <mark class=\"m-personalizado\">contra personas que <u class=\"m-clave\">no</u> participen directamente en las hostilidades, incluidos</mark> los</span></span> miembros de las <mark class=\"m-destacable\"><u class=\"m-clave\">Fuerzas Armadas</u></mark> que <mark class=\"m-resp r-ia\" data-q=\"1-ia-3722\">hayan <mark class=\"m-personalizado\">depuesto las armas y las</mark> personas puestas <mark class=\"m-destacable\"><u class=\"m-clave\">fuera de combate</u></mark> <mark class=\"m-personalizado\">por enfermedad, herida, detención</mark> o por cualquier <mark class=\"m-personalizado\">otra</mark> causa</mark>:</p><p><b>iv)</b> <mark class=\"m-personalizado\">Las condenas dictadas y las ejecuciones sin previo juicio ante un</mark> <mark class=\"m-autoridad\">tribunal</mark> regularmente constituido, <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">con todas las garantías</mark> judiciales generalmente reconocidas como <mark class=\"m-personalizado\">indispensables.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3723\">🎯 1 pregunta</mark></p><p><b>d)</b> <mark class=\"m-personalizado\">El párrafo 2.c)</mark> del presente artículo se <span class=\"ex-plg\"><span class=\"ex-plg-t\">aplica a los conflictos armados que no son de índole internacional, y por consiguiente, <mark class=\"m-personalizado\">no se aplica</mark> a las</span></span> situaciones de <mark class=\"m-personalizado\">tensiones internas y de disturbios interiores,</mark> tales como <mark class=\"m-resp r-ia\" data-q=\"1-ia-3724\">los motines, los actos esporádicos y aislados de violencia u otros actos análogos</mark>.</p><p><b>viii)</b> <mark class=\"m-personalizado\">Ordenar del desplazamiento de la población civil</mark> por razones relacionadas <span class=\"ex-plg\"><span class=\"ex-plg-t\">con el <mark class=\"m-personalizado\">conflicto, a menos</mark> que así lo <mark class=\"m-personalizado\">exija la seguridad</mark> de los civiles de que se trate <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">por razones militares imperativas;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3725\">🎯 1 pregunta</mark></p><p><b>f)</b> El <mark class=\"m-personalizado\">párrafo 2.e)</mark> del presente artículo <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">se aplica a los conflictos</mark> armados que <mark class=\"m-destacable\"><u class=\"m-clave\">no</u></mark> son de índole <mark class=\"m-personalizado\">internacional y,</mark> por consiguiente, no <mark class=\"m-personalizado\">se</mark> aplica a las situaciones de <mark class=\"m-personalizado\">tensiones internas y</mark> de disturbios <mark class=\"m-personalizado\">interiores,</mark> tales como los <mark class=\"m-personalizado\">motines, los actos esporádicos y aislados de violencia u otros</mark> actos análogos. <mark class=\"m-personalizado\">Se aplica a los conflictos armados</mark> que tienen lugar en el territorio</span></span> de un <mark class=\"m-autoridad\">Estado</mark> cuando existe <mark class=\"m-resp r-ia\" data-q=\"1-ia-3726\">un conflicto armado prolongado entre las autoridades gubernamentales y grupos armados organizados o entre tales grupos</mark>.</p><p><b>3.</b> <mark class=\"m-personalizado\">Nada</mark> de lo dispuesto en <span class=\"ex-plg\"><span class=\"ex-plg-t\">los párrafos <mark class=\"m-personalizado\">2.c) y e)</mark> <mark class=\"m-accion\">afectará</mark> a la responsabilidad que incumbe <mark class=\"m-personalizado\">a todo</mark> <mark class=\"m-autoridad\">gobierno</mark> <mark class=\"m-personalizado\">de mantener o restablecer el orden público</mark> en el <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">o</mark></span></span> de defender la <mark class=\"m-personalizado\">unidad e integridad territorial del</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3727\">por cualquier medio legítimo</mark>.</p><p class=\"ex-mas\"><mark class=\"m-resp ex-q\" data-q=\"1-148\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículo 8 bis y artículo 9 — Crimen de agresión y Elementos de los crímenes <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R20</span>","<p data-ex=\"*\"><b>Art. 8 bis.</b> 1. <span class=\"ex-plg\"><span class=\"ex-plg-t\">\u0007A los efectos del presente Estatuto,</span></span> una persona comete un <mark class=\"m-accion\">«crimen de agresión»</mark> cuando, estando <mark class=\"m-personalizado\">en condiciones de controlar <u class=\"m-clave\">o</u> dirigir efectivamente la <u class=\"m-clave\">acción</u> política <u class=\"m-clave\">o</u> militar de un</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Estado,</u></mark> planifica, prepara, inicia o realiza un acto de agresión que <span class=\"ex-plg\"><span class=\"ex-plg-t\">por sus características, gravedad y escala</span></span> constituya una violación manifiesta de la <mark class=\"m-personalizado\">Carta de las Naciones Unidas</mark>. 2. <span class=\"ex-plg\"><span class=\"ex-plg-t\">\u0007A los efectos del párrafo 1, por ‘’acto de agresión’’ se entenderá el uso de la fuerza armada por un Esta- do contra la soberanía, la integridad territorial o la independencia política de otro Estado, o en cualquier otra forma incompatible con la Carta de las Naciones Unidas.</span></span> <mark class=\"m-personalizado\">De conformidad con la</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3728,1-ia-3729,1-ia-4031,1-ia-4222\">resolución 3314 (XXIX) de la Asamblea General de las Naciones Unidas, de 14 de diciembre de 1974</mark>, <mark class=\"m-personalizado\">cualquiera de los actos siguientes</mark>, <mark class=\"m-personalizado\">independientemente de que haya o no declaración</mark> de guerra, <mark class=\"m-accion\">se caracterizará</mark> como acto de agresión: a) la invasión o el ataque <span class=\"ex-plg\"><span class=\"ex-plg-t\">por las fuerzas armadas de un Estado del territorio de otro Estado, o toda ocupación militar, aún temporal, que resulte de dicha invasión o ataque, o toda anexión, mediante el uso de la fuerza, del territorio de otro Estado o de parte de él</span></span>; b) <mark class=\"m-personalizado\">el bombardeo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, por las fuerzas armadas de un Estado, del territorio de otro Estado, o el empleo de cualesquiera armas por un Estado contra el territorio de otro Estado</span></span>; c) <mark class=\"m-personalizado\">el bloqueo de los puertos o de las costas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de un Estado por las fuerzas armadas de otro Estado</span></span>; (…) g) <mark class=\"m-personalizado\">el envío</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">por un Estado, o en su nombre,</span></span> <mark class=\"m-personalizado\">de bandas armadas</mark>, <mark class=\"m-personalizado\">grupos irregulares o mercenarios</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que lleven a cabo actos de fuerza armada contra otro Estado de tal gravedad que sean equiparables a los actos antes enumerados, o su sustancial participación en dichos actos</span></span>. <mark class=\"m-resp ex-q\" data-q=\"1-205\">🎯 1 pregunta</mark></p><p data-ex=\"*\" data-r=\"R20\"><span class=\"ex-sello ex-sello-r\">R20</span> <b>Art. 9.</b> 1. Los <mark class=\"m-destacable\">Elementos de los Crímenes</mark> <mark class=\"m-accion\">ayudarán</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-autoridad\">la Corte</mark> a <mark class=\"m-destacable\">interpretar y</mark> <mark class=\"m-personalizado\">aplicar los artículos</mark> 6, 7, 8 y 8 bis <span class=\"ex-plg\"><span class=\"ex-plg-t\">del presente Estatuto</span></span>, <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">aprobados</mark> por <mark class=\"m-destacable\">una <u class=\"m-clave\">mayoría de</u> dos tercios</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-autoridad\">los miembros de la Asamblea de los Estados Partes</mark>. 2. <mark class=\"m-accion\">Podrán</mark> <mark class=\"m-personalizado\">proponer</mark> <mark class=\"m-destacable\">enmiendas</mark> a <mark class=\"m-personalizado\">los Elementos de los crímenes</mark>: a) Cualquier <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte</mark>; <mark class=\"m-destacable\">b) Los</mark> <mark class=\"m-autoridad\">magistrados</mark>, <mark class=\"m-destacable\">por</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3735\">mayoría absoluta</mark>; c) El <mark class=\"m-autoridad\">fiscal.</mark> <mark class=\"m-destacable\">Las enmiendas</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-destacable\">aprobadas</mark> <mark class=\"m-personalizado\">por una</mark> <mark class=\"m-resp\" data-q=\"1-79,1-150,1-ia-3734,1-ia-3751,1-ia-4144\">mayoría de dos tercios</mark> <mark class=\"m-autoridad\">de los miembros de la Asamblea de los Estados Partes</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 8 bis — <mark class=\"m-personalizado\">Crimen de</mark> agresión: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3730,1-ia-3731,1-ia-3732,1-ia-3733\">🎯 4 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 10 — Normas de <mark class=\"m-personalizado\">derecho internacional</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3737,1-ia-4189\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 11, 12 y 13 — Competencia temporal, condiciones previas y ejercicio de la competencia · R20 <span class=\"ex-sello\">✱</span>","<p><b>Art. 11.</b> 1. <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">tendrá</mark> competencia <mark class=\"m-resp\" data-q=\"1-120,1-ia-3738\">únicamente respecto de crímenes cometidos después de la entrada en vigor del presente Estatuto</mark>. 2. Si un <mark class=\"m-autoridad\">Estado</mark> se hace Parte <span class=\"ex-plg\"><span class=\"ex-plg-t\">en el presente Estatuto</span></span> después de su entrada en vigor, <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-accion\">podrá ejercer</mark> su competencia <span class=\"m-caja\">únicamente con</span> respecto a los <mark class=\"m-plazo\">crímenes cometidos después de la entrada en vigor del presente Estatuto respecto de ese</mark> <mark class=\"m-autoridad\">Estado,</mark> <mark class=\"m-plazo\">a</mark> menos que <span class=\"m-caja\"><mark class=\"m-autoridad\">éste haya</mark></span> <mark class=\"m-personalizado\">hecho una declaración</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformi- dad con el párrafo 3</span></span> <mark class=\"m-personalizado\">del</mark> artículo 12.3. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3739\">🎯 1 pregunta</mark></p><p><b>Art. 12.</b> 1. <mark class=\"m-autoridad\">El Estado</mark> <mark class=\"m-personalizado\">que pase a ser Parte</mark> en <span class=\"ex-plg\"><span class=\"ex-plg-t\">el presente Estatuto <mark class=\"m-personalizado\">acepta</mark> por ello la <mark class=\"m-personalizado\">competencia de</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">respeto a los crímenes</mark> a que se refiere el artículo</span></span> 5. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3119\">🎯 1 pregunta</mark></p><p><b>a)</b> <mark class=\"m-personalizado\">El</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">en cuyo <u class=\"m-clave\">territorio</u> haya tenido <u class=\"m-clave\">lugar la</u> conducta</mark> de que <span class=\"ex-plg\"><span class=\"ex-plg-t\">se trate, <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">si el crimen</mark> se</span></span> hubiere cometido <mark class=\"m-personalizado\">a</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">bordo</mark></span> <mark class=\"m-personalizado\">de un buque o de una aeronave,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3741\">el Estado de matrícula del buque o la aeronave</mark>;</p><p data-ex=\"*\"><b>3.</b> Si <mark class=\"m-personalizado\">la</mark> <mark class=\"m-destacable\">aceptación</mark> <mark class=\"m-personalizado\">de un</mark> <mark class=\"m-autoridad\">Estado que no sea Parte</mark> en el presente Estatuto <mark class=\"m-personalizado\">fuere necesaria</mark> de conformidad con el párrafo 2, dicho <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-accion\">podrá,</mark> <mark class=\"m-personalizado\">mediante declaración depositada en poder del</mark> <mark class=\"m-autoridad\">secretario,</mark> consentir en que la <mark class=\"m-autoridad\">Corte</mark> ejerza su competencia respecto del crimen de que se trate. <mark class=\"m-autoridad\">El Estado aceptante</mark> <mark class=\"m-accion\">cooperará</mark> <mark class=\"m-personalizado\">con</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-resp\" data-q=\"1-206\">sin demora ni excepción de conformidad con la Parte IX</mark>.</p><p><b>Art. 13.</b> <mark class=\"m-personalizado\">La</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ejercer</mark> su competencia <span class=\"ex-plg\"><span class=\"ex-plg-t\">respecto de cualquiera de los crímenes a que se refiere el artículo 5 de conformidad con las disposiciones del presente Estatuto</span></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">si:</u></mark> a) un <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte remite</mark> <span class=\"m-caja\">al</span> <span class=\"m-caja\"><mark class=\"m-autoridad\">fiscal</mark></span> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, de conformidad con el artículo 14,</span></span> <span class=\"m-caja\">una situación</span> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en que parezca haberse cometido uno o varios de esos crímenes</span></span>; <mark class=\"m-autoridad\">b)</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">el Consejo</mark></span> de Seguridad, actuando con arreglo a lo dispuesto en el <mark class=\"m-resp\" data-q=\"1-ia-3743,1-ia-3756\">Capítulo VII de la Carta de las Naciones Unidas</mark>, <mark class=\"m-personalizado\">remite al</mark> <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-personalizado\">una situación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en que parezca haberse cometido uno o varios de esos crímenes</span></span>; <mark class=\"m-personalizado\">o</mark> c) <mark class=\"m-autoridad\"><u class=\"m-clave\">el</u> fiscal</mark> <mark class=\"m-personalizado\">ha iniciado una investigación</mark> (…) de conformidad con el artículo 15.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 14 — <mark class=\"m-personalizado\"><u class=\"m-clave\">Remisión</u> de una situación</mark> por <mark class=\"m-autoridad\">un Estado Parte</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3744,1-ia-4190,1-ia-4191\">🎯 3 preguntas más de este artículo</mark>"],["Artículos 15 y 15 bis — El fiscal y el crimen de agresión · R21 R22 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R21</span> <span class=\"ex-sello ex-sello-r\">R22</span>","<p data-ex=\"*\" data-r=\"R21\"><span class=\"ex-sello ex-sello-r\">R21</span> <b>Art. 15.</b> <mark class=\"m-destacable\">1. El</mark> <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-resp\" data-q=\"1-ia-3745,1-ia-3746,1-181\">iniciar de oficio una investigación sobre la base de información acerca de un crimen de la competencia de la Corte</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">2. E\u0007 l fiscal analizará la veracidad de la información recibida. Con tal fin, podrá recabar más información de los Estados, los órganos de la Naciones Unidas, las organizaciones intergubernamentales o no guber- namentales u otras fuentes fidedignas que considere apropiadas y podrá recibir testimonios escritos y orales en la sede de la Corte.</span></span> 3. <mark class=\"m-autoridad\">El fiscal,</mark> si <mark class=\"m-personalizado\">llegare a la conclusión</mark> de que existe <span class=\"m-circulo\"><mark class=\"m-personalizado\">fundamento</mark></span> <mark class=\"m-personalizado\">suficiente</mark> para abrir una investigación, <mark class=\"m-accion\">presentará</mark> <mark class=\"m-personalizado\">a la</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3747,1-ia-3830,1-ia-3836\">Sala de Cuestiones Preliminares</mark> <mark class=\"m-personalizado\">una petición de autorización para</mark> ello <span class=\"ex-plg\"><span class=\"ex-plg-t\">, junto con la documentación justificativa que haya reunido</span></span>. Las víctimas <mark class=\"m-accion\">podrán presentar</mark> observaciones <span class=\"ex-plg\"><span class=\"ex-plg-t\">a la Sala de Cuestiones Preliminares, de conformidad con las Reglas de Procedimiento y Prueba. 4. S\u0007 i, tras haber examinado la petición y la documentación que la justifique, la Sala de Cuestiones Preliminares considerare que hay fundamento suficiente para abrir una investigación y que el asunto parece corresponder a la competencia de la Corte, autorizará el inicio de la investigación, sin perjuicio de las resoluciones que pueda adoptar posteriormente la Corte con respecto a su competencia y la admisibilidad de la causa. R21</span></span>. 5. La negativa de la <mark class=\"m-autoridad\">Sala</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de Cuestiones Preliminares a autorizar la investigación</span></span> <mark class=\"m-accion\">no impedirá</mark> que el <mark class=\"m-autoridad\">fiscal presente ulteriormente</mark> otra petición basada en nuevos hechos o pruebas <span class=\"ex-plg\"><span class=\"ex-plg-t\">relacionadas con la misma situación</span></span>. <mark class=\"m-resp ex-q\" data-q=\"1-180,1-ia-3748,1-ia-3749\">🎯 3 preguntas</mark></p><p data-ex=\"*\" data-r=\"R22\"><span class=\"ex-sello ex-sello-r\">R22</span> <b>Art. 15 bis.</b> 2. <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">únicamente podrá</mark> <mark class=\"m-personalizado\">ejercer su competencia</mark> respecto de <mark class=\"m-personalizado\">crímenes de agresión</mark> cometidos <mark class=\"m-resp\" data-q=\"1-151,1-ia-3750,1-ia-4223\">un año después de la ratificación o aceptación de las enmiendas por treinta Estados Partes</mark>. 3. <span class=\"ex-plg\"><span class=\"ex-plg-t\">\u0007La Corte ejercerá su competencia respecto del crimen de agresión de conformidad con el presente artí- culo,</span></span> <mark class=\"m-autoridad\">a condición</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">que se</mark> <mark class=\"m-personalizado\">adopte</mark> una <mark class=\"m-autoridad\"><u class=\"m-clave\">decisión</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">después</u> del</mark> <mark class=\"m-autoridad\">1</mark> <mark class=\"m-personalizado\">de enero de 2017</mark> por <mark class=\"m-autoridad\">la</mark> misma mayoría <span class=\"ex-plg\"><span class=\"ex-plg-t\">de Estados Partes</span></span> que se <mark class=\"m-personalizado\">requiere</mark> <mark class=\"m-autoridad\">para</mark> <mark class=\"m-personalizado\">la</mark> aprobación <mark class=\"m-plazo\">de una</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">enmienda</mark></span> al <mark class=\"m-plazo\">Estatuto</mark> <mark class=\"m-autoridad\">(mayoría de 2/3).</mark> 4. <span class=\"ex-plg\"><span class=\"ex-plg-t\">La Corte podrá, de conformidad con el artículo 12, ejercer su competencia sobre un crimen de agresión, resultante de un acto de agresión cometido por un Estado Parte, salvo que ese Estado Parte haya declarado previamente que no acepta esa competencia mediante el depósito de una declaración en poder del Secretario.</span></span> <mark class=\"m-personalizado\">La retirada de esa declaración</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">podrá efectuarse en cualquier momento y</span></span> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">considerada <u class=\"m-clave\">por el</u></mark> <mark class=\"m-autoridad\">Estado Parte</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">en</u> un plazo de tres años.</mark></p><p><b><mark class=\"m-personalizado\">5.</mark></b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Respecto</u></mark> de un <mark class=\"m-autoridad\">Estado</mark> no Parte en el presente Estatuto, <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3554,1-ia-3713,1-ia-3741,1-ia-3753\">no ejercerá su competencia respecto del crimen de agresión cuando éste sea cometido por los nacionales de ese Estado o en el territorio del mismo</mark>.</p><p><b>6.</b> El <mark class=\"m-autoridad\">Fiscal</mark> (…) <mark class=\"m-accion\">verificará</mark> <mark class=\"m-personalizado\">en</mark> primer lugar si el <mark class=\"m-autoridad\">Consejo</mark> de Seguridad ha determinado <mark class=\"m-autoridad\">la existencia</mark> de un acto de agresión (…). <mark class=\"m-personalizado\">8.</mark> <mark class=\"m-plazo\">Cuando no</mark> <mark class=\"m-personalizado\">se realice dicha</mark> determinación en el plazo de <mark class=\"m-resp\" data-q=\"1-182\">seis meses</mark> desde <mark class=\"m-personalizado\">la fecha de notificación, el</mark> <mark class=\"m-autoridad\">Fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">iniciar los procedimientos</mark> de investigación respecto de un crimen de agresión, <mark class=\"m-personalizado\">siempre</mark> <mark class=\"m-autoridad\">y cuando la Sección</mark> de Cuestiones Preliminares (…) <mark class=\"m-personalizado\">haya autorizado el inicio</mark> de la investigación (…), y el <mark class=\"m-autoridad\">Consejo</mark> de Seguridad no haya decidido lo contrario de conformidad con el artículo 16. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3754\">🎯 1 pregunta</mark></p>"],["Artículos 16 y 17 — Suspensión por el Consejo de Seguridad y cuestiones de admisibilidad <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 16.</b> <mark class=\"m-personalizado\">En caso de que</mark> el <mark class=\"m-autoridad\">Consejo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de Seguridad, de conformidad con una resolución aprobada con arreglo a lo dispuesto en el Capítulo VII de la Carta de las Naciones</span></span> Unidas, pida a <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">que no inicie o</mark> que suspenda <mark class=\"m-resp\" data-q=\"1-152\">por un plazo de doce meses</mark> la investigación o <mark class=\"m-personalizado\">el enjuiciamiento que haya iniciado, la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">procederá</mark> <mark class=\"m-personalizado\">a esa suspensión</mark>; la petición <mark class=\"m-resp\" data-q=\"1-152,1-ia-3757\">podrá ser renovada por el Consejo de Seguridad en las mismas condiciones</mark>.</p><p data-ex=\"*\"><b>Art. 17.</b> 1. <mark class=\"m-autoridad\">La Corte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">ARTÍCULO 17. CUESTIONES DE ADMISIBILIDAD. 1. L\u0007 a Corte, teniendo en cuenta el décimo párrafo del preámbulo y el artículo 1,</span></span> <mark class=\"m-accion\">resolverá</mark> la inadmisibilidad de un asunto <mark class=\"m-personalizado\">cuando:</mark> <mark class=\"m-destacable\">a) el</mark> <mark class=\"m-personalizado\">asunto</mark> sea objeto de una <mark class=\"m-personalizado\">investigación o enjuiciamiento por</mark> <mark class=\"m-autoridad\">un Estado</mark> <mark class=\"m-personalizado\">que tenga jurisdicción</mark> sobre él, salvo que éste <mark class=\"m-personalizado\">no esté dispuesto a</mark> llevar a cabo la investigación o el enjuiciamiento o no <mark class=\"m-personalizado\">pueda realmente hacerlo;</mark> b) <span class=\"ex-plg\"><span class=\"ex-plg-t\">) \u0007El asunto haya sido objeto de investigación por un Estado que tenga jurisdicción sobre él y éste haya decidido no incoar acción penal contra la persona de que se trate, salvo que la decisión haya obedecido a que no esté dispuesto a llevar a cabo el enjuiciamiento o no pueda realmente hacerlo</span></span>; c) <mark class=\"m-personalizado\">la persona</mark> de que se trate haya sido <mark class=\"m-personalizado\">ya enjuiciada</mark> por la conducta a que se refiere la denuncia <span class=\"ex-plg\"><span class=\"ex-plg-t\">, y la Corte no pueda adelantar el juicio con arreglo a lo dispuesto en el párrafo 3 del artículo 20</span></span>; d) <mark class=\"m-personalizado\">el asunto</mark> no sea <mark class=\"m-personalizado\">de gravedad suficiente</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">para justificar la adopción de otras medidas por la Corte</span></span>. <mark class=\"m-resp ex-q\" data-q=\"1-208,1-ia-3758\">🎯 2 preguntas</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">A fin de</mark> <mark class=\"m-destacable\">determinar la</mark> <mark class=\"m-personalizado\">incapacidad para investigar o enjuiciar</mark> (…), la <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">examinará</mark> si el <mark class=\"m-autoridad\">Estado,</mark> debido al <mark class=\"m-personalizado\"><u class=\"m-clave\">colapso</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">total o sustancial</mark></span> <mark class=\"m-personalizado\">de su administración</mark> nacional <mark class=\"m-personalizado\">de justicia</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark></span></span> al hecho de que <mark class=\"m-personalizado\">carece de ella,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3802\">no puede hacer comparecer al acusado, no dispone de las pruebas y los testimonios necesarios o no está por otras razones en condiciones de llevar a cabo el juicio</mark>.</p>"],["Artículo 17 — Cuestiones de admisibilidad","<p><b>b)</b> El asunto haya sido objeto <span class=\"ex-plg\"><span class=\"ex-plg-t\">de investigación por un Estado que tenga jurisdicción sobre él y éste haya decidido no incoar acción penal contra la persona de que se trate, salvo que la</span></span> decisión haya obedecido a que <mark class=\"m-resp r-ia\" data-q=\"1-ia-3759\">no esté dispuesto a llevar a cabo el enjuiciamiento o no pueda realmente hacerlo</mark>;</p><p><b>d)</b> El <mark class=\"m-resp r-ia\" data-q=\"1-ia-3760,1-ia-4224\">asunto no sea de gravedad suficiente para justificar la adopción de otras medidas por la Corte</mark>.</p><p><b>a)</b> Que el juicio ya haya <span class=\"ex-plg\"><span class=\"ex-plg-t\">estado o esté en marcha o que la decisión nacional haya sido</span></span> adoptada con el propósito de <mark class=\"m-resp r-ia\" data-q=\"1-ia-3761\">sustraer a la persona de que se trate de su responsabilidad penal por crímenes de la competencia de la Corte</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">según lo dispuesto en el artículo</span></span> 5;</p><p><b>b)</b> Que haya habido una demora <span class=\"ex-plg\"><span class=\"ex-plg-t\">injustificada en el juicio que, dadas las</span></span> circunstancias, sea incompatible con la <mark class=\"m-resp r-ia\" data-q=\"1-ia-3762\">intención de hacer comparecer a la persona de que se trate ante la justicia</mark>;</p><p><b>c)</b> Que el proceso no haya <span class=\"ex-plg\"><span class=\"ex-plg-t\">sido o no esté siendo sustanciado de manera independiente o imparcial y haya sido o esté siendo sustanciado de forma en que, dadas las</span></span> circunstancias, sea incompatible con la <mark class=\"m-resp r-ia\" data-q=\"1-ia-3801\">intención de hacer comparecer a la persona de que se trate ante la justicia</mark>.</p>"],["Artículo 18 — Decisiones preliminares relativas a la admisibilidad · R23 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R23</span>","<p data-ex=\"*\"><b>Art. 18.</b> 1. <mark class=\"m-personalizado\">Cuando se haya remitido a</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">una situación</mark> en virtud del artículo <u class=\"m-clave\">13.a) y el</u> <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-personalizado\">haya determinado</mark> que existen <mark class=\"m-personalizado\"><u class=\"m-clave\">fundamentos</u> razonables</mark> para comenzar una investigación, o el <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-personalizado\">inicia una investigación</mark> en virtud de los artículos 13.c) y 15, éste <mark class=\"m-accion\">lo notificará</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3113\">a todos los Estados Partes y a aquellos Estados que, teniendo en cuenta la información disponible, ejercerían normalmente la jurisdicción sobre los crímenes de que se trate</mark>. <mark class=\"m-autoridad\">El fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">hacer la <u class=\"m-clave\">notificación</u></mark> a esos <mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-personalizado\">con</mark> <mark class=\"m-destacable\">carácter confidencial</mark> y, cuando lo considere necesario a <mark class=\"m-personalizado\">fin de proteger personas, impedir la destrucción de pruebas o</mark> impedir la <mark class=\"m-personalizado\">fuga</mark> de personas, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">limitar</u> el alcance de la información proporcionada a los</mark> <mark class=\"m-autoridad\">Estados.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-209,1-ia-3803\">🎯 2 preguntas</mark></p><p><b>2.</b> <mark class=\"m-resp\" data-q=\"1-276\">Dentro del mes siguiente</mark> a la recepción de dicha notificación, el <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-accion\">podrá informar</mark> a la <mark class=\"m-autoridad\">Corte</mark> que <mark class=\"m-personalizado\">está llevando</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">ha llevado a cabo una investigación</mark> en relación con sus nacionales u otras personas <mark class=\"m-personalizado\">bajo</mark> su jurisdicción respecto de actos criminales que puedan constituir crímenes contemplados en el artículo 5 y a los que se refiera la información proporcionada en la notificación a los <mark class=\"m-autoridad\">Estados.</mark> A petición de dicho <mark class=\"m-autoridad\">Estado, el fiscal</mark> <mark class=\"m-accion\">se inhibirá</mark> de su competencia en favor del <mark class=\"m-autoridad\">Estado</mark> en relación con la investigación sobre las personas antes mencionadas, a menos que la <mark class=\"m-autoridad\">Sala de Cuestiones</mark> Preliminares decida, <mark class=\"m-accion\">a</mark> petición del <mark class=\"m-autoridad\">fiscal,</mark> autorizar la investigación. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3804\">🎯 1 pregunta</mark></p><p data-r=\"R23\"><span class=\"ex-sello ex-sello-r\">R23</span> <b>3.</b> El <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">volver a examinar la cuestión de la inhibición</mark> de su competencia <mark class=\"m-resp\" data-q=\"1-ia-3805,1-182\">al cabo de seis meses a partir de la fecha de la inhibición o cuando se haya producido un cambio significativo de circunstancias</mark> en vista de que <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">Estado</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">no</mark></span> <mark class=\"m-personalizado\">está dispuesto</mark> a llevar a cabo la investigación <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">no puede realmente hacerlo.</mark></p><p><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">El Estado</mark> de que se trate <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-autoridad\">el fiscal</mark> <mark class=\"m-accion\">podrán apelar</mark> ante la <mark class=\"m-autoridad\">Sala de</mark> Apelaciones de la decisión de la <mark class=\"m-autoridad\">Sala de Cuestiones Preliminares,</mark> de conformidad con lo dispuesto en el artículo 82.</span></span> La apelación <mark class=\"m-accion\">podrá sustanciarse</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3806\">en forma sumaria</mark>.</p><p data-ex=\"*\"><b>6.</b> El <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-accion\">podrá,</mark> hasta que la <mark class=\"m-autoridad\">Sala de Cuestiones Preliminares</mark> <mark class=\"m-personalizado\">haya emitido su decisión,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o en cualquier momento si se hubiere inhibido de su competencia en virtud</span></span> de este artículo, <mark class=\"m-accion\">pedir</mark> a la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares, con carácter <mark class=\"m-resp\" data-q=\"1-210\">excepcional</mark>, que le autorice a llevar adelante las <mark class=\"m-destacable\">indagaciones</mark> que estime necesarias cuando <mark class=\"m-resp r-ia\" data-q=\"1-ia-3807\">exista una oportunidad única de obtener pruebas importantes o exista un riesgo significativo de que esas pruebas no estén disponibles ulteriormente</mark>.</p>"],["Artículo 19 — Impugnación de la competencia de la Corte o de la admisibilidad de la causa · R24 R25 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX\"><b><mark class=\"m-destacable\">Art. 19.</mark></b> 1. <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">cerciorará</mark> <mark class=\"m-personalizado\">de ser competente en</mark> todas las causas que le sean sometidas. La <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">determinar de oficio la admisibilidad</mark> de una causa de conformidad con el artículo 17. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3808\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-accion\">Podrán</mark> <mark class=\"m-destacable\">impugnar</mark> <mark class=\"m-personalizado\">la admisibilidad de la causa,</mark> por uno de los motivos mencionados en el artículo 17, o impugnar la competencia de la <mark class=\"m-autoridad\">Corte:</mark> <mark class=\"m-resp ex-q\" data-q=\"1-211\">🎯 1 pregunta</mark></p><p><b>c)</b> <mark class=\"m-personalizado\">Un</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">cuya aceptación se requiera de conformidad con el artículo 12.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3809\">🎯 1 pregunta</mark></p><p>En las actuaciones relativas a <span class=\"ex-plg\"><span class=\"ex-plg-t\">la competencia o la admisibilidad, <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">presentar asimismo observaciones</mark> a la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">quienes hayan remitido la situación</mark> de conformidad con el artículo 13 y las víctimas.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3810\">🎯 1 pregunta</mark></p><p><b>4.</b> <mark class=\"m-personalizado\">La admisibilidad de una causa o</mark> <mark class=\"m-autoridad\">la competencia de la Corte</mark> <mark class=\"m-personalizado\">sólo</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">ser impugnadas</mark> <mark class=\"m-destacable\">una</mark> sola vez por cualquiera de las personas o los <mark class=\"m-autoridad\">Estados</mark> a que se hace referencia <mark class=\"m-personalizado\">en el párrafo 2. La impugnación se</mark> <mark class=\"m-accion\">hará</mark> <mark class=\"m-personalizado\">antes del juicio o</mark> <mark class=\"m-autoridad\">a</mark> su inicio. En circunstancias excepcionales, la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">autorizar que la impugnación</mark> se haga <mark class=\"m-personalizado\"><u class=\"m-clave\">más de</u> una vez o en una fase ulterior</mark> del juicio. <mark class=\"m-personalizado\">Las impugnaciones</mark> o la admisibilidad <mark class=\"m-personalizado\">de</mark> una causa hechas <mark class=\"m-personalizado\">al inicio del juicio, o posteriormente</mark> con la autorización de la <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-resp\" data-q=\"1-65\">sólo podrán fundarse en el párrafo 1.c) del artículo 17</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3811\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Las decisiones relativas a la competencia o la admisibilidad</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">ser recurridas ante</mark> <mark class=\"m-autoridad\">la</mark> <mark class=\"m-resp\" data-q=\"1-82,1-ia-3813\">Sala de Apelaciones</mark> de conformidad con el artículo 82.</p><p data-ex=\"*\"><b>7.</b> <mark class=\"m-personalizado\">Si la impugnación es hecha por</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">el</u> Estado</mark> a que se hace referencia en los <mark class=\"m-personalizado\">apartados b) o</mark> c) del párrafo 2, <mark class=\"m-resp\" data-q=\"1-133,1-ia-3814\">el fiscal suspenderá la investigación hasta que la Corte resuelva de conformidad con el artículo 17</mark>.</p><p><b>c)</b> <mark class=\"m-personalizado\">Impedir,</mark> en cooperación con <span class=\"ex-plg\"><span class=\"ex-plg-t\">los <mark class=\"m-autoridad\">Estados</mark> que corresponda, <mark class=\"m-personalizado\">que eludan la acción de la justicia personas</mark> respecto de los cuales el <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-personalizado\">haya pedido ya una orden de detención</mark> en virtud del artículo 58.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3815\">🎯 1 pregunta</mark></p><p><b>9.</b> <mark class=\"m-personalizado\">La impugnación no</mark> <mark class=\"m-accion\">afectará</mark> <mark class=\"m-personalizado\">a la validez de ningún</mark> <mark class=\"m-destacable\">acto</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">realizado por <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">fiscal,</mark> <mark class=\"m-destacable\">ni</mark> de ninguna <mark class=\"m-destacable\">orden</mark> o mandamiento dictado por la <mark class=\"m-autoridad\">Corte,</mark> antes de ella.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3816\">🎯 1 pregunta</mark></p><p><b>10.</b> <mark class=\"m-personalizado\">Si la</mark> <mark class=\"m-autoridad\">Corte</mark> hubiere <mark class=\"m-personalizado\">declarado inadmisible</mark> una <span class=\"ex-plg\"><span class=\"ex-plg-t\">causa de conformidad con el artículo 17, <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">pedir que se revise</mark> esa decisión cuando se haya cerciorado</span></span> cabalmente de que han <mark class=\"m-personalizado\">aparecido</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3817,1-ia-3827\">nuevos hechos que invalidan los motivos por los cuales la causa había sido considerada inadmisible</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">conformidad con dicho artículo.</span></span></p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Derecho aplicable por la Corte (art. 21)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1.º</span><u class=\"m-clave\">EN PRIMER LUGAR</u>: <mark class=\"m-resp r-ia\" data-q=\"1-ia-3820,1-ia-4225\">el presente Estatuto, los Elementos de los crímenes y sus Reglas de Procedimiento y Prueba</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2.º</span><u class=\"m-clave\">EN SEGUNDO LUGAR</u>: <mark class=\"m-destacable\">tratados</mark> aplicables, <mark class=\"m-destacable\">principios</mark> y normas del <mark class=\"m-personalizado\">derecho internacional</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3.º</span><u class=\"m-clave\">EN SU DEFECTO</u>: <mark class=\"m-destacable\">principios</mark> generales del <mark class=\"m-personalizado\">derecho</mark> que <mark class=\"m-personalizado\">derive la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">del derecho interno</mark> de los sistemas jurídicos <mark class=\"m-personalizado\">del mundo</mark></div></div></div><div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Cosa juzgada (art. 20)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Non bis in idem</div><div class=\"vis-ramas\"><div class=\"vis-rama\"><mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">procesado por</mark> <mark class=\"m-autoridad\">la Corte</mark> por crímenes por los que ya hubiere <u class=\"m-clave\">sido</u> <mark class=\"m-personalizado\">condenado</mark> o <u class=\"m-clave\">absuelto</u> <mark class=\"m-autoridad\">por la Corte</mark></div><div class=\"vis-rama\"><mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">procesado por</mark> <mark class=\"m-autoridad\">otro tribunal</mark> por crímenes del <mark class=\"m-personalizado\">art</mark>. 5 por los que <mark class=\"m-autoridad\">la Corte</mark> ya le condenó o absolvió</div><div class=\"vis-rama\"><mark class=\"m-autoridad\">La Corte</mark> <u class=\"m-clave\">no</u> <mark class=\"m-accion\">procesará</mark> a quien ya fue <mark class=\"m-personalizado\">procesado por</mark> <mark class=\"m-autoridad\">otro tribunal</mark>, <u class=\"m-clave\">a menos que</u> el proceso:<div class=\"vis-sub\"><span>a) <mark class=\"m-resp r-ia\" data-q=\"1-ia-3818,1-ia-3819,1-ia-3820,1-ia-4225\">Obedeciera al propósito de sustraer al acusado de su responsabilidad penal</mark></span><span>b) <mark class=\"m-resp r-ia\" data-q=\"1-ia-3818,1-ia-3819\">No hubiere sido instruido en forma independiente o imparcial</mark></span></div></div></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículos</mark> 20 y 21 — <mark class=\"m-destacable\">Cosa <u class=\"m-clave\">juzgada</u></mark> y <mark class=\"m-personalizado\">derecho</mark> aplicable: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3821\">🎯 1 pregunta más de este artículo</mark>"],["Artículos 53 y 54 — Inicio de la investigación y atribuciones del fiscal <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 53.</b> 1. <mark class=\"m-autoridad\">El fiscal</mark>, <mark class=\"m-personalizado\">después de evaluar la información</mark> de que disponga, <mark class=\"m-accion\">iniciará</mark> <mark class=\"m-personalizado\">una investigación</mark>, a <mark class=\"m-personalizado\">menos</mark> que determine que no <mark class=\"m-personalizado\">existe fundamento razonable</mark> para proceder a ella <span class=\"ex-plg\"><span class=\"ex-plg-t\">con arreglo al presente Estatuto</span></span>. <mark class=\"m-personalizado\">Al decidir</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">si ha de iniciar una investigación, el fiscal</span></span> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">en cuenta si:</mark> a) <span class=\"ex-plg\"><span class=\"ex-plg-t\">) \u0007La información de que dispone constituye</span></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">fundamento</u></mark> <mark class=\"m-destacable\">razonable</mark> <mark class=\"m-personalizado\">para creer</mark> que se ha <mark class=\"m-personalizado\">cometido</mark> o se está cometiendo un crimen de la competencia de la <mark class=\"m-autoridad\">Corte</mark>; b) <mark class=\"m-personalizado\">la causa es o sería</mark> <mark class=\"m-destacable\">admisible</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el artículo 17</span></span>; c) <mark class=\"m-personalizado\">existen</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">razones</u> sustanciales</mark> <mark class=\"m-personalizado\">para creer</mark> que <span class=\"ex-plg\"><span class=\"ex-plg-t\">, aun teniendo en cuenta la gravedad del crimen y los intereses de las víctimas,</span></span> <mark class=\"m-personalizado\">una investigación <u class=\"m-clave\">no redundaría</u> en interés de la justicia</mark>. (…) <mark class=\"m-resp ex-q\" data-q=\"1-212,1-ia-3823\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>3.</b> a) <mark class=\"m-personalizado\">A petición</mark> del <mark class=\"m-autoridad\">Estado que haya remitido</mark> el asunto <span class=\"ex-plg\"><span class=\"ex-plg-t\">con arreglo al artículo 14</span></span> <mark class=\"m-destacable\">o</mark> <mark class=\"m-autoridad\">del Consejo de Seguridad</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el párrafo b) del artículo 13</span></span>, <mark class=\"m-autoridad\">la Sala de Cuestiones Preliminares</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">examinar</mark> la <mark class=\"m-personalizado\">decisión del</mark> <mark class=\"m-autoridad\">fiscal</mark> de no proceder a la investigación <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el párrafo 1 o el párrafo 2</span></span> y <mark class=\"m-accion\">pedir</mark> al <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-personalizado\">que reconsidere esa decisión.</mark> b) <mark class=\"m-personalizado\">Además, la</mark> <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-personalizado\">de Cuestiones Preliminares</mark> <mark class=\"m-accion\">podrá,</mark> <mark class=\"m-resp\" data-q=\"1-181\">de oficio</mark>, <mark class=\"m-personalizado\">revisar una decisión del</mark> <mark class=\"m-autoridad\">fiscal de</mark> <span class=\"m-caja\">no proceder a la investigación</span> <mark class=\"m-resp r-vec\" data-q=\"1-181\">si dicha decisión se basare únicamente en el párrafo 1.c), o el párrafo 2.c)</mark> (interés de la justicia). En ese caso, <mark class=\"m-personalizado\">la decisión</mark> del <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3824,1-ia-3826\">únicamente surtirá efecto si es confirmada por la Sala de Cuestiones Preliminares</mark>.</p><p data-ex=\"*\"><b>a)</b> A <mark class=\"m-personalizado\">fin de establecer la veracidad</mark> de los hechos, <mark class=\"m-accion\">ampliará</mark> <mark class=\"m-personalizado\">la investigación a todos los hechos y las pruebas</mark> que sean pertinentes para <mark class=\"m-personalizado\">determinar</mark> si hay <mark class=\"m-personalizado\">responsabilidad penal</mark> de conformidad con el presente Estatuto <mark class=\"m-personalizado\">y,</mark> a esos efectos, <mark class=\"m-accion\">investigará</mark> <mark class=\"m-resp\" data-q=\"1-ia-3828,1-214\">tanto las circunstancias incriminantes como las eximentes</mark>;</p><p data-ex=\"*\"><b>b)</b> <mark class=\"m-accion\">Adoptará</mark> <mark class=\"m-personalizado\">medidas</mark> adecuadas para <mark class=\"m-personalizado\">asegurar la eficacia de la investigación y el enjuiciamiento</mark> de los crímenes de la competencia de la <mark class=\"m-autoridad\">Corte.</mark> A esos efectos, <mark class=\"m-accion\">respetará</mark> <mark class=\"m-personalizado\">los intereses y las circunstancias</mark> personales de <mark class=\"m-personalizado\"><u class=\"m-clave\">víctimas y testigos,</u></mark> entre otros, <mark class=\"m-personalizado\">la edad, el género,</mark> definido en el párrafo 3 del artículo <mark class=\"m-personalizado\">7, y la salud,</mark> y <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">en cuenta la naturaleza de los crímenes, en particular</mark> los de <mark class=\"m-resp\" data-q=\"1-ia-3829,1-215\">violencia sexual, violencia por razones de género y violencia contra los niños</mark>, <mark class=\"m-personalizado\">y</mark></p><p data-ex=\"*\"><b>b)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Hacer comparecer e interrogar</u></mark> a las personas objeto de investigación, las víctimas y los <mark class=\"m-resp\" data-q=\"1-216\">testigos</mark>;</p><p><b>d)</b> <mark class=\"m-resp r-vec\" data-q=\"1-107\">Concertar</mark> <mark class=\"m-personalizado\">las disposiciones o los acuerdos</mark> compatibles con el presente Estatuto que sean <mark class=\"m-personalizado\">necesarios para facilitar la cooperación</mark> de <mark class=\"m-resp\" data-q=\"1-107\">un Estado, una organización intergubernamental o una persona</mark>;</p><p data-ex=\"*\"><b>e)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Convenir</u> en <u class=\"m-clave\">que no</u></mark> <mark class=\"m-accion\">divulgará</mark> <mark class=\"m-personalizado\">en ninguna etapa del procedimiento los documentos o la información</mark> que obtenga a condición de <mark class=\"m-personalizado\">preservar su carácter confidencial</mark> y, <span class=\"m-caja\">únicamente,</span> a los efectos de <mark class=\"m-personalizado\">obtener nuevas pruebas, salvo</mark> <mark class=\"m-resp\" data-q=\"1-ia-3831,1-217\">con el acuerdo de quien haya facilitado la información</mark>, y</p>"],["Artículos 55 y 57 — Derechos durante la investigación y Sala de Cuestiones Preliminares <span class=\"ex-sello\">✱</span>","<p><b>a)</b> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3832\">Nadie será obligado a declarar contra sí mismo ni a declararse culpable</mark>;</p><p><b>d)</b> <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">sometido a arresto o detención arbitrarios ni</mark> <mark class=\"m-accion\">será</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">privado de su libertad salvo por los motivos previstos</mark> en el presente <mark class=\"m-personalizado\">Estatuto</mark> y de conformidad con los procedimientos establecidos en él.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3833\">🎯 1 pregunta</mark></p><p><b>b)</b> <mark class=\"m-personalizado\">A guardar <u class=\"m-clave\">silencio,</u></mark> <mark class=\"m-resp\" data-q=\"1-155,1-ia-3834\">sin que ello pueda tenerse en cuenta a los efectos de determinar su culpabilidad o inocencia</mark>;</p><p data-ex=\"*\"><b>d)</b> <mark class=\"m-personalizado\">A ser <u class=\"m-clave\">interrogada</u> en presencia de su</mark> <mark class=\"m-autoridad\">abogado,</mark> <mark class=\"m-personalizado\">a menos que haya</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">renunciado</u> voluntariamente</mark> a su derecho a asistencia letrada. <mark class=\"m-resp ex-q\" data-q=\"1-218,1-ia-3835\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 57.</b> 2. a) <mark class=\"m-destacable\">Las providencias u órdenes</mark> <mark class=\"m-personalizado\">que</mark> <mark class=\"m-autoridad\">la Sala de Cuestiones Preliminares</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">dicte en virtud de los artículos 15, 18 o 19, el párrafo 2 del artículo 54, el párrafo 7 del artículo 61</span></span> o el artículo <mark class=\"m-destacable\">72,</mark> <mark class=\"m-accion\">deberán</mark> ser aprobadas <mark class=\"m-personalizado\">por</mark> <mark class=\"m-resp\" data-q=\"1-ia-3839,1-219\">la mayoría de los magistrados que la componen</mark>. b) En todos los demás casos, un <mark class=\"m-autoridad\">magistrado de la Sala de Cuestiones Preliminares</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">ejercer las</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">funciones</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">establecidas en el presente Estatuto, a menos que las Reglas de Procedimiento y Prueba dispongan otra cosa o así lo acuerde, por mayoría la Sala de Cuestiones Preliminares</span></span></span>.</p><p><b>57.3.</b> Además de otras <mark class=\"m-destacable\">funciones</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que le confiere el presente Estatuto, <mark class=\"m-autoridad\">la Sala de Cuestiones Preliminares</mark> <mark class=\"m-accion\">podrá:</mark> a) <mark class=\"m-destacable\">A petición del</mark> <mark class=\"m-autoridad\">fiscal,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">dictar las providencias</u></mark> y <mark class=\"m-personalizado\">órdenes</mark> que sean <mark class=\"m-personalizado\">necesarias</mark> a los fines de una <mark class=\"m-personalizado\">investigación.</mark> b) <mark class=\"m-destacable\">A</mark> <mark class=\"m-personalizado\">petición de quien haya sido detenido o haya comparecido</mark> en virtud de una orden de comparecencia expedida con <mark class=\"m-personalizado\">arreglo al artículo 58,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">dictar esas órdenes,</u></mark> <mark class=\"m-personalizado\">incluidas medidas</mark> tales como las indicadas en el artículo 56 o solicitar, con arreglo a la Parte <mark class=\"m-personalizado\">IX,</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">la cooperación</u></mark> que sea necesaria <mark class=\"m-personalizado\">para ayudarle a preparar su defensa.</mark> c) <mark class=\"m-personalizado\">Cuando sea necesario, asegurar la</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">protección</u></mark> y <mark class=\"m-personalizado\"><u class=\"m-clave\">el respeto</u></mark> <mark class=\"m-personalizado\">de la intimidad de víctimas y testigos, la</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">preservación</u></mark> <mark class=\"m-personalizado\">de pruebas, la</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">protección</mark></span> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-autoridad\">personas</mark> <mark class=\"m-personalizado\">detenidas o que hayan comparecido</mark> en virtud de una orden de comparecencia, así como la <mark class=\"m-personalizado\">protección</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">de información</u></mark> que afecte a la <mark class=\"m-personalizado\">seguridad nacional.</mark> d) Autorizar al <mark class=\"m-autoridad\">fiscal a</mark> adoptar determinadas <mark class=\"m-personalizado\">medidas de investigación en el territorio de</mark> <mark class=\"m-autoridad\">un Estado</mark> Parte sin <mark class=\"m-destacable\">haber obtenido la cooperación de éste</mark> con arreglo a la Parte <mark class=\"m-personalizado\">IX en el caso de</mark> que <mark class=\"m-autoridad\">la Sala</mark> <mark class=\"m-personalizado\">haya determinado,</mark> de <span class=\"m-caja\">ser</span> <mark class=\"m-personalizado\">posible teniendo en cuenta las opiniones</mark> <mark class=\"m-autoridad\">del Estado</mark> de que se trate, que dicho <mark class=\"m-autoridad\">Estado</mark> manifiestamente <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u></mark> <mark class=\"m-personalizado\">está</mark> en <mark class=\"m-personalizado\">condiciones de cumplir</mark> una solicitud de cooperación debido a que <mark class=\"m-personalizado\">no existe</mark> <mark class=\"m-autoridad\">autoridad u órgano</mark> alguno de su sistema <mark class=\"m-personalizado\">judicial</mark> competente para <span class=\"m-caja\">cumplir</span> <mark class=\"m-personalizado\">una solicitud de cooperación</mark> con arreglo a la Parte IX. e) <mark class=\"m-personalizado\">Cuando</mark> se haya <mark class=\"m-personalizado\">dictado</mark> una <mark class=\"m-personalizado\">orden de detención o de comparecencia</mark> con arreglo al artículo 58, y <span class=\"m-caja\">habida cuenta</span> del valor de <mark class=\"m-personalizado\">las pruebas</mark> y de <mark class=\"m-personalizado\">los derechos de las partes</mark> de que se trate, de conformidad con lo dispuesto en el <mark class=\"m-personalizado\">presente</mark> Estatuto y las Reglas de Procedimiento y Prueba, <mark class=\"m-personalizado\"><u class=\"m-clave\">recabar la</u></mark> <mark class=\"m-personalizado\">cooperación de</mark> <mark class=\"m-autoridad\">los Estados</mark> con arreglo al párrafo 1.k) del artículo 93 <mark class=\"m-personalizado\">para adoptar medidas cautelares a</mark> los efectos de <mark class=\"m-personalizado\">un decomiso</mark> que, en particular, beneficie en última instancia a las víctimas.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3840,1-ia-3841,1-ia-3842\">🎯 3 preguntas</mark></p>"],["Artículo 56 — Medidas de la Sala de Cuestiones Preliminares ante una oportunidad única de investigar <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b><mark class=\"m-autoridad\">Art. 56.</mark></b> <b><mark class=\"m-autoridad\">b)</mark></b> <mark class=\"m-autoridad\">La Sala,</mark> a <mark class=\"m-autoridad\">petición del fiscal,</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">adoptar las medidas</mark> que sean necesarias para <span class=\"m-caja\"><mark class=\"m-personalizado\">velar por la</mark></span> <mark class=\"m-destacable\">eficiencia e integridad</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">de las actuaciones y, en particular,</mark></span> para proteger los derechos de <mark class=\"m-autoridad\">la</mark> <mark class=\"m-resp\" data-q=\"1-220\">defensa</mark>.</p><p data-ex=\"*\"><b>a)</b> La <mark class=\"m-autoridad\">Sala de</mark> Cuestiones Preliminares, cuando considere <mark class=\"m-personalizado\">que</mark> el <mark class=\"m-autoridad\">fiscal</mark> no <mark class=\"m-personalizado\">ha <u class=\"m-clave\">solicitado</u> medidas</mark> previstas en el presente artículo que, a su juicio, sean <mark class=\"m-destacable\"><u class=\"m-clave\">esenciales</u> para la</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">defensa en</mark></span> juicio, <mark class=\"m-personalizado\">le</mark> <mark class=\"m-accion\">consultará</mark> <mark class=\"m-personalizado\">si se justificaba no haberlas solicitado. La</mark> <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">adoptar de oficio esas medidas</mark> si, tras la consulta, <mark class=\"m-personalizado\">llegare a la conclusión de que no había justificación</mark> para no solicitarlas. <mark class=\"m-resp ex-q\" data-q=\"1-221\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 56 — Disposiciones que <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">adoptar</mark> <mark class=\"m-autoridad\">la sala de cuestiones preliminares</mark> <mark class=\"m-personalizado\">cuando se</mark> <mark class=\"m-personalizado\">presente</mark> una oportunidad única de <mark class=\"m-personalizado\">proceder</mark> a <mark class=\"m-personalizado\">una investigación</mark> (texto completo): <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3837,1-ia-3838\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 58 y 59 — Orden de detención o de comparecencia y procedimiento en el Estado de detención · R26 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R26</span>","<p data-ex=\"EXOF\"><b>Art. 58.</b> 1. En cualquier momento <mark class=\"m-destacable\">después de iniciada la</mark> <mark class=\"m-resp\" data-q=\"1-169\">investigación</mark>, la <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-destacable\">de Cuestiones Preliminares</mark> <mark class=\"m-accion\">dictará,</mark> a <span class=\"m-caja\"><mark class=\"m-plazo\">solicitud del</mark></span> <mark class=\"m-autoridad\">fiscal,</mark> una <mark class=\"m-plazo\">orden</mark> de <mark class=\"m-personalizado\">detención contra una persona</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">si,</u></mark> tras examinar la <mark class=\"m-personalizado\">solicitud y las pruebas y otra información</mark> <mark class=\"m-autoridad\">presentadas por el</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">fiscal,</mark></span> <mark class=\"m-personalizado\">estuviere convencida de que:</mark></p><p><b><mark class=\"m-personalizado\">b)</mark></b> <mark class=\"m-personalizado\">La detención</mark> parece <mark class=\"m-personalizado\"><u class=\"m-clave\">necesaria</u> para:</mark> <mark class=\"m-resp ex-q\" data-q=\"1-153\">🎯 1 pregunta</mark></p><p><b>iii)</b> En su caso, <mark class=\"m-personalizado\">impedir que</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">la persona <mark class=\"m-personalizado\">siga cometiendo ese crimen o un crimen conexo</mark> que sea de la competencia de la <mark class=\"m-autoridad\">Corte</mark> y <mark class=\"m-personalizado\">tenga</mark> su origen en las mismas circunstancias.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3843\">🎯 1 pregunta</mark></p><p><b>e)</b> <mark class=\"m-personalizado\">La razón</mark> <mark class=\"m-autoridad\">por la cual el fiscal</mark> <mark class=\"m-personalizado\">crea necesaria la detención.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3844\">🎯 1 pregunta</mark></p><p><b>4.</b> La orden de detención <mark class=\"m-resp r-ia\" data-q=\"1-ia-3845\">seguirá en vigor mientras la Corte no disponga lo contrario</mark>.</p><p><b>6.</b> <mark class=\"m-autoridad\">El fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">pedir a</mark> <mark class=\"m-autoridad\">la Sala de Cuestiones Preliminares</mark> <mark class=\"m-personalizado\">que enmiende la orden de detención para modificar la referencia al crimen indicado en ésta o agregar otros.</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">La Sala</mark> de Cuestiones Preliminares <mark class=\"m-accion\">enmendará</mark></span></span> la orden <mark class=\"m-personalizado\">si estuviere convencida</mark> de que <mark class=\"m-resp r-ia\" data-q=\"1-ia-3339,1-ia-3847\">hay motivo razonable para creer que la persona cometió los crímenes en la forma que se indica en esa modificación o adición</mark>.</p><p data-ex=\"*\" data-r=\"R26\"><span class=\"ex-sello ex-sello-r\">R26</span> <b>7.</b> <mark class=\"m-autoridad\">El fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">pedir a</mark> <mark class=\"m-autoridad\">la Sala de Cuestiones Preliminares</mark> <mark class=\"m-personalizado\">que, en lugar de una orden de detención, dicte una</mark> <mark class=\"m-destacable\">orden</mark> <mark class=\"m-personalizado\">de comparecencia.</mark> <mark class=\"m-autoridad\">La Sala,</mark> de estar convencida de que hay <mark class=\"m-personalizado\">motivo razonable para creer</mark> que la persona <mark class=\"m-personalizado\">ha cometido el crimen</mark> que se le imputa y <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">bastará</mark> <mark class=\"m-personalizado\">con una orden de comparecencia para</mark> asegurar <mark class=\"m-personalizado\">que comparezca</mark> <span class=\"m-caja\">efectivamente,</span> <mark class=\"m-accion\">dictará,</mark> <mark class=\"m-personalizado\">con o sin las condiciones limitativas de la libertad</mark> (distintas de <mark class=\"m-personalizado\">la detención),</mark> que prevea el derecho interno, <mark class=\"m-personalizado\">una orden para que la persona comparezca.</mark> La orden de comparecencia <mark class=\"m-accion\">consignará:</mark> <mark class=\"m-resp ex-q\" data-q=\"1-183\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>b)</b> <mark class=\"m-resp\" data-q=\"1-154\">La fecha de la comparecencia</mark>;</p><p>La <mark class=\"m-personalizado\">notificación</mark> de la orden <mark class=\"m-accion\">será</mark> <mark class=\"m-resp\" data-q=\"1-306\">personal</mark>.</p><p data-ex=\"*\"><b>4.</b> <mark class=\"m-personalizado\">Al decidir la solicitud,</mark> <mark class=\"m-autoridad\">la autoridad competente del Estado de detención</mark> <mark class=\"m-accion\">examinará</mark> <mark class=\"m-destacable\">si,</mark> dada la <mark class=\"m-personalizado\">gravedad de los</mark> presuntos <mark class=\"m-personalizado\">crímenes, hay circunstancias urgentes y excepcionales que justifiquen la libertad provisional <u class=\"m-clave\">y</u> si existen las salvaguardias necesarias</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">para que el Estado de detención pueda cumplir su obligación de entregar la persona a la Corte</span></span>. Esa <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-resp\" data-q=\"1-ia-3849,1-ia-3902,1-222\">no podrá examinar si la orden de detención fue dictada conforme a derecho con arreglo a los apartados a) y b) del párrafo 1 del artículo 58</mark>.</p><p><b>5.</b> <mark class=\"m-personalizado\">La solicitud de libertad</mark> <span class=\"m-caja\">provisional</span> <span class=\"m-caja\"><mark class=\"m-accion\">será</mark></span> <mark class=\"m-personalizado\">notificada a</mark> <mark class=\"m-autoridad\">la</mark> <mark class=\"m-resp\" data-q=\"1-89,1-156\">Sala de Cuestiones Preliminares</mark>, <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">hará</mark> recomendaciones a la <mark class=\"m-autoridad\">autoridad competente del Estado de detención.</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Antes de adoptar su decisión, la autoridad competente del Estado de detención tendrá plenamente en cuenta esas recomendaciones, incluidas las relativas a medidas para impedir la evasión de la persona.</span></span></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q\" data-q=\"1-153\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículos 60 y 61 — Primeras diligencias en la Corte y confirmación de los cargos <span class=\"ex-sello\">✱</span>","<p><b>Art. 60.</b> 1. <mark class=\"m-personalizado\">Una vez</mark> que el <span class=\"ex-plg\"><span class=\"ex-plg-t\">imputado haya sido <mark class=\"m-personalizado\">entregado</mark> a la <mark class=\"m-autoridad\">Corte</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">o</mark></span> haya <mark class=\"m-personalizado\">comparecido voluntariamente</mark> o en cumplimiento de una orden de comparecencia, <mark class=\"m-autoridad\">la Sala de Cuestiones Preliminares</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">asegurará</mark> de que ha sido <mark class=\"m-personalizado\">informado de los crímenes</mark> que le son imputados <mark class=\"m-personalizado\">y de los derechos</mark> que le reconoce el presente Estatuto, <mark class=\"m-personalizado\">incluido el de pedir la libertad provisional.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3905\">🎯 1 pregunta</mark></p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Quien sea objeto de una orden de detención <mark class=\"m-accion\">podrá pedir</mark> la libertad provisional. Si la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares está convencida de que se dan las condiciones enunciadas <mark class=\"m-personalizado\">en</mark> el párrafo 1 del artículo 58, <mark class=\"m-accion\">se mantendrá</mark> la detención.</span></span> En caso contrario, la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares <mark class=\"m-resp r-ia\" data-q=\"1-ia-3906\">pondrá en libertad al detenido, con o sin condiciones</mark>.</p><p><b>3.</b> La <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">revisará</mark> periódicamente <mark class=\"m-destacable\">su decisión</mark> en cuanto a la puesta en libertad o la detención, y <mark class=\"m-accion\">podrá hacerlo</mark> en cualquier</span></span> momento en que lo solicite <mark class=\"m-resp r-ia\" data-q=\"1-ia-3907\">el fiscal o el detenido</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">Sobre la base de la revisión, la <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-accion\">podrá modificar</mark> su decisión en cuanto a la detención, la puesta en libertad o las condiciones de ésta, si está convencida de que es <mark class=\"m-personalizado\">necesario</mark> en razón de un cambio en las circunstancias.</span></span></p><p><b>4.</b> La <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">se asegurará</mark> de que la <mark class=\"m-personalizado\">detención <u class=\"m-clave\">en</u> espera de juicio no se prolongue excesivamente</mark> a causa de una <mark class=\"m-destacable\"><u class=\"m-clave\">demora</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">inexcusable del</u></mark> <mark class=\"m-autoridad\">fiscal. Si</mark> <mark class=\"m-personalizado\">se</mark></span></span> produjere dicha <mark class=\"m-personalizado\">demora,</mark> la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3908\">considerará la posibilidad de poner en libertad al detenido, con o sin condiciones</mark>.</p><p><b>5.</b> <mark class=\"m-personalizado\">De ser necesario,</mark> <mark class=\"m-autoridad\">la Sala</mark> de Cuestiones Preliminares <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">dictar</mark> <mark class=\"m-resp\" data-q=\"1-119,1-ia-3846\">una orden de detención para hacer comparecer a una persona que haya sido puesta en libertad</mark>.</p><p data-ex=\"*\"><b>Art. 61.</b> 1. Con sujeción a lo dispuesto en el párrafo 2 y dentro de un plazo razonable tras la <mark class=\"m-personalizado\">entrega</mark> de la persona a la <mark class=\"m-autoridad\">Corte o</mark> su comparecencia voluntaria ante ésta, la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares <mark class=\"m-accion\">celebrará</mark> una <mark class=\"m-autoridad\">audiencia</mark> <mark class=\"m-personalizado\">para confirmar los cargos</mark> sobre la base de los cuales el <mark class=\"m-autoridad\">fiscal</mark> tiene la <mark class=\"m-personalizado\">intención de pedir el</mark> procesamiento. La <mark class=\"m-autoridad\">audiencia</mark> <mark class=\"m-accion\">se celebrará</mark> <mark class=\"m-resp\" data-q=\"1-ia-3909,1-223\">en presencia del fiscal y del imputado, así como de su defensor</mark>.</p><p data-ex=\"*\"><b>2.</b> La <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares, a solicitud del <mark class=\"m-autoridad\">fiscal</mark> o de oficio, <mark class=\"m-accion\">podrá celebrar</mark> una <mark class=\"m-autoridad\">audiencia</mark> <mark class=\"m-destacable\">en</mark> ausencia del acusado para confirmar los cargos en los cuales el <mark class=\"m-autoridad\">fiscal</mark> se basa para pedir el enjuiciamiento cuando el imputado: <mark class=\"m-resp ex-q\" data-q=\"1-224\">🎯 1 pregunta</mark></p><p><b>a)</b> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3124\">Haya renunciado a su derecho a estar presente</mark>, o</p><p><b>b)</b> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3910\">Haya huido o no sea posible encontrarlo</mark> y se hayan tomado <span class=\"ex-plg\"><span class=\"ex-plg-t\">todas las medidas razonables para asegurar <mark class=\"m-personalizado\">su</mark> comparecencia ante la <mark class=\"m-autoridad\">Corte</mark> e informarle de los cargos y de que <mark class=\"m-accion\">se celebrará</mark> una <mark class=\"m-autoridad\">audiencia</mark> para confirmarlos.</span></span></p><p>En <mark class=\"m-personalizado\">este caso, el</mark> <mark class=\"m-autoridad\">imputado</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">representado por un</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">defensor</mark> cuando la <mark class=\"m-autoridad\">Sala de Cuestiones Preliminares resuelva</mark> <mark class=\"m-personalizado\">que</mark> ello redunda <mark class=\"m-personalizado\">en interés de la justicia.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3911\">🎯 1 pregunta</mark></p><p><b>b)</b> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3912,1-ia-3915,1-ia-3916\">Se le informará de las pruebas que el fiscal se proponga presentar en la audiencia</mark>.</p><p><b>4.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-plazo\">Antes de</mark> la <mark class=\"m-autoridad\">audiencia, el fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">proseguir la investigación y modificar o</mark> <mark class=\"m-resp r-ia r-vec\" data-q=\"1-ia-3812,1-ia-3913\">retirar los cargos</mark>. <mark class=\"m-accion\">Se dará</mark> <mark class=\"m-personalizado\">al imputado aviso</mark> con antelación razonable a la <mark class=\"m-autoridad\">audiencia</mark> de <mark class=\"m-personalizado\">cualquier modificación</mark> de los cargos o de su retiro.</span></span> En caso de retirarse cargos, <mark class=\"m-autoridad\">el fiscal</mark> <mark class=\"m-accion\">comunicará</mark> <mark class=\"m-personalizado\">las razones</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3812,1-ia-3913\">a la Sala de Cuestiones Preliminares</mark>.</p><p data-ex=\"*\"><b>5.</b> <mark class=\"m-personalizado\">En la</mark> <mark class=\"m-autoridad\">audiencia, el fiscal</mark> <mark class=\"m-accion\">presentará</mark> <mark class=\"m-personalizado\">respecto de cada cargo pruebas</mark> suficientes de que hay <mark class=\"m-personalizado\">motivos fundados</mark> para creer que el imputado <mark class=\"m-personalizado\">cometió</mark> el crimen que se le imputa. <mark class=\"m-autoridad\">El fiscal</mark> <mark class=\"m-accion\">podrá</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">presentar</mark></span> <mark class=\"m-personalizado\">pruebas documentales</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">un resumen de las pruebas y</mark> <mark class=\"m-resp\" data-q=\"1-93,1-ia-3914\">no será necesario que llame a los testigos que han de declarar en el juicio</mark>.</p><p data-ex=\"*\"><b>7.</b> <mark class=\"m-autoridad\">La Sala de Cuestiones Preliminares</mark> <mark class=\"m-accion\">determinará,</mark> <mark class=\"m-personalizado\">sobre la base de la</mark> <mark class=\"m-autoridad\">audiencia,</mark> si <mark class=\"m-personalizado\">existen</mark> pruebas <mark class=\"m-personalizado\"><u class=\"m-clave\">suficientes</u></mark> de que hay motivos fundados para creer que el imputado <mark class=\"m-personalizado\">cometió cada crimen</mark> que se le imputa. <mark class=\"m-resp ex-q\" data-q=\"1-225\">🎯 1 pregunta</mark></p><p><b>a)</b> <mark class=\"m-accion\">Confirmará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">los cargos</u></mark> respecto de los cuales haya determinado que existen pruebas suficientes <span class=\"m-circulo\"><mark class=\"m-personalizado\">y</mark></span> <mark class=\"m-resp\" data-q=\"1-157,1-ia-3917\">asignará al acusado a una Sala de Primera Instancia para su enjuiciamiento por los cargos confirmados</mark>;</p><p><b>8.</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">La no confirmación</u> de un cargo</mark> por parte de la <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares <mark class=\"m-destacable\"><u class=\"m-clave\">no</u></mark> <mark class=\"m-accion\">obstará</mark> <mark class=\"m-personalizado\">para que el</mark> <mark class=\"m-autoridad\">fiscal</mark></span></span> <mark class=\"m-personalizado\">la pida nuevamente</mark> a condición de que <mark class=\"m-resp r-ia\" data-q=\"1-ia-3918\">presente pruebas adicionales</mark>.</p><p data-ex=\"*\"><b>9.</b> <mark class=\"m-personalizado\">Una vez confirmados los cargos</mark> <mark class=\"m-autoridad\">y antes de comenzar el</mark> juicio, el <mark class=\"m-autoridad\">fiscal,</mark> <mark class=\"m-personalizado\">con <u class=\"m-clave\">autorización</u> de</mark> <mark class=\"m-autoridad\">la Sala de Cuestiones Preliminares y previa</mark> <mark class=\"m-personalizado\">notificación al acusado,</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-resp\" data-q=\"1-121\">modificar los cargos</mark>. <mark class=\"m-autoridad\">El fiscal,</mark> <mark class=\"m-personalizado\">si se propusiera</mark> presentar <mark class=\"m-personalizado\">nuevos cargos <u class=\"m-clave\">o</u></mark> sustituirlos por <mark class=\"m-personalizado\">otros más graves,</mark> <mark class=\"m-accion\">deberá pedir</mark> <mark class=\"m-destacable\">una</mark> <mark class=\"m-autoridad\">audiencia</mark> <mark class=\"m-personalizado\">de</mark> conformidad con el presente artículo <mark class=\"m-personalizado\">para confirmarlos.</mark> <mark class=\"m-autoridad\">Una vez comenzado</mark> el juicio, el <mark class=\"m-autoridad\">fiscal,</mark> <mark class=\"m-personalizado\">con autorización de</mark> <mark class=\"m-autoridad\">la Sala de</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">Primera</mark></span> <mark class=\"m-autoridad\">Instancia,</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">retirar los cargos.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3919\">🎯 1 pregunta</mark></p><p><b>10.</b> <mark class=\"m-personalizado\">Toda orden ya dictada</mark> <mark class=\"m-accion\">dejará</mark> <mark class=\"m-personalizado\">de tener efecto</mark> con respecto a los cargos que <mark class=\"m-resp r-ia\" data-q=\"1-ia-3920\">no hayan sido confirmados por la Sala de Cuestiones Preliminares o hayan sido retirados por el fiscal</mark>.</p><p><b>11.</b> <mark class=\"m-plazo\">Una vez confirmados los cargos</mark> de conformidad con el presente artículo, <mark class=\"m-autoridad\">la</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3921\">Presidencia</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">constituirá</mark> <mark class=\"m-autoridad\">una Sala de Primera Instancia</mark> que, con sujeción a lo dispuesto en el párrafo 9 del presente artículo y en el párrafo 4 del artículo 64, <mark class=\"m-accion\">se encargará</mark> de la siguiente fase del procedimiento y <mark class=\"m-accion\">podrá ejercer</mark> las funciones de la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones Preliminares que sean pertinentes y apropiadas en ese procedimiento.</span></span></p>"],["Artículos 86 y 87 — Obligación general de cooperar y solicitudes de cooperación","<p><b>Art. 86.</b> Los <mark class=\"m-autoridad\">Estados Partes</mark> (…) <mark class=\"m-accion\">cooperarán</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3922\">plenamente</mark> <mark class=\"m-destacable\">con la</mark> <mark class=\"m-autoridad\">Corte</mark> en <mark class=\"m-destacable\">relación con la investigación y el enjuiciamiento de crímenes de</mark> su competencia.</p><p><b>Art. 87.</b> a) La <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">estará</mark> facultada para formular <mark class=\"m-destacable\">solicitudes de cooperación</mark> a los <mark class=\"m-autoridad\">Estados Partes.</mark> Éstas <mark class=\"m-accion\">se transmitirán</mark> <mark class=\"m-resp\" data-q=\"1-159\">por vía diplomática o por cualquier otro conducto adecuado que haya designado cada Estado Parte a la fecha de la ratificación, aceptación, aprobación o adhesión</mark>.</p><p><b>b)</b> <mark class=\"m-personalizado\">Cuando proceda, y sin perjuicio de lo dispuesto en el apartado a), las solicitudes</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">transmitirse también por conducto de la</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3923\">Organización Internacional de Policía Criminal o de cualquier organización regional competente</mark>.</p><p><b>2.</b> Las solicitudes de cooperación y <span class=\"ex-plg\"><span class=\"ex-plg-t\">los documentos <mark class=\"m-personalizado\">que las justifiquen</mark> <mark class=\"m-accion\">estarán</mark> <mark class=\"m-personalizado\">redactados en</mark> un <mark class=\"m-destacable\">idioma</mark> oficial del <mark class=\"m-autoridad\">Estado</mark> requerido, o acompañados de una traducción a ese idioma, o a uno de los idiomas de</span></span> trabajo de la <mark class=\"m-autoridad\">Corte,</mark> según <mark class=\"m-resp r-ia\" data-q=\"1-ia-3924\">la elección que haya hecho el Estado a la fecha de la ratificación, aceptación, aprobación o adhesión</mark>.</p><p><b>3.</b> <mark class=\"m-autoridad\">El Estado requerido</mark> <mark class=\"m-resp\" data-q=\"1-91,1-ia-3925,1-ia-4007\">preservará el carácter confidencial de toda solicitud de cooperación y de los documentos que las justifiquen, salvo en la medida en que su divulgación sea necesaria para tramitarla</mark>.</p><p><b>4.</b> Con respecto a las <mark class=\"m-personalizado\">solicitudes de asistencia</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">presentadas de conformidad con la presente Parte, la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">adoptar todas las medidas,</mark> incluidas las relativas a la protección de</span></span> la información, que sean <mark class=\"m-personalizado\">necesarias para <u class=\"m-clave\">proteger la seguridad y el bienestar</u> físico o psicológico de</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3926\">las víctimas, los posibles testigos y sus familiares</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">solicitar</mark> que toda <mark class=\"m-personalizado\">información comunicada</mark> en virtud de la presente Parte <mark class=\"m-personalizado\">sea transmitida y procesada de manera que se proteja</mark> la seguridad y el bienestar físico o psicológico de las <mark class=\"m-personalizado\">víctimas, los</mark> posibles testigos y sus familiares.</span></span></p><p><b>b)</b> Cuando un <mark class=\"m-autoridad\">Estado</mark> que no <span class=\"ex-plg\"><span class=\"ex-plg-t\">sea parte en el presente Estatuto <mark class=\"m-personalizado\">y</mark> que haya celebrado un arreglo especial o un acuerdo con la <mark class=\"m-autoridad\">Corte</mark> se niegue a cooperar en la ejecución de las solicitudes a que se refieran <u class=\"m-clave\">tal</u> arreglo</span></span> o acuerdo, <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-autoridad\">informar de ello</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3825,1-ia-3927,1-ia-3929\">a la Asamblea de los Estados Partes o al Consejo de Seguridad, si éste le hubiese remitido el asunto</mark>.</p><p><b>6.</b> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">solicitar de</mark> <mark class=\"m-autoridad\">cualquier organización intergubernamental</mark> que <span class=\"ex-plg\"><span class=\"ex-plg-t\">le proporcione <mark class=\"m-personalizado\">información o documentos.</mark> Asimismo, la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">podrá solicitar</mark> otras formas <mark class=\"m-personalizado\">de cooperación y asistencia que</mark> se hayan acordado</span></span> con cualquiera de esas organizaciones, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3928\">de conformidad con su competencia o mandato</mark>.</p>"],["Artículo 89 — Entrega de personas a la Corte y tránsito <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>2.</b> <mark class=\"m-personalizado\">Cuando la persona</mark> cuya entrega se pida la <mark class=\"m-personalizado\">impugne ante</mark> <mark class=\"m-autoridad\">un tribunal nacional</mark> oponiendo la excepción de <mark class=\"m-destacable\">cosa juzgada</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el artículo 20</span></span>, <mark class=\"m-autoridad\">el Estado</mark> requerido <mark class=\"m-accion\">celebrará</mark> <mark class=\"m-personalizado\">de inmediato consultas con</mark> <mark class=\"m-autoridad\">la Corte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">para determinar si ha habido una decisión sobre la admisibilidad de la causa</span></span>. Si <mark class=\"m-personalizado\">la causa es admisible</mark>, el <mark class=\"m-autoridad\">Estado</mark> requerido <mark class=\"m-accion\">cumplirá</mark> <mark class=\"m-personalizado\">la solicitud</mark>. Si <mark class=\"m-destacable\">está</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">pendiente</u></mark> la decisión sobre la admisibilidad, el <mark class=\"m-autoridad\">Estado</mark> requerido <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">aplazar la ejecución</mark> de la solicitud de <mark class=\"m-personalizado\">entrega</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">hasta que la Corte adopte esa decisión</span></span>. <mark class=\"m-resp ex-q\" data-q=\"1-226\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>3.</b> a) <mark class=\"m-autoridad\">El Estado</mark> <mark class=\"m-personalizado\">Parte</mark> <mark class=\"m-accion\">autorizará</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con su derecho procesal</span></span> el <mark class=\"m-destacable\">tránsito</mark> por su territorio de una persona que otro <mark class=\"m-autoridad\">Estado</mark> entregue a la <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-personalizado\">salvo</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">cuando</mark></span> el tránsito por ese <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">obstaculice o demore la entrega</mark>; <span class=\"ex-plg\"><span class=\"ex-plg-t\">b) La solicitud de la Corte de que se autorice ese tránsito será transmitida de conformidad con el artículo 87 y contendrá: i) Una descripción de la persona que será transportada; ii) Una breve exposición de los hechos de la causa y su tipificación, y iii) La orden de detención y entrega;</span></span> c) la persona transportada <mark class=\"m-accion\">permanecerá</mark> <mark class=\"m-personalizado\">detenida durante el tránsito</mark>; <mark class=\"m-personalizado\">d) No se</mark> <mark class=\"m-accion\">requerirá</mark> <mark class=\"m-personalizado\">autorización alguna</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3933,1-ia-3934\">cuando la persona sea transportada por vía aérea y no se prevea aterrizar en el territorio del Estado de tránsito</mark>; <mark class=\"m-personalizado\">e)</mark> En caso de <mark class=\"m-personalizado\">aterrizaje imprevisto</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en el territorio del Estado de tránsito, éste podrá pedir a la Corte que presente una solicitud de tránsito con arreglo a lo dispuesto en el apartado b)</span></span>, el <mark class=\"m-autoridad\">Estado</mark> de tránsito <mark class=\"m-accion\">detendrá</mark> a la persona transportada mientras se recibe la solicitud de <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">Corte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y se efectúa el tránsito</span></span>; <mark class=\"m-personalizado\">sin embargo, la <u class=\"m-clave\">detención</u></mark> <mark class=\"m-destacable\">no</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">prolongarse</mark> <mark class=\"m-personalizado\">más</mark> de <mark class=\"m-resp\" data-q=\"1-158,1-ia-3935\">96 horas</mark> contadas desde el aterrizaje imprevisto si la solicitud no es <mark class=\"m-personalizado\">recibida dentro</mark> de ese plazo.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 89 — <mark class=\"m-personalizado\">Entrega</mark> de <mark class=\"m-personalizado\">personas</mark> <mark class=\"m-autoridad\">a la corte</mark> (texto completo): <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3931,1-ia-3932,1-ia-3936\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 90 — Solicitudes concurrentes <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> El <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte que haya recibido</mark> una solicitud de la <mark class=\"m-autoridad\">Corte</mark> relativa a <mark class=\"m-personalizado\">la entrega de una persona</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de con- formidad con el artículo 89</span></span>, <mark class=\"m-personalizado\">y reciba además una solicitud de cualquier otro</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">relativa a la extradición de la misma persona por la misma conducta</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que constituya la base del crimen en razón del cual la Corte ha pedido la entrega</span></span>, <mark class=\"m-accion\">notificará</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-autoridad\">la Corte</mark> y <mark class=\"m-destacable\">al</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">requirente ese</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">hecho.</u></mark> <mark class=\"m-resp ex-q\" data-q=\"1-227\">🎯 1 pregunta</mark></p><p><b>4.</b> <mark class=\"m-destacable\">Si el</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-destacable\">requirente <u class=\"m-clave\">no</u> es parte en el presente Estatuto,</mark> el <mark class=\"m-autoridad\">Estado</mark> requerido, en <mark class=\"m-personalizado\">caso de que</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3940\">no esté obligado por alguna norma internacional a conceder la extradición</mark> al <mark class=\"m-autoridad\">Estado</mark> requirente, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3937,1-ia-3938,1-ia-3939,1-ia-3940,1-ia-3941,1-ia-3942,1-ia-4011\">dará prioridad a la solicitud de entrega que le haya hecho la Corte si ésta ha determinado que la causa era admisible</mark>.</p><p><b>8.</b> <mark class=\"m-personalizado\">Cuando,</mark> como consecuencia de una notificación efectuada con arreglo al presente artículo, <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">haya determinado la <u class=\"m-clave\">inadmisibilidad</u></mark> de una causa <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">posteriormente <u class=\"m-clave\">se deniegue</u> la extradición <u class=\"m-clave\">al</u></mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">requirente,</u></mark> <mark class=\"m-resp\" data-q=\"1-78,1-ia-3943\">el Estado requerido notificará su decisión a la Corte</mark>.</p>"],["Artículos 91 y 92 — Solicitud de detención y entrega y detención provisional · R27 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R27</span>","<p data-r=\"R27\"><span class=\"ex-sello ex-sello-r\">R27</span> <b>Art. 91.</b> <mark class=\"m-destacable\">1. <u class=\"m-clave\">La solicitud</u></mark> <mark class=\"m-personalizado\">de detención y entrega</mark> <span class=\"m-caja\"><mark class=\"m-accion\">deberá</mark></span> formularse <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"1-184\">por escrito</mark>.</mark> <mark class=\"m-destacable\">En caso <u class=\"m-clave\">de</u> urgencia,</mark> <mark class=\"m-accion\">se podrá hacer</mark> por cualquier <mark class=\"m-personalizado\"><u class=\"m-clave\">otro medio</u></mark> que permita <mark class=\"m-personalizado\">dejar constancia escrita, a condición</mark> de que <mark class=\"m-resp r-ia\" data-q=\"1-ia-3944,1-ia-4009\">la solicitud sea confirmada en la forma indicada en el párrafo 1.a) del artículo 87</mark>.</p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-personalizado\">La solicitud de detención y entrega</mark> de una persona respecto de la cual la <mark class=\"m-autoridad\">Sala</mark> de Cuestiones <mark class=\"m-personalizado\">Preliminares</mark> haya dictado una orden de detención de conformidad con el artículo <mark class=\"m-destacable\">58</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-destacable\">contener</mark> <mark class=\"m-personalizado\">los elementos siguientes</mark> o ir <mark class=\"m-personalizado\">acompañada de:</mark> <mark class=\"m-resp ex-q\" data-q=\"1-228\">🎯 1 pregunta</mark></p><p><b>c)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Los</u> documentos, las declaraciones o la información</mark> que sean <mark class=\"m-personalizado\">necesarios para</mark> cumplir <span class=\"ex-plg\"><span class=\"ex-plg-t\">los requisitos de procedimiento del <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">requerido</mark> relativos a la entrega; <mark class=\"m-personalizado\">sin embargo, esos</mark> requisitos <mark class=\"m-accion\">no podrán</mark> ser <mark class=\"m-personalizado\">más onerosos</mark> que los aplicables a las solicitudes de <mark class=\"m-personalizado\">extradición conforme a tratados</mark> o acuerdos <mark class=\"m-personalizado\">celebrados</mark> por el <mark class=\"m-autoridad\">Estado</mark></span></span> requerido y otros <mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-personalizado\">y, de ser posible,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4030\">serán menos onerosos, habida cuenta del carácter específico de la Corte</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3945\">🎯 1 pregunta</mark></p><p><b>d)</b> <mark class=\"m-personalizado\">Si</mark> la persona que <span class=\"ex-plg\"><span class=\"ex-plg-t\">se busca <mark class=\"m-personalizado\">ha sido condenada a</mark> una pena, <mark class=\"m-personalizado\"><u class=\"m-clave\">copia de la sentencia</u></mark> y, <mark class=\"m-personalizado\">en el caso</mark> de una pena de reclusión, <mark class=\"m-personalizado\">una indicación</mark> de la parte de la pena que se ha cumplido y de <mark class=\"m-personalizado\">la que queda por cumplir.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3946\">🎯 1 pregunta</mark></p><p><b>4.</b> A <mark class=\"m-personalizado\">solicitud</mark> de <mark class=\"m-autoridad\">la Corte, un Estado Parte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">consultará</mark> <mark class=\"m-personalizado\">con</mark> ésta, en general o con respecto a un asunto concreto, sobre las disposiciones de su derecho interno que puedan ser aplicables de conformidad con el apartado c) del párrafo 2 del presente artículo. En esas consultas, el <mark class=\"m-autoridad\">Estado</mark> Parte <mark class=\"m-accion\">comunicará</mark> a la <mark class=\"m-autoridad\">Corte</mark> los <mark class=\"m-personalizado\">requisitos específicos de su derecho interno.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3947\">🎯 1 pregunta</mark></p><p><b>Art. 92.</b> <mark class=\"m-destacable\">1. En</mark> caso <mark class=\"m-destacable\"><u class=\"m-clave\">de</u> urgencia, la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">solicitar la</mark> <mark class=\"m-personalizado\">detención provisional</mark> de la persona buscada hasta <mark class=\"m-personalizado\">que se presente la solicitud de entrega</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y los documentos que la justifiquen de conformidad con el artículo 91</span></span>. 2. <mark class=\"m-personalizado\">La solicitud</mark> de detención provisional <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">hacerse <mark class=\"m-resp r-ia\" data-q=\"1-ia-3948\">por cualquier medio que permita dejar constancia escrita</mark> y</mark> <mark class=\"m-accion\">contendrá:</mark> a) <mark class=\"m-personalizado\">información suficiente para identificar a la persona</mark> buscada <mark class=\"m-personalizado\">y</mark> datos sobre <mark class=\"m-personalizado\">su probable paradero;</mark> b) <mark class=\"m-personalizado\">una exposición concisa de los crímenes</mark> por los que se pida la detención <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">de los hechos</mark> que presuntamente serían constitutivos de esos crímenes, <mark class=\"m-resp\" data-q=\"1-104\">inclusive, de ser posible, la indicación de la fecha y el lugar en que se cometieron</mark>; c) <mark class=\"m-personalizado\">una <u class=\"m-clave\">declaración</u> de que <u class=\"m-clave\">existe una orden</u></mark> de detención o una decisión final condenatoria <span class=\"ex-plg\"><span class=\"ex-plg-t\">respecto de la persona buscada</span></span>, <mark class=\"m-personalizado\">y d)</mark> una declaración de que <mark class=\"m-accion\">se presentará</mark> una solicitud de entrega <span class=\"ex-plg\"><span class=\"ex-plg-t\">de la persona buscada</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3949\">🎯 1 pregunta</mark></p><p class=\"ex-mas\"><mark class=\"m-resp ex-q\" data-q=\"1-228\">🎯 1 pregunta más de este artículo</mark></p>"],["Artículo 93 — Otras formas de cooperación <span class=\"ex-sello\">✱</span>","<p><b>b)</b> <mark class=\"m-personalizado\">Practicar pruebas,</mark> incluidos los <mark class=\"m-personalizado\">testimonios</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">bajo juramento, y <mark class=\"m-personalizado\">producir pruebas,</mark> incluidos los <mark class=\"m-personalizado\">dictámenes e informes periciales</mark> que requiera la <mark class=\"m-autoridad\">Corte;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3951\">🎯 1 pregunta</mark></p><p><b>h)</b> <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"1-ia-3952\">Practicar allanamientos y decomisos</mark>;</mark></p><p><b>k)</b> <mark class=\"m-personalizado\">Identificar, determinar el paradero o inmovilizar el producto y los bienes</mark> y haberes obtenidos <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">del</mark> crimen y de los <mark class=\"m-personalizado\">instrumentos del crimen,</mark> o incautarse de ellos, <mark class=\"m-personalizado\">con miras a su decomiso</mark> ulterior y <mark class=\"m-personalizado\">sin perjuicio</mark> de los derechos de <mark class=\"m-personalizado\">terceros de buena fe, y</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3953\">🎯 1 pregunta</mark></p><p><b><mark class=\"m-personalizado\">2.</mark></b> <mark class=\"m-personalizado\">La</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">dar seguridades a los testigos o expertos que comparezcan ante ella de que no</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">enjuiciados o detenidos ni se</mark> <mark class=\"m-accion\">restringirá</mark> <mark class=\"m-personalizado\">su libertad personal por</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3954\">un acto u omisión anterior a su salida del Estado requerido</mark>.</p><p><b>3.</b> <mark class=\"m-personalizado\">Cuando la ejecución de una determinada</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">medida de asistencia detallada en una solicitud presentada de conformidad con</span></span> el párrafo 1 <mark class=\"m-personalizado\">estuviera prohibida en</mark> <mark class=\"m-autoridad\">el Estado requerido</mark> <mark class=\"m-personalizado\">por un principio fundamental de derecho ya existente y de aplicación general,</mark> el <mark class=\"m-autoridad\">Estado</mark> requerido <mark class=\"m-accion\">celebrará</mark> sin <mark class=\"m-personalizado\">demora consultas con</mark> <mark class=\"m-autoridad\">la Corte</mark> para tratar de resolver la cuestión. En las consultas <mark class=\"m-personalizado\">se debería considerar si se puede prestar la asistencia de otra manera</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o con sujeción a condiciones. Si, después de celebrar consultas, no se pudiera</span></span> resolver la cuestión, la Corte modificará la solicitud según sea necesario.</p><p data-ex=\"*\"><b>4.</b> <mark class=\"m-autoridad\">El Estado Parte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">no dar lugar <u class=\"m-clave\">a</u> una solicitud de asistencia, en su totalidad o en parte,</mark> de conformidad con el artículo 72 y <mark class=\"m-resp\" data-q=\"1-ia-3955,1-229\">únicamente si la solicitud se refiere a la presentación de documentos o la divulgación de pruebas que afecten a su seguridad nacional</mark>.</p><p><b>6.</b> <mark class=\"m-personalizado\">Si no se da lugar a una solicitud</mark> de asistencia, el <mark class=\"m-autoridad\">Estado</mark> Parte requerido <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">comunicar sin demora</mark> <mark class=\"m-resp\" data-q=\"1-92,1-ia-3956\">los motivos a la Corte o al fiscal</mark>.</p><p><b>ii)</b> El <mark class=\"m-autoridad\">Estado</mark> requerido lo <span class=\"ex-plg\"><span class=\"ex-plg-t\">acepte, con sujeción a las condiciones que hubiere acordado con la <mark class=\"m-autoridad\">Corte.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3957\">🎯 1 pregunta</mark></p><p><b>b)</b> <mark class=\"m-autoridad\">El Estado requerido</mark> <mark class=\"m-accion\">podrá,</mark> cuando sea necesario, <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">transmitir</mark> <mark class=\"m-autoridad\">al fiscal</mark> <mark class=\"m-personalizado\">documentos o información</mark> con carácter <mark class=\"m-personalizado\">confidencial.</mark></span></span> El <mark class=\"m-autoridad\">fiscal</mark> <mark class=\"m-personalizado\">únicamente</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">utilizarlos para</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3958\">reunir nuevas pruebas</mark>.</p><p><b>i)</b> <mark class=\"m-autoridad\">El Estado Parte</mark> <mark class=\"m-personalizado\">que reciba solicitudes concurrentes de</mark> <mark class=\"m-autoridad\">la Corte y de otro Estado</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">conformidad con una <mark class=\"m-personalizado\">obligación internacional y que</mark> no se refieran a la <mark class=\"m-personalizado\">entrega o la extradición,</mark> <mark class=\"m-accion\">procurará,</mark> <mark class=\"m-personalizado\">en consulta</mark> con la <mark class=\"m-autoridad\">Corte</mark> y el otro <mark class=\"m-autoridad\">Estado,</mark> <mark class=\"m-personalizado\">atender ambas</mark> solicitudes, de ser <mark class=\"m-personalizado\">necesario postergando</mark> o condicionando una de ellas.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3959\">🎯 1 pregunta</mark></p><p><b>b)</b> <mark class=\"m-personalizado\">Sin embargo, cuando la solicitud de</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">se refiera a información, bienes o personas</mark> que estén <mark class=\"m-personalizado\">sometidos al control de</mark> <mark class=\"m-autoridad\">un tercer Estado <u class=\"m-clave\">o</u> de una organización internacional</mark> en virtud de un acuerdo internacional, <mark class=\"m-autoridad\">el Estado requerido</mark> <mark class=\"m-personalizado\">lo</mark> <mark class=\"m-accion\">comunicará</mark> a la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-resp\" data-q=\"1-ia-4001\">la Corte dirigirá su solicitud al tercer Estado o a la organización internacional</mark>.</p><p><b>a)</b> A solicitud de un <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Estado</mark> Parte que lleve a cabo una investigación o sustancie un <mark class=\"m-personalizado\">juicio por una</mark> conducta que constituya <mark class=\"m-personalizado\">un crimen de la competencia de la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-destacable\">o</mark> que constituya <mark class=\"m-personalizado\">un crimen grave</mark> con arreglo al derecho interno del <mark class=\"m-autoridad\">Estado</mark> requirente, <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">cooperar con él y prestarle asistencia;</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4002\">🎯 1 pregunta</mark></p><p><b><mark class=\"m-personalizado\">b)</mark></b> <mark class=\"m-personalizado\">El interrogatorio</mark> de una persona <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">detenida por</mark> orden de <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">Corte.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4003\">🎯 1 pregunta</mark></p><p><b>c)</b> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá,</mark> de conformidad <span class=\"ex-plg\"><span class=\"ex-plg-t\">con el presente párrafo y en las condiciones enunciadas en él, <mark class=\"m-personalizado\">acceder a una solicitud de asistencia</mark> presentada <mark class=\"m-personalizado\">por</mark> <mark class=\"m-autoridad\">un Estado que no sea parte</mark> en el presente Estatuto.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4005\">🎯 1 pregunta</mark></p>"],["Artículo 94 — Aplazamiento de la ejecución de una solicitud de asistencia (investigación o enjuiciamiento en curso) <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R28</span>","<p data-ex=\"*\" data-r=\"R28\"><span class=\"ex-sello ex-sello-r\">R28</span> <b>Art. 94.</b> <b>1.</b> <mark class=\"m-personalizado\">Si la ejecución inmediata de</mark> una <mark class=\"m-destacable\">solicitud de asistencia</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">interfiere</u> una investigación o enjuiciamiento en curso de un <u class=\"m-clave\">asunto</u></mark> <mark class=\"m-destacable\">distinto de</mark> aquel al que se refiera la solicitud, <mark class=\"m-autoridad\">el Estado requerido</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">aplazar la ejecución por el tiempo que acuerde con</mark> <mark class=\"m-autoridad\">la Corte.</mark> <mark class=\"m-personalizado\">No obstante,</mark> el aplazamiento <mark class=\"m-resp r-ia\" data-q=\"1-ia-4006\"><mark class=\"m-accion\">no excederá</mark> <mark class=\"m-personalizado\">de lo necesario para concluir</mark> la investigación o el enjuiciamiento de que se trate en el <mark class=\"m-autoridad\">Estado</mark> requerido</mark>. <mark class=\"m-personalizado\">Antes de tomar la decisión de aplazar</mark> la ejecución de la solicitud, el <mark class=\"m-autoridad\">Estado</mark> requerido <mark class=\"m-personalizado\">debería considerar si</mark> <mark class=\"m-accion\">se podrá</mark> <mark class=\"m-personalizado\">prestar</mark> inmediatamente la <mark class=\"m-personalizado\">asistencia</mark> con sujeción a <mark class=\"m-personalizado\">ciertas condiciones.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-185\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 95 — Aplazamiento de la <mark class=\"m-destacable\">ejecución</mark> por impugnarse <mark class=\"m-personalizado\">la admisibilidad de la causa</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4008,1-ia-4193\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 96 — <mark class=\"m-personalizado\">Contenido</mark> de <mark class=\"m-personalizado\">la solicitud</mark> relativa a <mark class=\"m-personalizado\">otras formas de asistencia</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4010\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 97 — <mark class=\"m-plazo\">Consultas con la</mark> <mark class=\"m-autoridad\">Corte</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4012,1-ia-4013,1-ia-4194\">🎯 3 preguntas más de este artículo</mark>"],["Artículos 98 y 99 — Renuncia a la inmunidad y cumplimiento de las solicitudes de asistencia <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 98.</b> <b>1.</b> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u></mark> <mark class=\"m-accion\">dará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">curso</u> a una solicitud de entrega o de asistencia en virtud de la cual</mark> el <mark class=\"m-autoridad\">Estado</mark> requerido deba actuar en forma <mark class=\"m-personalizado\">incompatible</mark> con las obligaciones que le imponga el <mark class=\"m-personalizado\">derecho internacional</mark> con respecto a <mark class=\"m-personalizado\">la inmunidad de un</mark> <mark class=\"m-autoridad\">Estado o la</mark> <mark class=\"m-personalizado\">inmunidad diplomática</mark> <mark class=\"m-autoridad\">de</mark> <mark class=\"m-personalizado\">una persona o un bien de</mark> <mark class=\"m-autoridad\">un tercer Estado,</mark> <mark class=\"m-personalizado\">salvo que</mark> la <mark class=\"m-autoridad\">Corte</mark> obtenga anteriormente la <mark class=\"m-personalizado\">cooperación</mark> de ese tercer <mark class=\"m-autoridad\">Estado</mark> para la renuncia <mark class=\"m-personalizado\">a la inmunidad.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-230,1-ia-4014,1-ia-4015\">🎯 3 preguntas</mark></p><p data-ex=\"*\"><b>Art. 99.</b> <b>1.</b> <mark class=\"m-personalizado\">Las solicitudes de asistencia</mark> <mark class=\"m-accion\">se cumplirán</mark> de conformidad con el <mark class=\"m-personalizado\">procedimiento aplicable en el derecho interno del</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">requerido y, salvo si ese derecho lo <u class=\"m-clave\">prohíbe,</u> en la <u class=\"m-clave\">forma especificada</u> en la <mark class=\"m-resp\" data-q=\"1-231\">solicitud</mark>,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">incluidos los procedimientos indicados en ella y la autorización a las personas especificadas en ella para estar presentes y prestar asistencia</span></span> en el trámite. <b>2.</b> En <mark class=\"m-personalizado\">el caso de una</mark> <mark class=\"m-destacable\">solicitud urgente</mark> y cuando la <span class=\"m-caja\"><mark class=\"m-autoridad\">Corte</mark></span> <span class=\"m-caja\">lo pida,</span> <mark class=\"m-personalizado\">los documentos o pruebas</mark> incluidos en la respuesta <mark class=\"m-accion\">serán transmitidos</mark> con <mark class=\"m-personalizado\">urgencia.</mark> <b>3.</b> <mark class=\"m-personalizado\">Las respuestas</mark> <mark class=\"m-autoridad\">del Estado requerido</mark> <mark class=\"m-accion\">serán transmitidas</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4017\">en su idioma y forma original</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4016\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>4.</b> Sin perjuicio de los demás artículos de la presente <mark class=\"m-personalizado\">parte, cuando resulte necesario en el caso de una solicitud que pueda ejecutarse</mark> <mark class=\"m-destacable\">sin</mark> <mark class=\"m-personalizado\">necesidad de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">medidas</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">coercitivas,</u> en particular la entrevista a</mark> una persona o la <mark class=\"m-personalizado\">recepción de pruebas</mark> de una persona voluntariamente, <mark class=\"m-personalizado\">aun cuando sea sin la presencia de las</mark> <mark class=\"m-autoridad\">autoridades del Estado</mark> <mark class=\"m-personalizado\">Parte requerido si ello fuere esencial</mark> para la ejecución de la solicitud, y <mark class=\"m-personalizado\">el</mark> reconocimiento de un lugar u otro recinto que no entrañe un cambio en él, <mark class=\"m-autoridad\">el fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ejecutar directamente la solicitud en el territorio de</mark> <mark class=\"m-autoridad\">un Estado según</mark> se indica a continuación: a) <mark class=\"m-personalizado\">Cuando</mark> <mark class=\"m-autoridad\">el Estado Parte requerido</mark> <mark class=\"m-personalizado\">fuere</mark> un <mark class=\"m-autoridad\">Estado</mark> en cuyo <mark class=\"m-personalizado\">territorio</mark> se hubiera <mark class=\"m-personalizado\">cometido</mark> presuntamente el crimen, <mark class=\"m-personalizado\">y</mark> hubiere habido una <mark class=\"m-personalizado\">decisión de admisibilidad</mark> de conformidad con los artículos 18 ó 19, <mark class=\"m-autoridad\">el fiscal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">ejecutar directamente</u></mark> la <mark class=\"m-personalizado\">solicitud tras</mark> celebrar todas <mark class=\"m-personalizado\">las consultas</mark> posibles con el <mark class=\"m-autoridad\">Estado</mark> Parte requerido. b) <mark class=\"m-personalizado\">En los demás casos,</mark> <mark class=\"m-autoridad\">el fiscal</mark> <mark class=\"m-accion\">podrá ejecutar</mark> la solicitud <mark class=\"m-personalizado\">tras celebrar consultas con</mark> <mark class=\"m-autoridad\">el Estado Parte requerido</mark> <mark class=\"m-personalizado\">y con sujeción</mark> a cualquier <mark class=\"m-personalizado\">condición u observación razonable</mark> que imponga o haga ese <mark class=\"m-autoridad\">Estado</mark> Parte. <mark class=\"m-personalizado\">Cuando</mark> el <mark class=\"m-autoridad\">Estado</mark> Parte requerido <mark class=\"m-personalizado\">considere que hay problemas</mark> para la ejecución de una solicitud de conformidad con el presente <mark class=\"m-personalizado\">apartado,</mark> <mark class=\"m-accion\">celebrará</mark> <mark class=\"m-personalizado\">consultas</mark> sin demora con <mark class=\"m-autoridad\">la Corte</mark> para resolver la cuestión. <mark class=\"m-resp ex-q\" data-q=\"1-232,1-ia-4018,1-ia-4019\">🎯 3 preguntas</mark></p>"],["Artículos 100, 101 y 102 — Gastos, principio de la especialidad y términos empleados <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R29</span>","<p><b>Art. 100.</b> 1. <mark class=\"m-resp r-ia\" data-q=\"1-ia-4020,1-ia-4022\">Los gastos ordinarios que se deriven del cumplimiento de las solicitudes en el territorio del Estado requerido correrán a cargo de éste</mark>, <mark class=\"m-personalizado\">con</mark> excepción <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">de los siguientes</mark>, que <mark class=\"m-accion\">correrán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">a cargo</u> de</mark> <mark class=\"m-autoridad\">la Corte</mark></span></span> : <span class=\"ex-plg\"><span class=\"ex-plg-t\">a) gastos relacionados con el <mark class=\"m-personalizado\">viaje y la seguridad de los testigos y peritos</mark>, o el traslado (…) de personas detenidas; b) gastos de <mark class=\"m-personalizado\">traducción</mark>, <mark class=\"m-personalizado\">interpretación y transcripción</mark>; c) gastos de <mark class=\"m-personalizado\"><u class=\"m-clave\">viaje y</u> dietas de los</mark> <mark class=\"m-autoridad\">magistrados, el fiscal</mark> (…); d) costo de los <mark class=\"m-personalizado\"><u class=\"m-clave\">informes</u> o <u class=\"m-clave\">dictámenes</u> periciales solicitados por la</mark> <mark class=\"m-autoridad\">Corte</mark>; e) gastos relacionados con el <mark class=\"m-personalizado\">transporte de la persona que <u class=\"m-clave\">entregue a</u> la</mark> <mark class=\"m-autoridad\">Corte un</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">Estado de</mark></span> <span class=\"m-caja\"><mark class=\"m-plazo\">detención</mark></span>, <span class=\"m-caja\"><mark class=\"m-plazo\">y</mark></span> f) <mark class=\"m-personalizado\">previa <u class=\"m-clave\">consulta</u></mark>, <mark class=\"m-personalizado\">todos los</mark> gastos extraordinarios (…).</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4021\">🎯 1 pregunta</mark></p><p data-ex=\"*\" data-r=\"R29\"><span class=\"ex-sello ex-sello-r\">R29</span> <b>Art. 101.</b> <mark class=\"m-destacable\">1. Quien</mark> haya sido <mark class=\"m-personalizado\">entregado a</mark> <mark class=\"m-autoridad\">la <u class=\"m-clave\">Corte</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en virtud del presente Estatuto</span></span> <mark class=\"m-resp\" data-q=\"1-ia-4023,1-186\">no será procesado, castigado o detenido por una conducta anterior a su entrega, a menos que ésta constituya la base del delito por el cual haya sido entregado</mark>. 2. <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">pedir</mark> <mark class=\"m-autoridad\">al Estado</mark> que hizo la entrega que la <mark class=\"m-destacable\">dispense</mark> <mark class=\"m-personalizado\">del cumplimiento</mark> de los requisitos establecidos en el <mark class=\"m-personalizado\">párrafo 1</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y, si fuere necesario, proporcionará información adicional de conformidad con el artículo 91</span></span>. <mark class=\"m-autoridad\">Los Estados Partes</mark> <mark class=\"m-accion\">estarán</mark> <mark class=\"m-personalizado\">facultados para dar</mark> esa <mark class=\"m-personalizado\">dispensa</mark> a la <mark class=\"m-autoridad\">Corte</mark> y <mark class=\"m-accion\">procurarán</mark> <mark class=\"m-personalizado\">hacerlo</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4024\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>Art. 102.</b> A los efectos del presente Estatuto: a) por <mark class=\"m-destacable\">«entrega»</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3736,1-ia-4025\">la entrega de una persona por un Estado a la Corte de conformidad con lo dispuesto en el presente Estatuto</mark>. b) por <mark class=\"m-destacable\">«extradición»</mark> <mark class=\"m-accion\">se entenderá</mark> la entrega de una persona <mark class=\"m-personalizado\">por un</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">a otro</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">de conformidad</mark> con lo dispuesto en un <mark class=\"m-personalizado\">tratado o convención o en el derecho interno</mark>.</p>"],["Artículo 1 — Objeto y fuentes jurídicas · R1 <span class=\"ex-sello ex-sello-r\">R1</span>","<p data-r=\"R1\"><span class=\"ex-sello ex-sello-r\">R1</span> <mark class=\"m-destacable\">El objeto</mark> <mark class=\"m-personalizado\">de esta ley orgánica es</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3011,1-ia-3930,1-ia-4030\">regular las relaciones de cooperación entre el Estado español y la Corte Penal Internacional</mark> <mark class=\"m-personalizado\">en el ejercicio de la jurisdicción y funciones encomendadas a esta institución por el Estatuto de Roma</mark> de 17 de julio de 1998 <mark class=\"m-personalizado\">-en lo</mark> sucesivo, el Estatuto- y su normativa complementaria, <mark class=\"m-personalizado\">mediante la</mark> atribución de competencias a los <mark class=\"m-autoridad\">órganos</mark> estatales y el establecimiento de procedimientos internos adecuados, aplicables <mark class=\"m-resp\" data-q=\"1-187,1-ia-3848,1-ia-4192\">en lo no previsto en el Estatuto y sus normas complementarias en la medida en que éstas resulten pertinentes</mark><span class=\"ex-plg\"><span class=\"ex-plg-t\">, en particular las reglas de procedimiento y prueba, así como en los acuerdos específicos de cooperación que España pueda</span></span> celebrar con la <mark class=\"m-autoridad\">Corte.</mark></p><p><mark class=\"m-personalizado\">Con</mark> <mark class=\"m-destacable\">carácter supletorio</mark> <mark class=\"m-personalizado\">a esta ley se</mark> <mark class=\"m-accion\">aplicarán</mark> <mark class=\"m-personalizado\">las</mark> <mark class=\"m-resp\" data-q=\"1-ia-3012,1-188\">normas orgánicas y procesales de aplicación general</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 2 — De <mark class=\"m-personalizado\">la cooperación</mark> pasiva: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3013\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 3</mark> — De <mark class=\"m-personalizado\">la cooperación</mark> activa: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3014,1-ia-3427,1-ia-4005\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 4 — De las autoridades competentes <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><mark class=\"m-destacable\">Son</mark> <mark class=\"m-autoridad\">autoridades</mark> <mark class=\"m-destacable\">competentes</mark> para <mark class=\"m-personalizado\">la aplicación de esta ley:</mark></p><p>a) <mark class=\"m-personalizado\">El</mark> <mark class=\"m-resp\" data-q=\"1-140\">Gobierno</mark>.</p><p>b) El <mark class=\"m-resp\" data-q=\"1-116\">Ministerio de Justicia</mark>.</p><p data-ex=\"EX\">c) <mark class=\"m-personalizado\">El</mark> <mark class=\"m-resp\" data-q=\"1-103,1-127\">Ministerio de Asuntos Exteriores</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3015\">en los casos previstos en esta ley, y, en todo caso, cuando intervinieran factores de política exterior</mark>.</p><p>d) <mark class=\"m-personalizado\">El</mark> <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-personalizado\">de Defensa y el</mark> <mark class=\"m-autoridad\">Ministerio</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">del Interior</mark>, <mark class=\"m-personalizado\">cuando el</mark> acto de cooperación afecte a sus competencias.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3016\">🎯 1 pregunta</mark></p><p data-ex=\"*\">e) <mark class=\"m-personalizado\">Los</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">judiciales de la jurisdicción ordinaria y, en particular</mark>, <mark class=\"m-personalizado\">la</mark> <mark class=\"m-resp\" data-q=\"1-233\">Audiencia Nacional</mark>.</p><p data-ex=\"*\">f) <mark class=\"m-personalizado\">Los</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">judiciales militares</mark> y, <mark class=\"m-personalizado\">en particular</mark>, <mark class=\"m-personalizado\">el</mark> <mark class=\"m-resp\" data-q=\"1-ia-3017,1-ia-3451,1-234\">Tribunal Militar Central</mark>.</p><p>g) <mark class=\"m-personalizado\">El</mark> <mark class=\"m-resp\" data-q=\"1-133\">Ministerio Fiscal</mark>.</p>"],["Artículo 5 — De la representación y defensa procesal · R2 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R2</span>","<p data-ex=\"*\"><b><mark class=\"m-destacable\">1.</mark></b> <mark class=\"m-destacable\">La</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">representación</u> y <u class=\"m-clave\">defensa</u> en juicio de España</mark> <mark class=\"m-autoridad\">ante los órganos de la Corte</mark> <mark class=\"m-accion\">corresponderá</mark> a los <mark class=\"m-resp r-ia\" data-q=\"1-ia-3019\">Abogados del Estado integrados en la Abogacía General del Estado</mark> y <mark class=\"m-personalizado\">de acuerdo con las instrucciones impartidas</mark> <mark class=\"m-resp\" data-q=\"1-235\">conjuntamente</mark>, en <span class=\"m-caja\">cada caso,</span> <mark class=\"m-personalizado\">por el</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3018\">Ministerio de Justicia y el Ministerio de Asuntos Exteriores</mark>. <mark class=\"m-personalizado\">En los supuestos</mark> en que el procedimiento <mark class=\"m-personalizado\">afecte a</mark> materias propias de <mark class=\"m-personalizado\">algún departamento ministerial</mark>, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">oirá</mark> <mark class=\"m-personalizado\">a</mark> éste <mark class=\"m-personalizado\">antes</mark> de impartir las citadas <mark class=\"m-personalizado\">instrucciones</mark>.</p><p data-r=\"R2\"><span class=\"ex-sello ex-sello-r\">R2</span> <b>2.</b> <mark class=\"m-autoridad\">El Gobierno</mark>, por <mark class=\"m-personalizado\">motivos excepcionales y oído</mark> <mark class=\"m-autoridad\">el Abogado General del Estado</mark>, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">acordar</mark> que una persona, <mark class=\"m-personalizado\">especialmente designada</mark> al efecto, <mark class=\"m-personalizado\">actúe como</mark> <mark class=\"m-destacable\">agente de España</mark> <mark class=\"m-personalizado\">en un determinado procedimiento</mark> ante los <mark class=\"m-autoridad\">órganos</mark> de la <mark class=\"m-autoridad\">Corte.</mark> La persona designada por el <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-resp\" data-q=\"1-189,1-ia-3020\">asumirá en el desempeño de sus servicios las funciones de Abogado del Estado y se ajustará a las disposiciones que regulan el ejercicio de dichas funciones</mark>.</p>"],["Artículo 6 — De los órganos de relación y consulta con la Corte <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>1.</b> <mark class=\"m-autoridad\">El</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3021\">Ministerio de Justicia</mark> <mark class=\"m-autoridad\">es</mark> <mark class=\"m-destacable\">el</mark> <mark class=\"m-resp\" data-q=\"1-127\">único órgano de relación</mark> <mark class=\"m-personalizado\">entre la</mark> <mark class=\"m-autoridad\">Corte</mark>, <mark class=\"m-personalizado\">por un lado, y los</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">judiciales</mark> y <mark class=\"m-autoridad\">Ministerio Fiscal</mark>, <mark class=\"m-personalizado\">por otro, sin perjuicio de las competencias del</mark> <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-personalizado\">de Asuntos Exteriores</mark>.</p><p data-ex=\"EX\"><b>2.</b> <mark class=\"m-autoridad\">El Ministerio de Justicia</mark> <mark class=\"m-personalizado\">es también el</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-destacable\">de consulta</mark> <mark class=\"m-personalizado\">con la</mark> <mark class=\"m-autoridad\">Corte</mark> en los casos previstos en <mark class=\"m-personalizado\">el Estatuto</mark>, <mark class=\"m-personalizado\">debiendo <u class=\"m-clave\">informar previamente</u></mark> de cada consulta <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-personalizado\">de Asuntos Exteriores</mark>.</p><p>Cuando la <mark class=\"m-personalizado\"><u class=\"m-clave\">consulta</u> incluya, a juicio del</mark> <mark class=\"m-autoridad\">Ministerio de Asuntos Exteriores</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">aspectos</u> de política exterior</mark>, <mark class=\"m-resp\" data-q=\"1-128,1-ia-3023\">será éste el competente, en coordinación con el Ministerio de Justicia</mark> <mark class=\"m-destacable\">y,</mark> en su caso, con <mark class=\"m-personalizado\">otros</mark> <mark class=\"m-autoridad\">ministerios</mark> concernidos.</p>"],["Artículo 7 — De la solicitud para iniciar una investigación por el Fiscal de la Corte <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><b>1.</b> <mark class=\"m-accion\">Corresponde</mark> <u class=\"m-clave\">exclusivamente</u> al <mark class=\"m-resp\" data-q=\"1-118\">Gobierno, mediante Acuerdo del Consejo de Ministros</mark>, a <mark class=\"m-destacable\">propuesta conjunta</mark> del <mark class=\"m-autoridad\">Ministro de Asuntos Exteriores</mark> y del <mark class=\"m-autoridad\">Ministro de Justicia</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3024\">decidir la presentación de la denuncia de una situación ante el Fiscal de la Corte</mark>, de <mark class=\"m-personalizado\">conformidad con lo prevenido en los artículos</mark> 13, <mark class=\"m-personalizado\">párrafo</mark> a), y 14 del <mark class=\"m-personalizado\">Estatuto</mark> (<mark class=\"m-personalizado\">remisión de una situación</mark> por un <mark class=\"m-autoridad\">Estado Parte</mark>), y en su caso, para <mark class=\"m-accion\">instar</mark> de la <mark class=\"m-autoridad\">Sala de Cuestiones Preliminares</mark> que el <mark class=\"m-autoridad\">Fiscal</mark> <mark class=\"m-accion\">reconsidere</mark> su <mark class=\"m-destacable\">decisión</mark> de <u class=\"m-clave\">no</u> <mark class=\"m-personalizado\">iniciar actuaciones</mark>, <mark class=\"m-personalizado\">conforme</mark> al artículo 53.3.a) del Estatuto. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3025,1-ia-4005\">🎯 2 preguntas</mark></p><p><b>2.</b> <u class=\"m-clave\">Cuando</u> se <mark class=\"m-personalizado\">presentare</mark> una <mark class=\"m-destacable\">denuncia o querella</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">ante un <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">judicial</mark> o del <mark class=\"m-autoridad\">Ministerio Fiscal</mark> o una <mark class=\"m-destacable\">solicitud</mark> en un <mark class=\"m-personalizado\">departamento ministerial</mark>, en <mark class=\"m-personalizado\">relación con hechos sucedidos en otros</mark> <mark class=\"m-autoridad\">Estados</mark>, cuyos <mark class=\"m-personalizado\">presuntos autores</mark> <u class=\"m-clave\">no</u> sean <mark class=\"m-personalizado\">nacionales españoles</mark> y para cuyo <mark class=\"m-destacable\">enjuiciamiento</mark> <mark class=\"m-personalizado\">pudiera</mark> ser <mark class=\"m-personalizado\">competente</mark></span></span> la <mark class=\"m-autoridad\">Corte</mark>, dichos <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3026\">se abstendrán de todo procedimiento</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3026,1-ia-3116,1-ia-3904\">limitándose a informar al denunciante, querellante o solicitante de la posibilidad de acudir directamente al Fiscal de la Corte</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">que <mark class=\"m-accion\">podrá</mark>, en su caso, <mark class=\"m-personalizado\">iniciar</mark> una <mark class=\"m-destacable\">investigación</mark>, <u class=\"m-clave\">sin perjuicio</u> de <mark class=\"m-personalizado\">adoptar</mark>, si fuera <mark class=\"m-personalizado\">necesario</mark>, las <mark class=\"m-destacable\">primeras diligencias urgentes</mark> para las que <mark class=\"m-personalizado\">pudieran</mark> tener <mark class=\"m-destacable\">competencia</mark></span></span> . <span class=\"ex-plg\"><span class=\"ex-plg-t\">En <mark class=\"m-personalizado\">iguales circunstancias</mark>, los <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">judiciales</mark> y el <mark class=\"m-autoridad\">Ministerio Fiscal</mark> <mark class=\"m-accion\">se abstendrán</mark> de <mark class=\"m-personalizado\">proceder de oficio</mark>.</span></span></p><p><b>3.</b> <u class=\"m-clave\">No obstante</u>, si el <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">Fiscal de la Corte</mark> <u class=\"m-clave\">no</u> <mark class=\"m-personalizado\">acordara la apertura</mark> de la <mark class=\"m-destacable\">investigación</mark> o la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">acordara</mark> la <mark class=\"m-destacable\">inadmisibilidad</mark> del asunto, la <mark class=\"m-personalizado\">denuncia</mark>, <mark class=\"m-personalizado\">querella</mark> o <mark class=\"m-destacable\">solicitud</mark> <mark class=\"m-accion\">podrá</mark> ser <mark class=\"m-accion\">presentada nuevamente</mark> ante los <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">correspondientes</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3027\">🎯 1 pregunta</mark></p>"],["Artículo 8 — Del requerimiento de inhibición al Fiscal de la Corte <span class=\"ex-sello\">✱</span>","<p><b><mark class=\"m-personalizado\">Art. 8.</mark></b> <mark class=\"m-destacable\">1. Recibida</mark> <mark class=\"m-personalizado\">en el</mark> <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-personalizado\">de Justicia</mark> notificación <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">del</mark> <mark class=\"m-autoridad\">Fiscal</mark> <mark class=\"m-destacable\">de la</mark> <mark class=\"m-autoridad\">Corte</mark> de inicio <mark class=\"m-personalizado\">de una investigación</mark> conforme al artículo 18.1 del Estatuto, de tratarse de hechos <mark class=\"m-personalizado\">cuyo conocimiento podría corresponder a la jurisdicción española por</mark> haber <mark class=\"m-destacable\">acaecido</mark> <mark class=\"m-personalizado\">en territorio español u</mark> <mark class=\"m-destacable\">ostentar</mark> sus <mark class=\"m-destacable\">presuntos responsables</mark> la <mark class=\"m-personalizado\">nacionalidad española,</mark></span></span> dicho departamento ministerial <mark class=\"m-accion\">solicitará</mark> <mark class=\"m-autoridad\">del</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3028\">Fiscal General del Estado</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\"><u class=\"m-clave\">información urgente</u> sobre la existencia de actuaciones penales</mark> que se sigan o se hayan seguido <mark class=\"m-personalizado\">en</mark> relación con los hechos objeto de la investigación, así como sobre <mark class=\"m-personalizado\">si tienen competencia los</mark> <mark class=\"m-autoridad\">tribunales</mark> <mark class=\"m-personalizado\">españoles.</mark></span></span></p><p data-ex=\"*\"><b><mark class=\"m-personalizado\">2.</mark></b> <mark class=\"m-personalizado\">Cuando de</mark> la información suministrada por el <mark class=\"m-autoridad\">Fiscal</mark> <mark class=\"m-personalizado\">General del</mark> <mark class=\"m-autoridad\">Estado</mark> apareciera que se <mark class=\"m-personalizado\">ha ejercido jurisdicción</mark> <mark class=\"m-autoridad\">en</mark> <mark class=\"m-personalizado\">España,</mark> se está <mark class=\"m-personalizado\">ejerciendo o,</mark> como consecuencia de <mark class=\"m-personalizado\">la notificación recibida, se ha iniciado</mark> una investigación por las <mark class=\"m-autoridad\">autoridades</mark> españolas, <mark class=\"m-autoridad\">los Ministros de Justicia y de Asuntos Exteriores, en plazo que</mark> <mark class=\"m-plazo\">no</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-plazo\">rebasar los</mark> <mark class=\"m-resp\" data-q=\"1-ia-3029,1-236\">veinte días</mark> desde la recepción de la notificación del <mark class=\"m-autoridad\">Fiscal</mark> de la <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-accion\">elevarán</mark> <mark class=\"m-plazo\">propuesta</mark> conjunta al <mark class=\"m-autoridad\">Consejo de Ministros</mark> para que resuelva sobre sostener la competencia de las <mark class=\"m-autoridad\">autoridades</mark> españolas y, en su caso, pedir la inhibición <mark class=\"m-autoridad\">al Fiscal de la Corte</mark> conforme al artículo 18.2 del Estatuto. <mark class=\"m-resp ex-q\" data-q=\"1-219\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>3.</b> <mark class=\"m-personalizado\">Una vez aprobado el</mark> <mark class=\"m-destacable\">Acuerdo</mark> del <mark class=\"m-autoridad\">Consejo de Ministros</mark> del apartado anterior, <mark class=\"m-accion\">corresponderá</mark> al <mark class=\"m-resp\" data-q=\"1-111,1-ia-3030\">Ministerio de Justicia formular la petición de inhibición</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y realizar las restantes actuaciones previstas en el Estatuto para dar cumplimiento a dicho Acuerdo.</span></span></p><p data-ex=\"*\"><b>4.</b> El <mark class=\"m-autoridad\">Ministerio</mark> de Justicia <mark class=\"m-accion\">responderá</mark> con carácter urgente a cualquier petición de información del <mark class=\"m-autoridad\">Fiscal</mark> de la <mark class=\"m-autoridad\">Corte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">referida al estado de los procedimientos penales que se siguieren en España y que hubieren sido objeto de petición de inhibición,</span></span> recabando dicha información <mark class=\"m-resp\" data-q=\"1-237\">del <mark class=\"m-autoridad\">Fiscal</mark> General del <mark class=\"m-autoridad\">Estado</mark> o directamente del <mark class=\"m-autoridad\">órgano</mark> judicial que estuviere conociendo del asunto</mark>. La información <mark class=\"m-accion\">se transmitirá</mark> con los límites de utilización que estableciere <mark class=\"m-resp r-ia\" data-q=\"1-ia-3031\">el órgano judicial que autorizare la información</mark>.</p><p><b>5.</b> <mark class=\"m-personalizado\">Cuando de la información suministrada por el</mark> <mark class=\"m-autoridad\">Fiscal General del Estado</mark> de conformidad <span class=\"ex-plg\"><span class=\"ex-plg-t\">con el apartado 1 resulte que <mark class=\"m-personalizado\">no se ha ejercido jurisdicción, ni se está ejerciendo,</mark> <mark class=\"m-destacable\">ni</mark> se ha <mark class=\"m-personalizado\">iniciado investigación</mark> en <mark class=\"m-autoridad\">España, el Ministerio de Justicia</mark> <mark class=\"m-personalizado\">lo</mark> <mark class=\"m-accion\">comunicará</mark> <mark class=\"m-personalizado\">urgentemente al</mark> <mark class=\"m-autoridad\">Fiscal de la Corte.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3032\">🎯 1 pregunta</mark></p>"],["Artículo 9 — De la impugnación de la competencia de la Corte o de la admisibilidad de la causa <span class=\"ex-sello\">✱</span>","<p><b>1.</b> Corresponde exclusivamente <mark class=\"m-autoridad\">al</mark> <mark class=\"m-resp\" data-q=\"1-118\">Gobierno, mediante Acuerdo del Consejo de Ministros</mark> <mark class=\"m-destacable\">(igual que para denunciar una situación, art. 7), a propuesta conjunta del Ministro de</mark> Justicia y del Ministro de Asuntos Exteriores, acordar la impugnación de <mark class=\"m-destacable\">la competencia de la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-destacable\">o de la admisibilidad de la causa</mark>, de conformidad <mark class=\"m-destacable\">con <u class=\"m-clave\">lo</u></mark> previsto en los artículos 17 y 19 del <mark class=\"m-personalizado\">Estatuto</mark>, <mark class=\"m-personalizado\">cuando los</mark> <mark class=\"m-autoridad\">tribunales</mark> <mark class=\"m-personalizado\">españoles hayan conocido</mark> del asunto <mark class=\"m-personalizado\">y</mark> haya recaído <mark class=\"m-personalizado\">sentencia</mark>, <mark class=\"m-destacable\">o</mark> se haya decretado el <mark class=\"m-personalizado\">sobreseimiento</mark> libre de la causa <u class=\"m-clave\">o</u> <mark class=\"m-personalizado\">estén conociendo</mark> del asunto. <mark class=\"m-personalizado\">Dicho <u class=\"m-clave\">acuerdo</u></mark> <mark class=\"m-accion\">habilitará</mark>, en su caso, <mark class=\"m-autoridad\">al Ministerio de Justicia</mark> <mark class=\"m-personalizado\">para llevar a cabo la impugnación</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3033\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>2.</b> Tal impugnación <mark class=\"m-accion\">se formalizará</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4030\">a la mayor brevedad posible, antes del inicio del juicio en la Corte</mark> <mark class=\"m-plazo\">y, excepcionalmente</mark>, <mark class=\"m-plazo\">en el momento de su iniciación o en un momento posterior</mark>, <mark class=\"m-personalizado\">fundándose en este último caso en el solo motivo</mark> de <mark class=\"m-resp\" data-q=\"1-ia-3007,1-ia-3034,1-238\">haberse producido ya cosa juzgada en España</mark>.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Inhibición a favor de la Corte (arts. 8-10)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">8</span><mark class=\"m-resp\" data-q=\"1-231\">Solicitud de inhibición al Fiscal de la Corte (art. 8)</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">9</span><mark class=\"m-resp r-ia\" data-q=\"1-ia-3808\">Impugnación de la competencia o admisibilidad (art. 9)</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">=</span><mark class=\"m-autoridad\">La Sala</mark> <mark class=\"m-personalizado\">competente</mark> <mark class=\"m-autoridad\">de la Corte</mark> <mark class=\"m-resp\" data-q=\"1-169\">autoriza al Fiscal a proceder a la investigación o mantiene su competencia</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso si\"><span class=\"et\">10</span>El <mark class=\"m-autoridad\">órgano jurisdiccional español</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3035\">se inhibirá a favor de la Corte y a su solicitud le remitirá lo actuado</mark></div>"],["Artículo 11 — De la detención · R3 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R3</span>","<p data-ex=\"*\" data-r=\"R3\"><span class=\"ex-sello ex-sello-r\">R3</span> <b>1.</b> Cuando fuere <mark class=\"m-destacable\">detenida</mark> una persona, en cumplimiento de una orden de la <mark class=\"m-autoridad\">Corte</mark> de detención provisional o de detención y entrega, la <mark class=\"m-autoridad\">autoridad</mark> que practicare la detención <mark class=\"m-autoridad\">lo</mark> <mark class=\"m-accion\">comunicará</mark> <mark class=\"m-autoridad\">inmediatamente</mark> <mark class=\"m-resp\" data-q=\"1-111\">al Ministerio de Justicia y al Juez Central de Instrucción de la Audiencia Nacional</mark>, debiendo ser <mark class=\"m-personalizado\">puesta dicha persona a disposición</mark> del <mark class=\"m-autoridad\">Juez</mark> Central <mark class=\"m-personalizado\">de Instrucción</mark> <mark class=\"m-resp\" data-q=\"1-115,1-ia-3036\">sin demora y, en todo caso, dentro del plazo de setenta y dos horas siguientes a la detención</mark>.</p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-autoridad\">El Juez Central de Instrucción</mark> <mark class=\"m-accion\">oirá</mark> a la <mark class=\"m-personalizado\">persona</mark> reclamada, asistida de <mark class=\"m-personalizado\">letrado</mark> y, en su caso, de <mark class=\"m-personalizado\">intérprete y al</mark> <mark class=\"m-autoridad\">Ministerio Fiscal,</mark> <mark class=\"m-resp\" data-q=\"1-ia-3037,1-239\">dentro de las setenta y dos horas siguientes a su puesta a disposición judicial</mark>. <mark class=\"m-personalizado\">Después de verificar la identidad</mark> del detenido, <mark class=\"m-personalizado\">el <u class=\"m-clave\">contenido</u> de la orden</mark> de detención <mark class=\"m-destacable\">y</mark> las <mark class=\"m-personalizado\">circunstancias</mark> previstas en el artículo 59.2 del Estatuto <mark class=\"m-accion\">informará</mark> al detenido del <mark class=\"m-personalizado\">contenido</mark> de la orden de detención <mark class=\"m-personalizado\">y de su <u class=\"m-clave\">derecho</u> a <u class=\"m-clave\">solicitar</u> la <u class=\"m-clave\">libertad</u></mark> provisional. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3038\">🎯 1 pregunta</mark></p><p><b>3.</b> (…) <mark class=\"m-autoridad\">la autoridad penitenciaria competente</mark> <mark class=\"m-accion\">informará</mark> <mark class=\"m-personalizado\">con antelación suficiente sobre la fecha de excarcelación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">al Juez Central de Instrucción</mark> <mark class=\"m-destacable\">y</mark> <mark class=\"m-autoridad\">al Ministerio de Justicia,</mark> <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">informará</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-autoridad\">la Corte</mark> (…).</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3039\">🎯 1 pregunta</mark></p>"],["Artículo 12 — De la libertad provisional <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 12.</b> 1. Si el detenido solicitara, en la comparecencia prevista en el artículo anterior, <mark class=\"m-personalizado\">su libertad</mark> provisional, <mark class=\"m-autoridad\">el Juez Central de</mark> Instrucción <mark class=\"m-accion\">acordará</mark> <mark class=\"m-destacable\">remitir dicha solicitud a la</mark> <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-resp\" data-q=\"1-111\">a través del Ministerio de Justicia</mark>, <mark class=\"m-personalizado\">con indicación del <u class=\"m-clave\">plazo</u></mark> para recibir sus recomendaciones, que <mark class=\"m-resp\" data-q=\"1-ia-3040,1-240\">no será inferior a veinte días</mark>.</p><p><mark class=\"m-personalizado\">En la misma resolución</mark> <mark class=\"m-autoridad\">el Juez Central de Instrucción</mark> <mark class=\"m-accion\">acordará</mark> <mark class=\"m-personalizado\">la prisión provisional</mark> del detenido <mark class=\"m-resp r-ia\" data-q=\"1-ia-3041\">por el tiempo estrictamente necesario para recibir las recomendaciones de la Corte sobre dicha solicitud y hasta que se resuelva sobre ésta</mark>.</p><p><b>2.</b> Una vez recibida, a través del <mark class=\"m-autoridad\">Ministerio</mark> de Justicia, la comunicación de la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">con las recomendaciones</mark> que ésta formule sobre la solicitud de libertad, o <mark class=\"m-personalizado\">concluido el plazo</mark> señalado para su formulación, el <mark class=\"m-autoridad\">Juez Central de Instrucción,</mark> <mark class=\"m-personalizado\">previa valoración</mark> de dichas recomendaciones, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">acordar la libertad provisional</mark> del detenido cuando <mark class=\"m-personalizado\">existan circunstancias urgentes y excepcionales</mark> que lo justifiquen <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">las salva guardias</u> necesarias</mark> para cumplir la obligación de entregar la persona a la <mark class=\"m-autoridad\">Corte</mark> y, <mark class=\"m-personalizado\">en</mark> especial, las medidas recomendadas al efecto por ésta.  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3042\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF\"><b>3.</b> <mark class=\"m-personalizado\">Si en el plazo</mark> establecido en las reglas de procedimiento y prueba <mark class=\"m-autoridad\">la Corte</mark> no <mark class=\"m-personalizado\">hubiera <u class=\"m-clave\">remitido</u> la documentación para la entrega</mark> prevista en el artículo 91.2 y 3 del Estatuto, el <mark class=\"m-autoridad\">Juez Central de Instrucción</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">acordar la <u class=\"m-clave\">libertad</u></mark> provisional <mark class=\"m-personalizado\">y las <u class=\"m-clave\">medidas</u></mark> cautelares adecuadas, <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">se mantendrán</mark> por un <mark class=\"m-resp r-ia\" data-q=\"1-ia-3043\">tiempo máximo de ciento ochenta días</mark>, <mark class=\"m-resp\" data-q=\"1-129,1-ia-3950\">sin perjuicio de volver a decretar la prisión una vez recibida la documentación de la Corte</mark>.</p><p data-ex=\"*\"><b>4.</b> <mark class=\"m-personalizado\">Cuando se acordare la libertad</mark> provisional, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">informará</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-autoridad\">la</mark> <mark class=\"m-resp\" data-q=\"1-89\">Sala de Cuestiones Preliminares</mark> <mark class=\"m-plazo\">y,</mark> <span class=\"m-caja\"><mark class=\"m-plazo\">posteriormente, cuantas</mark></span> <mark class=\"m-plazo\">veces ésta</mark> <span class=\"m-caja\"><mark class=\"m-plazo\">lo</mark></span> solicite. <mark class=\"m-resp ex-q\" data-q=\"1-241,1-ia-3044\">🎯 2 preguntas</mark></p>"],["Artículo 13 — De la entrega simplificada <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> <mark class=\"m-personalizado\">En la comparecencia</mark> regulada en el artículo 11 de esta ley <mark class=\"m-accion\">se interrogará</mark> a la persona reclamada acerca de <mark class=\"m-personalizado\">si</mark> <mark class=\"m-destacable\">consiente</mark> <mark class=\"m-personalizado\">en su entrega</mark> y, si <u class=\"m-clave\">diere</u> el consentimiento, <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">Juez</mark> <mark class=\"m-personalizado\">Central de Instrucción</mark> <mark class=\"m-accion\">dictará</mark> <mark class=\"m-personalizado\">auto acordando la <u class=\"m-clave\">entrega</u> a la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-resp\" data-q=\"1-ia-3045,1-242\">sin más trámites y sin que sea necesario que la Corte remita la documentación prevista en el artículo 91 del Estatuto</mark>.</p><p><mark class=\"m-personalizado\">Se</mark> <mark class=\"m-accion\">procederá</mark> <mark class=\"m-personalizado\">de la misma manera si también consiente en la entrega respecto a otros hechos no <u class=\"m-clave\">comprendidos</u> en la solicitud</mark> de la <mark class=\"m-autoridad\">Corte</mark> (…) y, si no accediere, <mark class=\"m-resp\" data-q=\"1-231\">la entrega se efectuará sólo por los hechos contenidos en la solicitud</mark>, sin perjuicio de lo que proceda, después de la entrega, en aplicación del apartado 2 del artículo 101 del Estatuto (principio de especialidad). Fuera de este caso, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3046\"><mark class=\"m-accion\">no se admitirá</mark> un consentimiento parcial</mark>.</p><p data-ex=\"*\"><b>3.</b> La persona reclamada, <mark class=\"m-personalizado\">aunque se hubiere opuesto</mark> a la entrega en la citada comparecencia, <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">dar su consentimiento</mark> <mark class=\"m-resp\" data-q=\"1-ia-3047,1-243\">dentro de los quince días siguientes</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, procediéndose en tal caso conforme a lo pre- venido en los apartados precedentes</span></span>.</p><p data-ex=\"*\"><b>4.</b> En la misma comparecencia <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">informará</mark> al detenido de que <mark class=\"m-personalizado\">el consentimiento</mark>, una vez dado, es <mark class=\"m-destacable\"><mark class=\"m-resp\" data-q=\"1-244,1-ia-3048\">irrevocable</mark></mark>.</p>"],["Artículo 14 — De la orden de comparecencia de un imputado ante la Corte <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\">Cuando, en lugar de una solicitud <mark class=\"m-destacable\">de detención</mark>, <mark class=\"m-destacable\">la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-destacable\">hubiere dictado una orden de comparecencia</mark>, el <mark class=\"m-autoridad\">Ministerio</mark> de Justicia <mark class=\"m-accion\">remitirá</mark> la solicitud <mark class=\"m-destacable\">de la</mark> <mark class=\"m-autoridad\">Corte</mark> al <mark class=\"m-resp\" data-q=\"1-130,1-ia-3049,1-ia-4204\">juez de instrucción del domicilio o residencia de la persona buscada</mark>, el <mark class=\"m-personalizado\">cual</mark> <mark class=\"m-accion\">citará</mark> <mark class=\"m-personalizado\">a</mark> ésta <mark class=\"m-personalizado\">personalmente</mark>, informándole de la <mark class=\"m-personalizado\">fecha y demás</mark> circunstancias relativas <mark class=\"m-personalizado\">a dicha comparecencia</mark>, <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-personalizado\">las medidas de aseguramiento de la comparecencia</mark> previstas en la legislación procesal española que considere más adecuadas, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3050\">con exclusión de las privativas de libertad</mark>, <mark class=\"m-personalizado\">remitiendo</mark> las diligencias practicadas <mark class=\"m-autoridad\">al Ministerio de Justicia</mark>, que <mark class=\"m-personalizado\">las</mark> <mark class=\"m-accion\">transmitirá</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-autoridad\">la Corte</mark>.</p>"],["Artículo 15 — De la entrega a la Corte · R4 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R4</span>","<p data-ex=\"*\"><b>1.</b> <mark class=\"m-personalizado\">No habiéndose accedido a la entrega simplificada</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">cuando hubiera sido detenida una persona en cum- plimiento de una orden de la Corte de detención y entrega o una vez recibida en el Juzgado Central de Instrucción la documentación prevista en el artículo 91.2 o 3 del Estatuto, según los casos,</span></span> <mark class=\"m-accion\">se pondrá</mark> <mark class=\"m-personalizado\">ésta de manifiesto en</mark> <mark class=\"m-autoridad\">Secretaría</mark> y <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">convocará</mark> <mark class=\"m-personalizado\">a una</mark> <mark class=\"m-autoridad\">audiencia</mark> que <mark class=\"m-accion\">tendrá</mark> lugar <mark class=\"m-resp\" data-q=\"1-ia-3051,1-245\">en el plazo máximo de diez días</mark>, <mark class=\"m-personalizado\">con citación de la persona</mark> reclamada y <mark class=\"m-personalizado\">su</mark> <mark class=\"m-autoridad\">defensor</mark> y, en su caso, de un intérprete, así como del <mark class=\"m-autoridad\">Ministerio Fiscal</mark>. A dicha <mark class=\"m-autoridad\">audiencia</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">asistir e <u class=\"m-clave\">intervenir</u></mark> <mark class=\"m-autoridad\">un delegado del Fiscal</mark> de la <mark class=\"m-autoridad\">Corte.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3052\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">Cuando se alegare la excepción</mark> de cosa juzgada, el <mark class=\"m-autoridad\">Juzgado</mark> Central de Instrucción <mark class=\"m-resp r-ia\" data-q=\"1-ia-3055\">lo comunicará al Ministerio de Justicia, aplazando la resolución sobre la entrega</mark>, mientras el <mark class=\"m-autoridad\">Ministerio</mark> de Justicia efectúa las <mark class=\"m-resp r-ia\" data-q=\"1-ia-3053\">consultas con la Corte previstas en el artículo 89.2 del Estatuto</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">Si de tales consultas resultare que la causa ha sido declarada admisible por la <mark class=\"m-autoridad\">Corte, el Juzgado</mark> Central <mark class=\"m-personalizado\">de</mark> Instrucción <mark class=\"m-accion\">alzará</mark> la suspensión. (…)</span></span></p><p data-ex=\"*\" data-r=\"R4\"><span class=\"ex-sello ex-sello-r\">R4</span> <b>3.</b> Concluida la <mark class=\"m-personalizado\">vista,</mark> <mark class=\"m-autoridad\">el Juzgado Central de Instrucción</mark> <mark class=\"m-accion\">resolverá</mark> sobre la petición de entrega, por medio de <mark class=\"m-personalizado\">auto,</mark> <mark class=\"m-resp\" data-q=\"1-ia-3054,1-190\">en el plazo de tres días</mark>.</p><p data-ex=\"*\"><b>5.</b> (…) 6. <mark class=\"m-personalizado\">Si la resolución fuere</mark> <mark class=\"m-destacable\">denegatoria</mark> de la entrega, <mark class=\"m-personalizado\">una vez firme,</mark> <mark class=\"m-accion\">se pondrá</mark> <mark class=\"m-personalizado\"><mark class=\"m-resp\" data-q=\"1-246\">urgentemente en libertad</mark></mark> a la persona detenida <span class=\"ex-plg\"><span class=\"ex-plg-t\">y se comunicará al Ministerio de Justicia, que a su vez lo hará a la Corte</span></span>.</p>"],["Artículo 16 — De las solicitudes concurrentes <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> <mark class=\"m-personalizado\">Cuando concurriere con</mark> la solicitud de entrega de la <mark class=\"m-autoridad\">Corte</mark> una solicitud de <mark class=\"m-destacable\">extradición</mark> <mark class=\"m-personalizado\">de un</mark> <mark class=\"m-autoridad\">Estado,</mark> sea o no parte en <mark class=\"m-personalizado\">el</mark> Estatuto, <mark class=\"m-personalizado\">o una orden europea de detención y entrega</mark>, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">notificará</mark> este hecho a <mark class=\"m-autoridad\">la Corte y al Estado</mark> requirente <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-resp\" data-q=\"1-ia-3056,1-247\">se tramitarán conjuntamente ambos procedimientos en el Juzgado Central de Instrucción que estuviere conociendo de la solicitud de entrega</mark>.</p><p><b>2.</b> <mark class=\"m-autoridad\">El Juez Central de Instrucción</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">se</u></mark> <mark class=\"m-accion\">abstendrá</mark> <mark class=\"m-personalizado\">de decidir</mark> <u class=\"m-clave\">sobre</u> la <mark class=\"m-personalizado\">entrega</mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">elevando</u> ambos procesos</mark> a la <mark class=\"m-resp\" data-q=\"1-233\">Sala de lo Penal de la Audiencia Nacional</mark>, que <mark class=\"m-accion\">resolverá</mark> <mark class=\"m-personalizado\">de acuerdo</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">con el</mark></span> <mark class=\"m-personalizado\">Estatuto</mark> y, en su caso, de acuerdo con <mark class=\"m-personalizado\">el tratado</mark> que existiere <mark class=\"m-personalizado\">con el</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">requirente</mark>. <mark class=\"m-personalizado\">Cuando <u class=\"m-clave\">no</u> existiere</mark> tratado, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3057\">se dará preferencia a la solicitud de la Corte</mark>.</p></div></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Detención y entrega a la Corte (LO 18/2003, arts. 11-17)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span><u class=\"m-clave\">Detención</u> en cumplimiento de una <mark class=\"m-destacable\">orden</mark> <mark class=\"m-autoridad\">de la Corte</mark> (<mark class=\"m-personalizado\">art</mark>. 11)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span>La <mark class=\"m-autoridad\">autoridad</mark> que detiene lo comunica <mark class=\"m-plazo\">inmediatamente</mark> <mark class=\"m-resp\" data-q=\"1-233,1-ia-3058,1-ia-3059\">al Ministerio de Justicia y al Juez Central de Instrucción de la Audiencia Nacional</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span>A <mark class=\"m-personalizado\">disposición</mark> del JCI <mark class=\"m-resp\" data-q=\"1-233,1-ia-3058,1-ia-3059\">sin demora y, en todo caso, dentro del plazo de setenta y dos horas</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">4</span>El JCI oye a <mark class=\"m-personalizado\">la persona</mark> reclamada (con <mark class=\"m-personalizado\">letrado</mark> e <mark class=\"m-personalizado\">intérprete</mark>) y <mark class=\"m-autoridad\">al Fiscal</mark> <mark class=\"m-resp\" data-q=\"1-233,1-ia-3058,1-ia-3059\">dentro de las setenta y dos horas siguientes</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">5</span>Se pregunta <mark class=\"m-personalizado\">si</mark> <mark class=\"m-destacable\">consiente</mark> <mark class=\"m-personalizado\">en su entrega</mark> (<mark class=\"m-destacable\">art. 13</mark>)</div><div class=\"vis-flecha\">↓</div><div class=\"vis-bifurca\"><div class=\"vis-paso si\"><span class=\"et\">SÍ</span><mark class=\"m-personalizado\">Auto</mark> de <mark class=\"m-personalizado\">entrega</mark> <mark class=\"m-resp\" data-q=\"1-233,1-ia-3058,1-ia-3059\">sin más trámites</mark> y <u class=\"m-clave\">sin</u> documentación del <mark class=\"m-personalizado\">art</mark>. 91 del <mark class=\"m-personalizado\">Estatuto</mark> · <u class=\"m-clave\">consentimiento</u> <mark class=\"m-destacable\">irrevocable</mark></div><div class=\"vis-paso no\"><span class=\"et\">NO</span><mark class=\"m-autoridad\">Audiencia</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3058\">en el plazo máximo de diez días</mark> (<mark class=\"m-personalizado\">art</mark>. 15) · el JCI resuelve <mark class=\"m-personalizado\">por auto</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3058\">en el plazo de tres días</mark></div></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">6</span>Recursos (<mark class=\"m-personalizado\">art</mark>. 17): apelación <mark class=\"m-resp\" data-q=\"1-233\">ante la Sala de lo Penal de la Audiencia Nacional</mark> · situación <mark class=\"m-personalizado\">personal</mark>: <mark class=\"m-personalizado\">art</mark>. 766 LECrim, <mark class=\"m-personalizado\">auto</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3058\">en el plazo de cinco días</mark> · <mark class=\"m-personalizado\">los autos</mark> de <mark class=\"m-autoridad\">la Sala</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3059\">no serán susceptibles de recurso alguno</mark></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 17 — De los recursos <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>: <mark class=\"m-resp ex-q\" data-q=\"1-248\">🎯 1 pregunta más de este artículo</mark></div><div class=\"vis\"><div class=\"vis-t\"><i>➜</i>Entrega temporal (art. 18)</div><div class=\"vis-flujo\"><div class=\"vis-paso \"><span class=\"et\">1</span><mark class=\"m-personalizado\">Entrega</mark> acordada y <mark class=\"m-personalizado\">la persona</mark> <mark class=\"m-personalizado\">está</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3066\">cumpliendo condena en España o sujeta a proceso por hechos distintos</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">2</span><mark class=\"m-accion\">Justicia</mark> <u class=\"m-clave\">consulta</u> con <mark class=\"m-autoridad\">la Corte</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3451\">si no se opusiere el Tribunal sentenciador o el instructor</mark></div><div class=\"vis-flecha\">↓</div><div class=\"vis-paso \"><span class=\"et\">3</span><mark class=\"m-destacable\">Resolución</mark> motivada, con las <mark class=\"m-personalizado\">modalidades</mark> de restitución a <mark class=\"m-personalizado\">España</mark> · <mark class=\"m-resp r-ia\" data-q=\"1-ia-4030\">se computa el período pasado a disposición de la Corte</mark></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 18 — De <mark class=\"m-destacable\">la entrega</mark> temporal <mark class=\"m-autoridad\">a la Corte</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3060\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 19 — De las actuaciones posteriores a la entrega","<p><b>1.</b> <mark class=\"m-personalizado\">Si</mark>, <mark class=\"m-personalizado\">después de la entrega</mark>, <mark class=\"m-autoridad\">la Corte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">pidiere autorización</mark> a España para proceder por una conducta <mark class=\"m-personalizado\">anterior</mark> a</span></span> la entrega, <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">trasladará</mark> <mark class=\"m-personalizado\">la petición</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4204\">al Juzgado Central de Instrucción, o a la Sala de lo Penal en el caso previsto en el artículo 16</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">esta ley <mark class=\"m-personalizado\">(solicitudes concurrentes</mark>), <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">resolverán</mark> de acuerdo con el criterio establecido en el apartado 2 del artículo 101 del Estatuto.</span></span>  (…)</p><p><b>2.</b> <mark class=\"m-personalizado\">Cuando</mark> la persona entregada fuere <mark class=\"m-personalizado\">puesta en libertad por</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">por razones distintas del cumplimiento de la sentencia y</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">se propusiera trasladarla a</mark> <mark class=\"m-autoridad\">otro Estado,</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">remitirá</mark> <mark class=\"m-personalizado\">esta información</mark> <mark class=\"m-resp\" data-q=\"1-233\">al Juzgado Central de Instrucción de la Audiencia Nacional</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">y,</u></mark> en su caso, <mark class=\"m-personalizado\">por</mark> <mark class=\"m-autoridad\">el Ministerio de Justicia</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">dará</mark> <mark class=\"m-personalizado\">el <u class=\"m-clave\">consentimiento</u></mark> de España para tal traslado <mark class=\"m-personalizado\">o</mark> <mark class=\"m-accion\">se solicitará</mark> su <mark class=\"m-personalizado\"><u class=\"m-clave\">devolución</u></mark> a España <mark class=\"m-personalizado\">si la razón de la puesta en libertad se debiere</mark> a que la causa fue declarada <mark class=\"m-personalizado\">inadmisible por</mark> la <mark class=\"m-autoridad\">Corte</mark> por el motivo previsto en el artículo 17.1.a) del Estatuto (asunto investigado <mark class=\"m-destacable\">o enjuiciado por un</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-destacable\">con jurisdicción).</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3061,1-ia-3363\">🎯 2 preguntas</mark></p>"],["Artículo 20 — De otras formas de cooperación con la Corte <span class=\"ex-sello\">✱</span>","<p><b>1.</b> <mark class=\"m-autoridad\">Los órganos judiciales y las restantes autoridades</mark> intervinientes <mark class=\"m-accion\">darán</mark> <mark class=\"m-personalizado\">cumplimiento a las solicitudes de cooperación</mark> formuladas <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">por</mark> <mark class=\"m-autoridad\">la Corte</mark> previstas en el</span></span> artículo 93 del Estatuto <mark class=\"m-personalizado\">que</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3062\">no estuvieran prohibidas en la legislación española y cuyo fin fuera también facilitar el proceso ante la Corte</mark>.</p><p data-ex=\"*\"><b>2.</b> <mark class=\"m-personalizado\">Cuando la solicitud de</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">pudiera afectar a la defensa <u class=\"m-clave\">o a la seguridad nacionales</u> o</mark> tenga por objeto <mark class=\"m-personalizado\">documentos</mark> o informaciones que hubieren sido <span class=\"m-circulo\"><mark class=\"m-personalizado\">transmitidos</mark></span> <mark class=\"m-personalizado\">a España con</mark> <mark class=\"m-destacable\">carácter confidencial por</mark> <mark class=\"m-personalizado\">un</mark> <mark class=\"m-autoridad\">Estado,</mark> <mark class=\"m-personalizado\">una organización</mark> internacional o una organización intergubernamental, el <mark class=\"m-resp\" data-q=\"1-131,1-ia-3022,1-ia-3063\">Ministerio de Asuntos Exteriores, en coordinación con los Ministerios de Justicia, del Interior y de Defensa</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">u</u></mark> <mark class=\"m-destacable\">otros</mark> <mark class=\"m-autoridad\">Ministerios</mark> <mark class=\"m-destacable\">competentes</mark>, <mark class=\"m-accion\">efectuará</mark> <mark class=\"m-personalizado\">consultas</mark> con <mark class=\"m-autoridad\">el Estado u organización</mark> <mark class=\"m-personalizado\">de que proceda</mark> <mark class=\"m-autoridad\">la información</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o documentación, informándose a la Corte del resultado de tales consultas</span></span>.</p><p><b>5.</b> En el caso de concurrencia <span class=\"ex-plg\"><span class=\"ex-plg-t\">de solicitudes de asistencia de la <mark class=\"m-autoridad\">Corte</mark> y de un <mark class=\"m-autoridad\">Estado,</mark> si aparecieren dificultades para atender a ambas, el <mark class=\"m-autoridad\">Ministerio</mark> de Justicia <mark class=\"m-accion\">celebrará</mark> consultas con la <mark class=\"m-autoridad\">Corte</mark> y dicho</span></span> <mark class=\"m-autoridad\">Estado,</mark> con el fin de <mark class=\"m-resp r-ia\" data-q=\"1-ia-3064\">postergar o condicionar una de ellas</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">informando en su caso a la <mark class=\"m-autoridad\">Corte,</mark> conforme al artículo 93.9.b) del Estatuto, de que las informaciones, bienes o personas objeto de la solicitud están bajo el control de un tercer <mark class=\"m-autoridad\">Estado</mark> u organización internacional.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4005\">🎯 1 pregunta</mark></p>"],["Artículo 21 — De las personas sujetas a la jurisdicción de la Corte · R5 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R5</span>","<p data-ex=\"*\" data-r=\"R5\"><span class=\"ex-sello ex-sello-r\">R5</span> <b>Art. 21.</b> 1. Las personas citadas como <mark class=\"m-destacable\">peritos o testigos</mark> <mark class=\"m-personalizado\">para comparecer ante los</mark> <mark class=\"m-autoridad\">tribunales</mark> <mark class=\"m-personalizado\">españoles en cumplimiento de una</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">comisión</u></mark> <mark class=\"m-personalizado\">rogatoria expedida</mark> por la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-resp\" data-q=\"1-191\">las mismas obligaciones y responsabilidades que si hubieren sido citadas en una causa que se siguiere en España</mark>.</p><p><mark class=\"m-personalizado\">Si la comparecencia fuere en la sede de</mark> <mark class=\"m-autoridad\">la</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">Corte,</mark></span> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3065\">carácter voluntario</mark>, <mark class=\"m-personalizado\">solicitándose de ésta</mark> por el <mark class=\"m-autoridad\">Ministerio de Justicia</mark> <mark class=\"m-personalizado\">información</mark> acerca de las <mark class=\"m-personalizado\">inmunidades y plazo</mark> de vigencia para la persona citada, <mark class=\"m-autoridad\">que</mark> <mark class=\"m-accion\">será</mark> transmitida a dicha persona, <mark class=\"m-personalizado\">anticipándose los gastos por</mark> <mark class=\"m-autoridad\">el Ministerio de Justicia.</mark> <mark class=\"m-personalizado\">Si</mark> la <mark class=\"m-autoridad\">Corte</mark> hubiere remitido alguna <mark class=\"m-personalizado\">instrucción sobre</mark> la regla relativa a la <mark class=\"m-personalizado\">autoinculpación, se</mark> <mark class=\"m-accion\">entregará</mark> dicho documento <mark class=\"m-personalizado\">al testigo y el</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">judicial</mark> <mark class=\"m-accion\">se cerciorará</mark> de que ha sido debidamente entendido.</p><p><mark class=\"m-accion\">No será</mark> <mark class=\"m-personalizado\">necesario el</mark> <mark class=\"m-destacable\">consentimiento</mark> <mark class=\"m-personalizado\">cuando se tratare de</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3066\">un condenado por la Corte que se encontrare cumpliendo condena en España</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">en cuyo caso <mark class=\"m-accion\">se efectuará</mark> el traslado temporal, en las condiciones que se acuerden con la <mark class=\"m-autoridad\">Corte.</mark></span></span></p><p><b>3.</b> Las personas en tránsito <span class=\"ex-plg\"><span class=\"ex-plg-t\">en España para comparecer ante la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">gozarán</mark> de inmunidad.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3067\">🎯 1 pregunta</mark></p><p><b>5.</b> El <mark class=\"m-autoridad\">Ministerio de Justicia,</mark> <mark class=\"m-accion\">en</mark> <mark class=\"m-autoridad\">coordinación con el Ministerio del Interior y,</mark> en <span class=\"ex-plg\"><span class=\"ex-plg-t\">su caso, con otras Administraciones competentes, <mark class=\"m-accion\">podrá convenir</mark> con el</span></span> <mark class=\"m-autoridad\">Secretario</mark> de la <mark class=\"m-autoridad\">Corte</mark> la <mark class=\"m-resp r-ia\" data-q=\"1-ia-3068\">acogida temporal de víctimas traumatizadas o de testigos que pudieran correr peligro por su testimonio</mark>.</p>"],["Artículo 22 — De la ejecución de las penas en España <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>1.</b> De <mark class=\"m-personalizado\">conformidad</mark> con el <mark class=\"m-destacable\">acuerdo</mark> que <mark class=\"m-personalizado\">eventualmente se celebre</mark> entre España y la <mark class=\"m-autoridad\">Corte</mark> y con la <mark class=\"m-personalizado\">disposición adicional</mark> única de la Ley <mark class=\"m-personalizado\">Orgánica</mark> 6/2000 <span class=\"ex-plg\"><span class=\"ex-plg-t\">, de 4 de octubre, por la que se autoriza la ratificación por España del Estatuto de la Corte Penal Internacional</span></span>, el <mark class=\"m-autoridad\">Ministerio de Justicia</mark>, <mark class=\"m-personalizado\">previas las consultas oportunas</mark>, <mark class=\"m-accion\">comunicará</mark> a la <mark class=\"m-autoridad\">Corte</mark> las <mark class=\"m-personalizado\">condiciones</mark> en las que España <mark class=\"m-personalizado\">estuviese dispuesta a aceptar</mark> el <mark class=\"m-destacable\">traslado de un condenado</mark> a <mark class=\"m-destacable\">pena</mark> <mark class=\"m-personalizado\">privativa</mark> de <mark class=\"m-destacable\">libertad</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o las razones que impidiesen la aceptación de dicho traslado</span></span>. <mark class=\"m-resp ex-q\" data-q=\"1-249\">🎯 1 pregunta</mark></p><p>Por el <mark class=\"m-autoridad\">Ministerio de Justicia</mark> <mark class=\"m-accion\">se transmitirán</mark> las <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">oportunas informaciones</mark> al <mark class=\"m-autoridad\">Ministerio del Interior</mark> para la <mark class=\"m-personalizado\">realización del traslado</mark>, <mark class=\"m-personalizado\">debiendo comunicarse</mark> por las</span></span> <mark class=\"m-autoridad\">autoridades penitenciarias</mark> al <mark class=\"m-autoridad\">juez de vigilancia penitenciaria</mark> <mark class=\"m-personalizado\">competente la llegada del recluso</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3069\">en un plazo de veinticuatro horas</mark>.</p><p><b>2.</b> (…) 3. Los <mark class=\"m-autoridad\">jueces de vigilancia penitenciaria</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y el <mark class=\"m-autoridad\">Ministerio del Interior</mark> <mark class=\"m-accion\">prestarán</mark> el <mark class=\"m-personalizado\">máximo apoyo</mark> a <mark class=\"m-autoridad\">Magistrados y funcionarios de la Corte</mark> que se <mark class=\"m-personalizado\">personaren</mark> en España para <mark class=\"m-accion\">supervisar</mark> la <mark class=\"m-destacable\">ejecución de las penas</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3102\">🎯 1 pregunta</mark></p><p><b>4.</b> Para que se pueda <mark class=\"m-personalizado\">proceder</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en España contra un <mark class=\"m-personalizado\">condenado que estuviere cumpliendo una condena impuesta</mark> por la <mark class=\"m-autoridad\">Corte</mark> en un <mark class=\"m-personalizado\">establecimiento penitenciario español</mark>, por <mark class=\"m-personalizado\">hechos anteriores a su entrega</mark> a España,</span></span> el <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-personalizado\">instructor o el</mark> <mark class=\"m-autoridad\">tribunal</mark> <mark class=\"m-personalizado\">competente</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3101,1-ia-3104\">dirigirá la comunicación y la documentación pertinente al Ministerio de Justicia</mark>, que las <mark class=\"m-accion\">trasladará</mark> a la <mark class=\"m-autoridad\">Corte</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3103\">absteniéndose de proceder hasta la decisión de ésta</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Igualmente</mark> <mark class=\"m-accion\">se actuará</mark> para la <mark class=\"m-destacable\">extradición</mark> a un <mark class=\"m-autoridad\">Estado.</mark></span></span></p><p><b>5.</b> (…) 6. En caso de <mark class=\"m-destacable\">evasión</mark> del <mark class=\"m-personalizado\">condenado</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, el <mark class=\"m-autoridad\">Ministerio de Justicia</mark> <mark class=\"m-accion\">informará</mark> <mark class=\"m-plazo\">con urgencia</mark> al <mark class=\"m-autoridad\">Secretario de la Corte</mark> de tal <mark class=\"m-personalizado\">circunstancia</mark> y</span></span> <mark class=\"m-accion\">consultará</mark> con ella acerca de <mark class=\"m-resp r-ia\" data-q=\"1-ia-3105\">si España solicita su extradición al Estado en que se encuentre o si la Corte insta su entrega a dicho Estado</mark>.</p><p><b>7.</b> <u class=\"m-clave\">Cuando</u> la <mark class=\"m-personalizado\">petición</mark> de <mark class=\"m-destacable\">ejecución</mark> de la <mark class=\"m-autoridad\">Corte</mark> se <mark class=\"m-personalizado\">refiriese</mark> a una <mark class=\"m-destacable\">multa u orden de decomiso</mark>, el <mark class=\"m-autoridad\">Ministerio de Justicia</mark> <mark class=\"m-accion\">transmitirá</mark> la <mark class=\"m-personalizado\">documentación pertinente</mark> al <mark class=\"m-autoridad\">Fiscal General del Estado</mark> para que inste la <mark class=\"m-destacable\">ejecución</mark> ante el <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">judicial competente</mark> y, en su caso, se pongan a <mark class=\"m-personalizado\">disposición</mark> del <mark class=\"m-autoridad\">Ministerio de Justicia</mark> los bienes o sumas <mark class=\"m-personalizado\">obtenidas para su transferencia</mark> a la <mark class=\"m-autoridad\">Corte</mark> . <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3106\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 23 — De <mark class=\"m-personalizado\">las medidas</mark> de <mark class=\"m-destacable\">reparación</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3107,1-ia-3108,1-ia-4030\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 24 — De la intervención de España en calidad de «amicus curiae» <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\">Si España recibiere una <mark class=\"m-resp r-ia\" data-q=\"1-ia-4030\">invitación de la Corte</mark> <mark class=\"m-accion\">para participar</mark> <mark class=\"m-personalizado\">en un proceso en calidad de</mark> <mark class=\"m-destacable\">«amicus curiae»</mark>, <mark class=\"m-destacable\">el</mark> <mark class=\"m-resp\" data-q=\"1-128\">Ministerio de Justicia</mark> <mark class=\"m-accion\">consultará</mark> <mark class=\"m-destacable\">con el</mark> <mark class=\"m-autoridad\">Ministerio</mark> <mark class=\"m-destacable\">de Asuntos Exteriores</mark> para <mark class=\"m-resp r-ia\" data-q=\"1-ia-3109\">determinar la conveniencia u oportunidad de hacerlo</mark> y, en su <mark class=\"m-personalizado\">caso,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3109\">fijar los términos de dicha participación</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-250\">🎯 1 pregunta</mark></p>"],["Artículo 25 — De la celebración del juicio y otras actuaciones procesales en España · R6 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello ex-sello-r\">R6</span>","<p data-ex=\"EXOF\" data-r=\"R6\"><span class=\"ex-sello ex-sello-r\">R6</span> <u class=\"m-clave\">Si</u> la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">propusiere</mark> la <mark class=\"m-personalizado\">celebración</mark> del <mark class=\"m-destacable\">juicio u otras actuaciones procesales en España</mark>, el <mark class=\"m-resp\" data-q=\"1-170\">Ministerio de Justicia</mark>, <u class=\"m-clave\">previa</u> <mark class=\"m-personalizado\">consulta</mark> con los <mark class=\"m-autoridad\">Ministerios de Asuntos Exteriores y del Interior</mark> y <mark class=\"m-resp\" data-q=\"1-170\">otras autoridades competentes</mark>, <mark class=\"m-accion\">comunicará</mark> a la <mark class=\"m-autoridad\">Corte</mark> la <mark class=\"m-destacable\">decisión</mark> al <mark class=\"m-personalizado\">respecto</mark>. En su caso, los <mark class=\"m-destacable\">aspectos no jurisdiccionales</mark> de dichas <mark class=\"m-personalizado\">actuaciones</mark> <mark class=\"m-accion\">estarán</mark> <mark class=\"m-personalizado\">sometidos</mark> al <mark class=\"m-resp r-ia\" data-q=\"1-ia-3110,1-ia-3111\">acuerdo específico que se celebre con la Corte</mark>.</p>"],["Artículos 1 a 5 — Dignidad humana, vida, integridad, tortura y esclavitud <span class=\"ex-sello\">✱</span>","<p><b><mark class=\"m-destacable\">Art. 1.</mark></b> <mark class=\"m-personalizado\">La dignidad humana es</mark> <mark class=\"m-destacable\">inviolable.</mark> <mark class=\"m-accion\">Será</mark> <mark class=\"m-resp\" data-q=\"1-83,1-ia-3129\">respetada y protegida</mark>.</p><p><b><mark class=\"m-destacable\">Art. 2.</mark></b> <mark class=\"m-destacable\">1. Toda persona</mark> <mark class=\"m-personalizado\">tiene</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3443\">derecho a la vida</mark>. <mark class=\"m-personalizado\">2. Nadie</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3130,1-ia-3558,1-ia-3627\">condenado a la pena de muerte ni ejecutado</mark>.</p><p data-ex=\"*\"><b>Art. <mark class=\"m-destacable\">3.</mark></b> 1. <mark class=\"m-personalizado\">Toda persona tiene derecho a su integridad física y psíquica</mark>. 2. <mark class=\"m-personalizado\">En el marco de la</mark> <mark class=\"m-destacable\">medicina y la biología</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">respetarán</mark> en <mark class=\"m-personalizado\">particular</mark>: a) <mark class=\"m-personalizado\">el consentimiento</mark> <mark class=\"m-destacable\">libre e informado</mark> de la persona de que se trate, <span class=\"m-caja\">de acuerdo</span> con las <mark class=\"m-personalizado\">modalidades</mark> establecidas por la ley; b) <mark class=\"m-resp\" data-q=\"1-76,1-ia-3132\">la prohibición de las prácticas eugenésicas, en particular las que tienen como finalidad la selección de las personas</mark>; c) la <mark class=\"m-destacable\">prohibición</mark> de que <mark class=\"m-destacable\">el cuerpo humano o partes</mark> del mismo en cuanto tales <mark class=\"m-personalizado\">se conviertan</mark> en <mark class=\"m-destacable\">objeto de lucro</mark>; d) la <mark class=\"m-destacable\">prohibición</mark> de la <mark class=\"m-destacable\">clonación</mark> <mark class=\"m-personalizado\">reproductora</mark> de <mark class=\"m-destacable\">seres humanos</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3131\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b><mark class=\"m-destacable\">Art. 4.</mark></b> Nadie <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser sometido a tortura ni a penas o tratos</mark> <mark class=\"m-resp\" data-q=\"1-108,1-ia-3133,1-ia-3832\">inhumanos o degradantes</mark>.</p><p><b>Art. 5.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">1. <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser sometido a esclavitud o servidumbre</mark>. <mark class=\"m-personalizado\">2. Nadie</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser constreñido a realizar un trabajo forzado u obligatorio</mark>.</span></span> 3. <mark class=\"m-personalizado\">Se prohíbe la</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3134\">trata de seres humanos</mark>.</p>"],["Artículos 8, 9 y 10 — Datos personales, matrimonio y familia, pensamiento y objeción de conciencia <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 8.</b> 1. <mark class=\"m-autoridad\">Toda persona tiene</mark> <mark class=\"m-personalizado\">derecho a la protección de los datos</mark> de carácter personal que le conciernan. 2. Estos datos <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">tratarán</mark> <mark class=\"m-personalizado\">de modo leal</mark>, <mark class=\"m-personalizado\">para fines concretos y sobre la base del consentimiento de</mark> <mark class=\"m-destacable\">la persona</mark> <mark class=\"m-personalizado\">afectada o en virtud de otro fundamento legítimo previsto por la ley. Toda persona tiene derecho a <u class=\"m-clave\">acceder</u></mark> a los datos recogidos <mark class=\"m-personalizado\">que le conciernan y a obtener su rectificación</mark>. 3. <mark class=\"m-personalizado\">El respeto</mark> de estas normas <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">sujeto al control de</mark> <mark class=\"m-resp\" data-q=\"1-ia-3138,1-253\">una autoridad independiente</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3137\">🎯 1 pregunta</mark></p><p><b>Art. 9.</b> Se garantizan el <mark class=\"m-personalizado\">derecho a contraer matrimonio y el derecho a fundar una familia</mark> según <mark class=\"m-resp\" data-q=\"1-88,1-ia-3139\">las leyes nacionales que regulen su ejercicio</mark>.</p><p data-ex=\"EX\"><b>Art. 10.</b> 1. Toda <mark class=\"m-autoridad\">persona</mark> tiene derecho a la <mark class=\"m-personalizado\">libertad de pensamiento, de</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">conciencia</mark></span> y <span class=\"m-caja\"><mark class=\"m-personalizado\">de</mark></span> <mark class=\"m-personalizado\">religión.</mark> Este derecho implica <mark class=\"m-resp\" data-q=\"1-136\">la libertad de cambiar de religión o de convicciones, así como la libertad de manifestar su religión o sus convicciones individual o colectivamente, en público o en privado</mark>, a <mark class=\"m-personalizado\">través</mark> del <mark class=\"m-resp r-ia\" data-q=\"1-ia-3140\">culto, la enseñanza, las prácticas y la observancia de los ritos</mark>.</p><p><b>2.</b> Se reconoce el <mark class=\"m-personalizado\">derecho a la objeción de conciencia</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3141\">de acuerdo con las leyes nacionales que regulen su ejercicio</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 11 — <mark class=\"m-personalizado\"><u class=\"m-clave\">Libertad</u> de</mark> <mark class=\"m-personalizado\">expresión</mark> y <mark class=\"m-personalizado\">de información</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3142,1-ia-3143\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 12 a 15 — Partidos políticos, artes y ciencias, educación y trabajo <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 12.</b> 1. <mark class=\"m-autoridad\">Toda persona</mark> tiene derecho a <mark class=\"m-personalizado\">la</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">libertad de</mark></span> reunión pacífica y a la libertad de asociación en <mark class=\"m-personalizado\">todos los niveles,</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">especialmente en</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">los</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">ámbitos político, sindical</u></mark> y cívico, lo que supone el <mark class=\"m-personalizado\">derecho</mark> de toda persona <mark class=\"m-personalizado\">a</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3144,1-ia-3437\">fundar con otras sindicatos y a afiliarse a los mismos para la defensa de sus intereses</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-254\">🎯 1 pregunta</mark></p><p><b>2.</b> Los partidos políticos a <mark class=\"m-personalizado\">escala de la Unión</mark> <mark class=\"m-destacable\">contribuyen</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3145\">expresar la voluntad política de los ciudadanos de la Unión</mark>.</p><p><b>Art. 13.</b> Las artes y la <mark class=\"m-personalizado\">investigación científica son libres</mark>. <mark class=\"m-personalizado\">Se respeta la</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3146\">libertad de cátedra</mark>.</p><p data-ex=\"*\"><b>Art. 14.</b> 1. <mark class=\"m-autoridad\">Toda persona</mark> tiene <mark class=\"m-personalizado\">derecho a la educación y al <u class=\"m-clave\">acceso a</u> la formación <u class=\"m-clave\">profesional</u> y permanente</mark>. 2. Este derecho <span class=\"m-caja\">incluye</span> la facultad de <mark class=\"m-resp\" data-q=\"1-ia-3147,1-255\">recibir gratuitamente la enseñanza obligatoria</mark>. (…)</p><p data-ex=\"*\"><b>Art. 15.3.</b> <mark class=\"m-autoridad\">Los nacionales de terceros países</mark> que estén <mark class=\"m-personalizado\">autorizados a trabajar</mark> en el territorio de los <mark class=\"m-autoridad\">Estados</mark> miembros tienen <mark class=\"m-personalizado\">derecho a unas</mark> <mark class=\"m-resp\" data-q=\"1-ia-3149,1-256\">condiciones laborales equivalentes a aquellas de que disfrutan los ciudadanos de la Unión</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3428\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 15 — <u class=\"m-clave\">Libertad</u> <u class=\"m-clave\">profesional</u> y <mark class=\"m-personalizado\">derecho a</mark> trabajar: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4195\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 16 — <mark class=\"m-personalizado\"><u class=\"m-clave\">Libertad</u> de</mark> empresa: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3150,1-ia-4163\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 17, 18 y 19 — Propiedad, asilo y protección en caso de devolución, expulsión y extradición","<p><b>Art. 17.1.</b> <mark class=\"m-autoridad\">Toda persona</mark> tiene <mark class=\"m-personalizado\">derecho a disfrutar de la propiedad de los bienes</mark> <u class=\"m-clave\">que</u> haya <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">adquirido legalmente</mark> (…). <mark class=\"m-personalizado\"><u class=\"m-clave\">Nadie</u> puede</mark> ser <mark class=\"m-personalizado\"><u class=\"m-clave\">privado</u> de su propiedad</mark> más <mark class=\"m-personalizado\">que por causa de</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">utilidad</u> pública</mark>, en</span></span> los casos <mark class=\"m-personalizado\">y</mark> condiciones <mark class=\"m-personalizado\">previstos en la ley y a cambio,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3151,1-ia-3152\">en un tiempo razonable</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">de <mark class=\"m-personalizado\">una justa indemnización</mark> por su pérdida.</span></span>  (…) 2. <mark class=\"m-personalizado\">Se protege la propiedad intelectual</mark>.</p><p><b>Art. 18.</b> <mark class=\"m-personalizado\">Se garantiza el derecho de asilo</mark> dentro del <mark class=\"m-destacable\">respeto</mark> <mark class=\"m-personalizado\">de las normas de la</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3153\">Convención de Ginebra de 28 de julio de 1951 y del Protocolo de 31 de enero de 1967</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">sobre el <mark class=\"m-personalizado\">Estatuto de los Refugiados</mark> (…).</span></span></p><p><b>Art. 19.</b> 1. <mark class=\"m-personalizado\">Se <u class=\"m-clave\">prohíben</u> las</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3154\">expulsiones colectivas</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">2. <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser devuelto, expulsado o extraditado a un</mark> <mark class=\"m-autoridad\">Estado</mark> en el que corra un <mark class=\"m-personalizado\"><u class=\"m-clave\">grave riesgo de</u> ser sometido</mark> a la pena <mark class=\"m-personalizado\">de muerte</mark>, <mark class=\"m-personalizado\">a tortura o a otras</mark> penas o tratos <mark class=\"m-personalizado\">inhumanos o degradantes</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3155\">🎯 1 pregunta</mark></p>"],["Artículos 20, 23 y 24 — Igualdad ante la ley, igualdad entre mujeres y hombres y derechos del niño · R7 R8 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R7</span> <span class=\"ex-sello ex-sello-r\">R8</span> <span class=\"ex-sello ex-sello-r\">R9</span>","<p><b>Art. 20.</b> <mark class=\"m-resp\" data-q=\"1-173,1-ia-3201\">Todas las personas son iguales ante la ley</mark>.</p><p data-r=\"R7\"><span class=\"ex-sello ex-sello-r\">R7</span> <b>Art. 22.</b> La Unión respeta la diversidad <mark class=\"m-resp\" data-q=\"1-192\">cultural, religiosa y lingüística</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3204\">🎯 1 pregunta</mark></p><p data-ex=\"*\" data-r=\"R8\"><span class=\"ex-sello ex-sello-r\">R8</span> <b><mark class=\"m-personalizado\">Art.</mark> 23.</b> La igualdad entre mujeres y hombres <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">garantizarse en todos los ámbitos</mark>, <mark class=\"m-personalizado\">inclusive en</mark> materia <mark class=\"m-destacable\">de <mark class=\"m-resp\" data-q=\"1-193\">empleo, trabajo y retribución</mark></mark>. <mark class=\"m-destacable\">El principio</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">igualdad</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">no</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">impide</u> el mantenimiento o la adopción de medidas que supongan ventajas concretas en favor</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3205\">del sexo menos representado</mark>.</p><p data-ex=\"EXOF\" data-r=\"R9\"><span class=\"ex-sello ex-sello-r\">R9</span> <b>Art. 24.</b> 1. <mark class=\"m-autoridad\">Los niños</mark> tienen <mark class=\"m-personalizado\">derecho a la <u class=\"m-clave\">protección y</u> a los cuidados necesarios para su bienestar</mark>. <mark class=\"m-accion\">Podrán</mark> <mark class=\"m-personalizado\">expresar su <u class=\"m-clave\">opinión</u></mark> libremente. Ésta <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">tenida en cuenta</mark> para los <mark class=\"m-destacable\">asuntos que les afecten</mark>, en <mark class=\"m-personalizado\"><u class=\"m-clave\">función</u> de su</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">edad y</mark></span> madurez. 2. <span class=\"m-caja\">En</span> todos los actos relativos a los niños llevados a cabo por <mark class=\"m-autoridad\">autoridades</mark> públicas o instituciones <mark class=\"m-autoridad\">privadas</mark>, <mark class=\"m-autoridad\">el</mark> <mark class=\"m-personalizado\">interés superior del niño</mark> <mark class=\"m-accion\">constituirá</mark> <mark class=\"m-autoridad\">una</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3207\">consideración primordial</mark>. 3. <mark class=\"m-autoridad\">Todo niño</mark> tiene <mark class=\"m-personalizado\">derecho</mark> a mantener de forma periódica <mark class=\"m-personalizado\">relaciones personales y <u class=\"m-clave\">contactos</u> directos con su padre y con su madre, salvo</mark> si ello es <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"1-ia-3208\">contrario a sus intereses</mark></mark>. <mark class=\"m-resp ex-q\" data-q=\"1-102,1-ia-3206\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 21 — <u class=\"m-clave\">No</u> <mark class=\"m-destacable\">discriminación</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3202,1-ia-3203\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 25 — <mark class=\"m-personalizado\">Derechos</mark> de <mark class=\"m-personalizado\">las personas</mark> mayores: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3209\">🎯 1 pregunta más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 26 — Integración de <mark class=\"m-personalizado\">las personas</mark> discapacitadas: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3210\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 27 — Derecho a la información y consulta de los trabajadores en la empresa <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 27.</b> <mark class=\"m-accion\">Deberá</mark> <mark class=\"m-personalizado\">garantizarse a</mark> los <mark class=\"m-autoridad\">trabajadores o a sus representantes,</mark> en los <mark class=\"m-personalizado\">niveles adecuados, la información y consulta con suficiente antelación, en los casos y condiciones previstos</mark> en el <mark class=\"m-autoridad\">Derecho de</mark> la Unión y en las <mark class=\"m-autoridad\">legislaciones y prácticas nacionales.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-257,1-ia-3211\">🎯 2 preguntas</mark></p>"],["Artículo 28 — Derecho de negociación y de acción colectiva <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 28.</b> Los <mark class=\"m-personalizado\">trabajadores y los empresarios, o sus organizaciones respectivas,</mark> de conformidad con el <mark class=\"m-autoridad\">Derecho de la Unión</mark> y con las legislaciones y prácticas <mark class=\"m-autoridad\">nacionales,</mark> tienen <mark class=\"m-personalizado\">derecho a <u class=\"m-clave\">negociar</u> y celebrar <u class=\"m-clave\">convenios</u> colectivos,</mark> en los <mark class=\"m-destacable\">niveles adecuados, y</mark> <mark class=\"m-personalizado\">a emprender,</mark> <mark class=\"m-destacable\">en caso de conflicto de intereses,</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">acciones</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">colectivas</u> para la defensa de sus intereses, <u class=\"m-clave\">incluida</u></mark> <mark class=\"m-resp\" data-q=\"1-ia-3212,1-258\">la huelga</mark>.</p>"],["Artículos 29, 32, 34 y 37 — Colocación, trabajo infantil, ayuda social y medio ambiente · R10 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R10</span>","<p><b>Art. 29.</b> <mark class=\"m-autoridad\">Toda persona</mark> tiene <mark class=\"m-personalizado\">derecho a acceder a un</mark> <mark class=\"m-resp\" data-q=\"1-80,1-ia-3213\">servicio gratuito</mark> <mark class=\"m-personalizado\">de colocación</mark>.</p><p data-ex=\"*\" data-r=\"R10\"><span class=\"ex-sello ex-sello-r\">R10</span> <b>Art. 31.</b> 1. <mark class=\"m-autoridad\">Todo trabajador</mark> tiene <mark class=\"m-personalizado\">derecho a trabajar en condiciones que <u class=\"m-clave\">respeten</u> su</mark> <mark class=\"m-destacable\"><mark class=\"m-resp r-ia\" data-q=\"1-ia-3215\">salud, seguridad y dignidad</mark></mark>. 2. <span class=\"ex-plg\"><span class=\"ex-plg-t\">\u0007Todo trabajador tiene derecho</span></span> <mark class=\"m-personalizado\">a la limitación de la duración máxima del trabajo y a períodos de descanso diarios y semanales</mark>, así como a <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"1-ia-3216\">un <u class=\"m-clave\">período</u> de vacaciones anuales retribuidas</mark></mark>. <mark class=\"m-resp ex-q\" data-q=\"1-194\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 32.</b> <mark class=\"m-personalizado\">Se prohíbe el trabajo infantil</mark>. <mark class=\"m-personalizado\">La edad <u class=\"m-clave\">mínima</u></mark> de admisión al trabajo <mark class=\"m-accion\">no podrá</mark> <mark class=\"m-personalizado\">ser inferior</mark> <mark class=\"m-resp\" data-q=\"1-259,1-ia-3217\">a la edad en que concluye el período de escolaridad obligatoria</mark>, sin perjuicio <mark class=\"m-personalizado\"><u class=\"m-clave\">de</u></mark> disposiciones <mark class=\"m-personalizado\">más favorables para</mark> los jóvenes <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">salvo</mark></span> <mark class=\"m-personalizado\">excepciones limitadas</mark>. (…)</p><p><b>Art. 34.3.</b> Con el <mark class=\"m-personalizado\">fin de combatir la exclusión social y la pobreza</mark>, la Unión reconoce y respeta el derecho a <mark class=\"m-resp r-ia\" data-q=\"1-ia-3222\">una ayuda social y a una ayuda de vivienda</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">para garantizar una <mark class=\"m-personalizado\">existencia digna</mark> a todos aquellos que no dispongan de recursos suficientes (…).</span></span></p><p data-ex=\"*\"><b>Art. 37.</b> En las políticas de <mark class=\"m-personalizado\">la Unión se</mark> <mark class=\"m-accion\">integrarán</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">garantizarán</mark>, <mark class=\"m-personalizado\">conforme al principio de desarrollo sostenible</mark>, <mark class=\"m-resp\" data-q=\"1-77,1-ia-3225\">un nivel elevado de protección del medio ambiente y la mejora de su calidad</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 30</mark> — <mark class=\"m-personalizado\">Protección</mark> en <u class=\"m-clave\">caso</u> de <u class=\"m-clave\">despido</u> injustificado: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3214\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 33 — Vida familiar y vida profesional <span class=\"ex-sello\">✱</span>","<p><b>Art. 33.</b> 1. Se garantiza la <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">protección de la familia en los planos</mark> <mark class=\"m-destacable\">jurídico, económico</mark> y <mark class=\"m-personalizado\">social.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3219\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>2.</b> Con el <mark class=\"m-personalizado\">fin</mark> de poder <mark class=\"m-personalizado\">conciliar</mark> vida familiar y vida profesional, <mark class=\"m-autoridad\">toda persona</mark> tiene derecho <span class=\"m-caja\">a</span> ser <mark class=\"m-personalizado\">protegida</mark> contra cualquier <mark class=\"m-personalizado\"><u class=\"m-clave\">despido</u> por una causa relacionada con la maternidad,</mark> así como el derecho a un <mark class=\"m-personalizado\">permiso pagado por maternidad y a un permiso parental</mark> con motivo del <mark class=\"m-personalizado\">nacimiento o de la adopción de</mark> un niño. <mark class=\"m-resp ex-q\" data-q=\"1-260,1-ia-3220\">🎯 2 preguntas</mark></p>"],["Artículo 35 — Protección de la salud <span class=\"ex-sello\">EXOF</span>","<p data-ex=\"EXOF\"><b>Art. 35.</b> <mark class=\"m-autoridad\">Toda persona</mark> tiene derecho a acceder a <mark class=\"m-personalizado\">la prevención sanitaria y a</mark> beneficiarse de la <mark class=\"m-personalizado\">atención sanitaria</mark> en las condiciones establecidas por <mark class=\"m-personalizado\">las <u class=\"m-clave\"><mark class=\"m-resp\" data-q=\"1-137\">legislaciones y prácticas nacionales</mark>.</u></mark> Al definirse y ejecutarse todas las políticas y acciones de <mark class=\"m-personalizado\">la Unión se</mark> <mark class=\"m-accion\">garantizará</mark> <mark class=\"m-personalizado\">un <u class=\"m-clave\">nivel</u></mark> elevado <mark class=\"m-personalizado\">de protección de la salud humana.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3223\">🎯 1 pregunta</mark></p>"],["Artículo 40 — Derecho de sufragio activo y pasivo en las elecciones municipales <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>Art. 40.</b> <mark class=\"m-personalizado\">Todo ciudadano de <u class=\"m-clave\">la Unión</u> tiene derecho de sufragio activo y pasivo en las elecciones municipales</mark> del <mark class=\"m-autoridad\">Estado</mark> miembro <span class=\"m-circulo\"><mark class=\"m-personalizado\">en que resida,</mark></span> en las <mark class=\"m-personalizado\">mismas condiciones que los nacionales</mark> de dicho <mark class=\"m-autoridad\">Estado.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3229\">🎯 1 pregunta</mark></p>"],["Artículos 39, 41 y 42 — Sufragio, buena administración y acceso a los documentos <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX\"><b>Art. 39.</b> 1. Todo ciudadano de la <mark class=\"m-personalizado\">Unión</mark> tiene derecho de sufragio activo y pasivo en las elecciones al <mark class=\"m-autoridad\">Parlamento</mark> Europeo <mark class=\"m-personalizado\">en el</mark> <mark class=\"m-autoridad\">Estado</mark> miembro en <mark class=\"m-personalizado\">que resida</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, en las mismas condiciones que los nacionales de di- cho Estado</span></span>. 2. <mark class=\"m-personalizado\">Los <u class=\"m-clave\">diputados</u> al</mark> <mark class=\"m-autoridad\">Parlamento</mark> <mark class=\"m-personalizado\">Europeo</mark> <mark class=\"m-accion\">serán elegidos</mark> por <mark class=\"m-resp r-ia\" data-q=\"1-ia-3228\">sufragio universal libre, directo y secreto</mark>.</p><p data-ex=\"*\"><b>Art. 41.</b> 1. <mark class=\"m-autoridad\">Toda</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">persona</u></mark> <u class=\"m-clave\">tiene</u> <mark class=\"m-personalizado\"><u class=\"m-clave\">derecho a que</u></mark> las instituciones, <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">y</mark> organismos de la <mark class=\"m-personalizado\">Unión</mark> <mark class=\"m-personalizado\">traten sus asuntos</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">imparcial</u> y</mark> <mark class=\"m-personalizado\">equitativamente y dentro de un plazo razonable.</mark> <b>2.</b> Este derecho <mark class=\"m-personalizado\">incluye</mark> en particular: a) el derecho de <mark class=\"m-autoridad\">toda persona</mark> a <mark class=\"m-personalizado\">ser oída antes</mark> de que se <mark class=\"m-personalizado\">tome en contra suya una medida individual que la</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">afecte</u></mark> <mark class=\"m-personalizado\">desfavorablemente;</mark> b) <mark class=\"m-personalizado\">el derecho de toda</mark> <mark class=\"m-autoridad\">persona</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">acceder al</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">expediente</u></mark> <mark class=\"m-personalizado\">que</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">le concierna,</u></mark> dentro del respeto de <mark class=\"m-personalizado\">los intereses legítimos de la</mark> confidencialidad y del secreto profesional y comercial; c) <mark class=\"m-personalizado\">la</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">obligación</u></mark> que incumbe a la administración <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">motivar</mark> <mark class=\"m-personalizado\">sus decisiones.</mark> <b>3.</b> <mark class=\"m-autoridad\">Toda persona</mark> tiene <mark class=\"m-personalizado\">derecho a la</mark> <mark class=\"m-destacable\">reparación</mark> <mark class=\"m-personalizado\">por la Unión de los daños causados</mark> por sus instituciones <mark class=\"m-autoridad\">o sus</mark> agentes en el ejercicio de sus funciones, de conformidad con los <mark class=\"m-resp r-ia\" data-q=\"1-ia-3232\">principios generales comunes a los Derechos de los <mark class=\"m-autoridad\">Estados</mark> miembros</mark>. 4. Toda persona <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">dirigirse a las instituciones de la Unión en <u class=\"m-clave\">una</u> de las lenguas de los Tratados</mark> y <mark class=\"m-accion\">deberá recibir</mark> una <mark class=\"m-personalizado\">contestación</mark> <mark class=\"m-resp\" data-q=\"1-ia-3233,1-261\">en esa misma lengua</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3230,1-ia-3231\">🎯 2 preguntas</mark></p><p data-ex=\"EX\"><b>Art. 42.</b> Todo ciudadano de la Unión y toda persona física <mark class=\"m-destacable\">o</mark> <mark class=\"m-personalizado\">jurídica <u class=\"m-clave\">que resida</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o</u> tenga su domicilio social</mark> en un <mark class=\"m-autoridad\">Estado</mark> miembro tiene derecho a acceder a los <mark class=\"m-resp r-ia\" data-q=\"1-ia-3234\">documentos de las instituciones, órganos y organismos de la Unión, cualquiera que sea su soporte</mark>.</p>"],["Artículos 43, 44 y 46 — Defensor del Pueblo Europeo, petición y protección diplomática <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX\"><b>Art. 43.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Todo ciudadano de la Unión y toda persona física o jurídica que resida o tenga su domicilio</span></span> social en un <mark class=\"m-autoridad\">Estado</mark> miembro tiene derecho a someter al <mark class=\"m-autoridad\">Defensor</mark> del Pueblo Europeo <mark class=\"m-destacable\"><u class=\"m-clave\">los</u></mark> <mark class=\"m-resp\" data-q=\"1-138\">casos de mala administración en la actuación de las instituciones, órganos u organismos de la Unión</mark>, <mark class=\"m-resp\" data-q=\"1-138,1-ia-3235,1-ia-4177\">con exclusión del Tribunal de Justicia de la Unión Europea en el ejercicio de sus funciones jurisdiccionales</mark>.</p><p data-ex=\"*\"><b>Art. 44.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Estado miembro</span></span> tiene el derecho de <mark class=\"m-destacable\">petición</mark> ante el <mark class=\"m-resp\" data-q=\"1-ia-3123,1-ia-3236,1-262\">Parlamento Europeo</mark>.</p><p><b>Art. 46.</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Todo ciudadano de la Unión</u></mark> <mark class=\"m-accion\">podrá acogerse</mark>, en el territorio de un <mark class=\"m-personalizado\">tercer país</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3227,1-ia-3238,1-ia-4207\">en el que no esté representado el Estado miembro del que sea nacional</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">a la protección de las <mark class=\"m-autoridad\">autoridades</mark> diplomáticas y consulares de cualquier <mark class=\"m-autoridad\">Estado</mark> miembro, en las mismas <mark class=\"m-personalizado\">condiciones</mark> que los nacionales de este <mark class=\"m-autoridad\">Estado.</mark></span></span></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 45 — <mark class=\"m-personalizado\"><u class=\"m-clave\">Libertad</u> de</mark> circulación y de <mark class=\"m-personalizado\">residencia</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3237\">🎯 1 pregunta más de este artículo</mark>"],["Artículos 47, 48 y 50 — Tutela judicial, presunción de inocencia y «non bis in idem» <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 47.</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Toda persona</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">cuyos derechos y libertades garantizados por el Derecho de la Unión hayan sido violados</span></span> tiene <mark class=\"m-personalizado\">derecho <u class=\"m-clave\">a</u> la <u class=\"m-clave\">tutela judicial</u></mark> <mark class=\"m-destacable\">efectiva</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">respetando las condiciones establecidas en el presente artículo</span></span>. <mark class=\"m-personalizado\"><u class=\"m-clave\">Toda</u> persona</mark> tiene derecho a que su <mark class=\"m-personalizado\"><u class=\"m-clave\">causa sea oída equitativa</u> y públicamente y dentro de un plazo <u class=\"m-clave\">razonable</u> por un</mark> <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-personalizado\">independiente e <u class=\"m-clave\">imparcial</u></mark>, <mark class=\"m-personalizado\">establecido <mark class=\"m-resp\" data-q=\"1-263\">previamente</mark> por la ley.</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Toda persona podrá hacerse 000636 aconsejar, defender y representar.</span></span> <mark class=\"m-accion\">Se prestará</mark> <mark class=\"m-personalizado\">asistencia jurídica gratuita</mark> a quienes <mark class=\"m-destacable\">no</mark> dispongan de <mark class=\"m-personalizado\">recursos suficientes</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3240\">siempre y cuando dicha asistencia sea necesaria para garantizar la efectividad del acceso a la justicia</mark>.</p><p><b>Art. 48.</b> 1. <mark class=\"m-personalizado\">Todo <u class=\"m-clave\">acusado</u> se presume inocente</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3241,1-ia-3425\">mientras su culpabilidad no haya sido declarada legalmente</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">2. Se <mark class=\"m-personalizado\">garantiza a todo</mark> acusado el respeto de los <mark class=\"m-personalizado\">derechos de la defensa</mark>.</span></span></p><p><b>Art. <mark class=\"m-destacable\">50.</mark></b> <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">juzgado</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">o</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">condenado penalmente por una infracción respecto de</span></span> la cual ya haya <mark class=\"m-personalizado\">sido <u class=\"m-clave\">absuelto</u> o condenado</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3245\">en la Unión mediante sentencia penal firme conforme a la ley</mark>.</p>"],["Artículo 49 — Principios de legalidad y de proporcionalidad de los delitos y las penas <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 49.</b> 1. <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser <u class=\"m-clave\">condenado</u> por una <u class=\"m-clave\">acción o</u></mark> <mark class=\"m-destacable\"><u class=\"m-clave\">una</u></mark> <mark class=\"m-personalizado\">omisión</mark> que, en el momento en que haya sido <mark class=\"m-personalizado\">cometida,</mark> <mark class=\"m-destacable\">no</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">constituya</mark></span> <mark class=\"m-personalizado\">una infracción</mark> según el <mark class=\"m-personalizado\">Derecho interno o el Derecho internacional.</mark> Del mismo modo, <span class=\"m-circulo\"><mark class=\"m-destacable\">no</mark></span> <span class=\"m-circulo\"><mark class=\"m-accion\">podrá</mark></span> imponerse <mark class=\"m-personalizado\">una <u class=\"m-clave\">pena</u> más grave que la aplicable en el momento en que la</mark> infracción <mark class=\"m-personalizado\">haya sido <u class=\"m-clave\">cometida.</u> Si con posterioridad</mark> a esta infracción la ley dispone una <mark class=\"m-personalizado\">pena más leve,</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">aplicarse ésta.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-264,1-ia-3242\">🎯 2 preguntas</mark></p><p><b>3.</b> La <mark class=\"m-personalizado\">intensidad de las penas no</mark> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">ser <u class=\"m-clave\">desproporcionada</u> en relación con</mark> la infracción. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3244\">🎯 1 pregunta</mark></p>"],["Artículos 51 y 52 — Ámbito de aplicación y alcance de los derechos y principios <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 51.</b> 1. <span class=\"m-caja\">Las disposiciones de</span> la presente <mark class=\"m-personalizado\">Carta</mark> <mark class=\"m-accion\">están</mark> <mark class=\"m-personalizado\">dirigidas a las instituciones,</mark> <mark class=\"m-autoridad\">órganos y organismos</mark> de la Unión, dentro del respeto del principio de subsidiariedad, así como a los <mark class=\"m-autoridad\">Estados</mark> miembros <mark class=\"m-resp\" data-q=\"1-265,1-ia-3246\">únicamente cuando apliquen el Derecho de la Unión</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">Por consiguiente, éstos respetarán los derechos, observarán los principios y promoverán su aplicación, con arreglo a sus respectivas competencias y dentro de los límites de las competencias que los Tratados atribuyen a la Unión.</span></span></p><p data-ex=\"*\"><b>2.</b> La presente <mark class=\"m-personalizado\">Carta</mark> <mark class=\"m-resp\" data-q=\"1-85\">no amplía el ámbito de aplicación del Derecho de la Unión</mark> más allá de las competencias de la Unión, <mark class=\"m-resp\" data-q=\"1-85\">ni crea ninguna competencia o misión nuevas</mark> para la <mark class=\"m-personalizado\">Unión,</mark> <mark class=\"m-resp\" data-q=\"1-85,1-ia-3247\">ni modifica las competencias y misiones definidas en los Tratados</mark>.</p><p data-ex=\"*\"><b>Art. 52.</b> 1. <mark class=\"m-personalizado\">Cualquier limitación</mark> del ejercicio de los <mark class=\"m-personalizado\">derechos y libertades</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">reconocidos por la presente Carta</span></span> <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">ser establecida por</mark> la ley y <mark class=\"m-personalizado\">respetar el contenido <mark class=\"m-resp\" data-q=\"1-266\">esencial</mark></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de dichos derechos y libertades. Dentro del respeto del principio de proporcionalidad, sólo podrán introducirse limitaciones cuando sean necesa- rias y respondan efectivamente a objetivos de interés general reconocidos por la Unión o a la necesidad de protección de los derechos y libertades de los demás</span></span>.</p><p><b>3.</b> <mark class=\"m-personalizado\">En la medida</mark> en que la presente <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">Carta contenga derechos</mark> que correspondan a derechos garantizados por el <mark class=\"m-personalizado\">Convenio Europeo</mark> para la</span></span> Protección de los <mark class=\"m-personalizado\">Derechos Humanos</mark> (…), <mark class=\"m-resp r-ia\" data-q=\"1-ia-3249\">su sentido y alcance serán iguales a los que les confiere dicho Convenio</mark>. Esta disposición <mark class=\"m-resp r-ia\" data-q=\"1-ia-3249\">no obstará a que el Derecho de la Unión conceda una protección más extensa</mark>. <b>4.</b> <mark class=\"m-personalizado\">En la medida</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en que la presente <mark class=\"m-personalizado\">Carta reconozca derechos fundamentales resultantes de las tradiciones constitucionales</mark> comunes a los <mark class=\"m-autoridad\">Estados</mark></span></span> miembros, dichos derechos <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">interpretarán</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3250\">en <mark class=\"m-personalizado\">armonía</mark> con las citadas tradiciones</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3248,1-ia-3252\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>5.</b> <mark class=\"m-personalizado\">Las disposiciones</mark> de la presente <mark class=\"m-personalizado\">Carta que contengan principios</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">aplicarse mediante actos legislativos y ejecutivos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">adoptados por las instituciones, órganos y organismos de la Unión, y por actos de los Estados miembros cuando apliquen el Derecho de la Unión, en el ejercicio de sus competencias respectivas</span></span>. <mark class=\"m-resp\" data-q=\"1-ia-3251,1-267\">Sólo podrán alegarse ante un órgano jurisdiccional en lo que se refiere a la interpretación y control de la legalidad de dichos actos</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 53 — <u class=\"m-clave\">Nivel</u> <mark class=\"m-personalizado\">de protección</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3253,1-ia-4167\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 54 — <mark class=\"m-destacable\">Prohibición</mark> del abuso de <mark class=\"m-personalizado\">derecho</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3254,1-ia-4168\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 1 — Finalidad · R11 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello ex-sello-r\">R11</span>","<p>a) La <mark class=\"m-destacable\">finalidad</mark> del <mark class=\"m-autoridad\">Consejo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de Europa <mark class=\"m-destacable\">consiste</mark> en <mark class=\"m-personalizado\">realizar unión más estrecha entre sus miembros para salvaguardar y promover los <u class=\"m-clave\">ideales</u> y <u class=\"m-clave\">los</u> principios que constituyen su patrimonio común</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">favorecer su <u class=\"m-clave\">progreso económico</u></mark> y <span class=\"m-circulo\"><mark class=\"m-personalizado\">social</mark></span></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3261\">🎯 1 pregunta</mark></p><p>b) <mark class=\"m-destacable\"><u class=\"m-clave\">Esta finalidad se</u></mark> <mark class=\"m-accion\">perseguirá</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">a través de los</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">órganos</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\"><u class=\"m-clave\">del</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Consejo</u></mark>, <mark class=\"m-destacable\"><u class=\"m-clave\">mediante el</u></mark> <mark class=\"m-personalizado\">examen de los asuntos de interés común, la conclusión de acuerdos y la adopción de una acción conjunta</mark> en los campos económicos, social, cultural, científico, jurídico y administrativo, así como la <mark class=\"m-personalizado\">salvaguardia</mark> y la mayor efectividad de los derechos humanos y las libertades fundamentales.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3262\">🎯 1 pregunta</mark></p><p>c) <mark class=\"m-personalizado\">La participación de los Miembros</mark> en <u class=\"m-clave\">los</u> trabajos <span class=\"ex-plg\"><span class=\"ex-plg-t\">del <mark class=\"m-autoridad\">Consejo</mark> de Europa <mark class=\"m-personalizado\">no debe alterar su contribución</mark> a la obra de las <mark class=\"m-personalizado\">Naciones Unidas</mark> (…).</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3263\">🎯 1 pregunta</mark></p><p data-ex=\"EX\" data-r=\"R11\"><span class=\"ex-sello ex-sello-r\">R11</span> d) <mark class=\"m-personalizado\">Los asuntos relativos a la</mark> <mark class=\"m-destacable\">defensa nacional</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3264\">no son de competencia del Consejo de Europa</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-195\">🎯 1 pregunta</mark></p>"],["Artículos 3, 4, 5 y 6 — Principios, miembros y miembros asociados <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p><b>Art. 3.</b> <mark class=\"m-autoridad\">Cada uno de los Miembros del Consejo</mark> de <mark class=\"m-personalizado\">Europa reconoce el</mark> <mark class=\"m-destacable\">principio</mark> <mark class=\"m-resp\" data-q=\"1-113\">del imperio del Derecho</mark> y el <mark class=\"m-personalizado\"><u class=\"m-clave\">principio</u></mark> en virtud del cual <mark class=\"m-personalizado\">cualquier persona</mark> que <u class=\"m-clave\">se</u> halle bajo su jurisdicción <mark class=\"m-personalizado\">ha de <u class=\"m-clave\">gozar</u> de los <u class=\"m-clave\">derechos</u> humanos y de las libertades fundamentales</mark>, <mark class=\"m-personalizado\">y se compromete a <u class=\"m-clave\">colaborar</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">sincera</mark></span> y <mark class=\"m-personalizado\"><u class=\"m-clave\">activamente</u> en la consecución de la finalidad</mark> definida en el capítulo primero. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3266\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>Art. 4.</b> <mark class=\"m-autoridad\">Cualquier Estado europeo</mark>, considerado <mark class=\"m-personalizado\">capaz de cumplir</mark> las posiciones del <mark class=\"m-personalizado\">artículo 3, <u class=\"m-clave\">y</u> que tenga voluntad</mark> de hacerlo <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser invitado</mark> <mark class=\"m-autoridad\">por el Comité de Ministros</mark> <mark class=\"m-personalizado\">a convertirse en Miembro del</mark> <mark class=\"m-autoridad\">Consejo</mark> de Europa. El <mark class=\"m-autoridad\">Estado</mark> así <mark class=\"m-personalizado\">invitado</mark> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">la calidad de Miembro</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3268,1-ia-3302,1-ia-3347\">tan pronto como se remita en su nombre al Secretario General un instrumento de adhesión</mark> al presente <mark class=\"m-personalizado\">Estatuto</mark>.</p><p data-ex=\"*\"><b><mark class=\"m-plazo\">Art.</mark> 5.</b> a) <mark class=\"m-destacable\">En circunstancias especiales</mark>, <mark class=\"m-autoridad\">un país europeo</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, considerado capaz de cumplir las disposiciones del artículo 3, y que voluntad de hacerlo,</span></span> <mark class=\"m-accion\">podrá</mark> ser <mark class=\"m-personalizado\">invitado por</mark> el <mark class=\"m-autoridad\">Comité de Ministros</mark> a <span class=\"m-caja\"><mark class=\"m-destacable\">hacerse</mark></span> Miembro asociado <span class=\"ex-plg\"><span class=\"ex-plg-t\">del Consejo de Europa. Todo país invitado de esta manera tendrá la calidad de Miembro asociado desde el momento en que, en su nombre, le sea remitido al Secretario General un instrumento de adhesión al presente estatuto</span></span>. <mark class=\"m-destacable\">Los miembros <u class=\"m-clave\">asociados</u> únicamente</mark> <mark class=\"m-accion\">tendrán</mark> <mark class=\"m-destacable\">derecho a estar representados en la</mark> <mark class=\"m-resp\" data-q=\"1-ia-3269,1-ia-3357,1-ia-4197,1-268\">Asamblea Consultiva</mark>. b) <mark class=\"m-personalizado\">El término</mark> <mark class=\"m-autoridad\">«Miembro»</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">» empleado en el presente Estatuto</span></span> <mark class=\"m-personalizado\">se refiere también a</mark> los Miembros <mark class=\"m-personalizado\">asociados</mark>, <mark class=\"m-personalizado\">salvo</mark> cuando <mark class=\"m-personalizado\">se trate de la representación en el</mark> <mark class=\"m-autoridad\">Comité de Ministros</mark>.</p><p><b>Art. 6.</b> <mark class=\"m-personalizado\">Antes de dirigir la <u class=\"m-clave\">invitación</u></mark> (…), el <mark class=\"m-autoridad\">Comité de Ministros</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">determinará</mark> el número de representantes a que el futuro Miembro <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">derecho en</mark> <mark class=\"m-autoridad\">la Asamblea Consultiva y su</mark> <mark class=\"m-personalizado\">parte proporcional de contribución financiera</mark></span></span> . <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3301\">🎯 1 pregunta</mark></p>"],["Artículos 7, 8 y 9 — Retirada y suspensión · R12 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R12</span>","<p data-ex=\"EXOF\" data-r=\"R12\"><span class=\"ex-sello ex-sello-r\">R12</span> <b>Art. 7.</b> <mark class=\"m-autoridad\">Cualquier Miembro del Consejo de Europa</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">retirarse</mark> <mark class=\"m-autoridad\">del mismo notificando su decisión al Secretario General.</mark> La notificación <mark class=\"m-accion\">surtirá</mark> <mark class=\"m-personalizado\">efecto</mark> <mark class=\"m-resp\" data-q=\"1-126,1-ia-3303\">al concluir el año financiero en curso, si tuvo lugar en los primeros nueve meses de este año, y al finalizar el año financiero siguiente, si se realizó en los tres últimos meses</mark>.</p><p data-ex=\"*\"><b>Art. 8.</b> <mark class=\"m-autoridad\">El Comité de Ministros del Consejo</mark> de Europa <mark class=\"m-accion\">podrá</mark> <mark class=\"m-resp\" data-q=\"1-269\">dejar en suspenso el derecho de representación</mark> <mark class=\"m-personalizado\">del</mark> <mark class=\"m-autoridad\">Miembro del Consejo</mark> de Europa <mark class=\"m-personalizado\">que <u class=\"m-clave\">infrinja gravemente</u></mark> lo dispuesto en el <mark class=\"m-personalizado\">artículo 3</mark> (imperio del Derecho y derechos humanos), <mark class=\"m-resp\" data-q=\"1-269,1-ia-3304\">e invitarle a retirarse</mark> <mark class=\"m-personalizado\">en las</mark> <mark class=\"m-destacable\">condiciones previstas en el</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">artículo 7. Si no</mark></span> <mark class=\"m-destacable\">atiende</mark> a dicha invitación, el <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">puede</u> decidir</mark> que el Miembro de que se trata <mark class=\"m-personalizado\">ha cesado de pertenecer</mark> al <mark class=\"m-autoridad\">Consejo</mark> a <mark class=\"m-personalizado\">partir de una fecha que</mark> <mark class=\"m-accion\">determinará</mark> <mark class=\"m-personalizado\">el</mark> propio <mark class=\"m-autoridad\">Comité.</mark></p><p data-ex=\"*\"><b>Art. 9.</b> <mark class=\"m-autoridad\">Cuando un Miembro</mark> no <mark class=\"m-personalizado\"><u class=\"m-clave\">cumpla</u> sus</mark> <mark class=\"m-destacable\">obligaciones financieras,</mark> <mark class=\"m-autoridad\">el Comité de Ministros</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-resp\" data-q=\"1-ia-3270,1-ia-3305,1-270\">suspender su derecho de representación en el Comité y en la Asamblea Consultiva durante el tiempo en que deje de satisfacer dichas obligaciones</mark>.</p>"],["Artículos 13, 14 y 15 — Naturaleza y composición del Comité · R13 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R13</span>","<p data-ex=\"EXOF\" data-r=\"R13\"><span class=\"ex-sello ex-sello-r\">R13</span> <b>Art. 14.</b> <mark class=\"m-personalizado\">Cada Miembro</mark> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-destacable\">un representante</mark> <mark class=\"m-personalizado\">en el</mark> <mark class=\"m-autoridad\">Comité de Ministros</mark> y cada representante <mark class=\"m-personalizado\">tiene</mark> un <mark class=\"m-destacable\">voto</mark>. Los representantes en el <mark class=\"m-autoridad\">Comité</mark> son <mark class=\"m-resp\" data-q=\"1-103\">los Ministros de Asuntos Exteriores</mark><span class=\"ex-plg\"><span class=\"ex-plg-t\">. Cuando un Ministro de Asuntos Exteriores no pueda asistir a las sesiones, o cuando otras</span></span> circunstancias lo aconsejen, <mark class=\"m-accion\">podrá designarse</mark> un suplente que actúe en su lugar; éste <mark class=\"m-accion\">será,</mark> en la medida de lo posible, un miembro <mark class=\"m-autoridad\">del Gobierno de su país</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-140,1-ia-3311\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 15.</b> a) <mark class=\"m-autoridad\">El Comité de Ministros</mark> <mark class=\"m-accion\">examinará</mark>, <mark class=\"m-destacable\"><u class=\"m-clave\">por recomendación de la</u></mark> <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"1-271\">Asamblea Consultiva</mark></mark> <mark class=\"m-destacable\">o <u class=\"m-clave\">por iniciativa propia,</u></mark> <mark class=\"m-personalizado\">las</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">medidas</mark></span> <mark class=\"m-personalizado\">adecuadas</mark> para realizar la finalidad <mark class=\"m-personalizado\">del</mark> <mark class=\"m-autoridad\">Consejo</mark> de Europa, <mark class=\"m-personalizado\">incluida</mark> la conclusión de <mark class=\"m-personalizado\"><u class=\"m-clave\">convenios y de</u></mark> <mark class=\"m-personalizado\">acuerdos</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">la adopción</mark> por los Gobiernos de <mark class=\"m-personalizado\">una política</mark> común respecto a determinados asuntos. <mark class=\"m-personalizado\">Sus</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">conclusiones</u></mark> <mark class=\"m-accion\">serán comunicadas</mark> <mark class=\"m-personalizado\">a los Miembros</mark> por <mark class=\"m-destacable\">el</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Secretario</u></mark> <mark class=\"m-destacable\">General</mark>. b) <mark class=\"m-destacable\">Las <u class=\"m-clave\">conclusiones</u> del</mark> <mark class=\"m-autoridad\">Comité de Ministros</mark> <mark class=\"m-accion\">podrán</mark>, si hubiere lugar a ello, <mark class=\"m-personalizado\">revestir la forma de recomendaciones</mark> a los Gobiernos. <mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">invitar</mark> a éstos a poner en su <mark class=\"m-personalizado\">conocimiento</mark> las <mark class=\"m-personalizado\">medidas</mark> que <mark class=\"m-personalizado\">han tomado</mark> respecto a <mark class=\"m-personalizado\">dichas recomendaciones.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3313\">🎯 1 pregunta</mark></p>"],["Artículos 16, 17 y 18 — Organización interior y Reglamento interno del Comité <span class=\"ex-sello\">EXOF</span>","<p><b>Art. 16.</b> Sin perjuicio de los <span class=\"ex-plg\"><span class=\"ex-plg-t\">poderes de la <mark class=\"m-autoridad\">Asamblea Consultiva</mark> (…), el <mark class=\"m-autoridad\">Comité de Ministros</mark> <mark class=\"m-accion\">resolverá,</mark> con carácter obligatorio, cualquier cuestión relativa a la organización y el régimen interior del <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-personalizado\">de Europa. Con este</mark> fin <mark class=\"m-accion\">adoptará</mark> los <mark class=\"m-destacable\">reglamentos financieros y administrativos</mark> necesarios.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3314\">🎯 1 pregunta</mark></p><p><b>Art. 17.</b> <mark class=\"m-autoridad\">El Comité de Ministros</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">constituir</mark> <mark class=\"m-destacable\">Comités o Comisiones</mark> <mark class=\"m-personalizado\">de carácter</mark> <mark class=\"m-destacable\">consultivo o técnico</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3315\">para todas las finalidades específicas que juzgue convenientes</mark>.</p><p data-ex=\"EXOF\"><b>Art. 18.</b> El <mark class=\"m-autoridad\">Comité de Ministros</mark> <mark class=\"m-accion\">adoptará</mark> <mark class=\"m-destacable\">su Reglamento interno</mark>, <mark class=\"m-personalizado\">que</mark> <mark class=\"m-accion\">determinará</mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">especialmente</mark></span>: i) <mark class=\"m-resp\" data-q=\"1-109,1-ia-4198\">El quórum</mark>; ii) La <mark class=\"m-personalizado\">forma de <u class=\"m-clave\">designación</u> del</mark> <mark class=\"m-autoridad\">Presidente</mark> <mark class=\"m-destacable\">y</mark> la <mark class=\"m-personalizado\">duración de sus funciones</mark>; iii) El <mark class=\"m-personalizado\">procedimiento que</mark> ha de seguirse para <mark class=\"m-personalizado\">incluir temas en el orden del día,</mark> así como para presentar <mark class=\"m-personalizado\">propuestas de resoluciones</mark>; iv) <mark class=\"m-personalizado\">Las condiciones en que <u class=\"m-clave\">se</u></mark> <mark class=\"m-accion\">notificará</mark> <mark class=\"m-personalizado\">la designación de los</mark> <mark class=\"m-destacable\">suplentes</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, afectados con arreglo al artículo 14</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3316\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 19 — <u class=\"m-clave\">Informes</u> del <mark class=\"m-autoridad\">Comité de Ministros</mark> a <mark class=\"m-autoridad\">la Asamblea</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3317,1-ia-4170\">🎯 2 preguntas más de este artículo</mark></div><div class=\"vis\"><div class=\"vis-t\"><i>🌳</i>Mayorías del Comité de Ministros (art. 20)</div><div class=\"vis-arbol\"><div class=\"vis-raiz\">Mayorías</div><div class=\"vis-ramas\"><div class=\"vis-rama\">a) <b>Unanimidad</b> de los votos emitidos y <mark class=\"m-destacable\">mayoría</mark> de los representantes: <mark class=\"m-personalizado\">cuestiones importantes</mark><div class=\"vis-sub\"><span><mark class=\"m-personalizado\">recomendaciones</mark> (15 b)</span><span><u class=\"m-clave\">informes</u> a <mark class=\"m-autoridad\">la Asamblea</mark> (19)</span><span><mark class=\"m-destacable\">reuniones</mark> y publicidad (21 a y b)</span><span><mark class=\"m-destacable\">sede de</mark> <mark class=\"m-autoridad\">la Asamblea</mark> (33)</span><span><mark class=\"m-destacable\">enmiendas</mark> a los arts. 1 d), 7, 15, 20 y 22</span></div></div><div class=\"vis-rama\">b) <mark class=\"m-resp r-ia\" data-q=\"1-ia-3319,1-ia-3321\">Mayoría simple</mark> de los representantes con <mark class=\"m-personalizado\">derecho a</mark> formar <mark class=\"m-personalizado\">parte del</mark> <mark class=\"m-autoridad\">Comité</mark>: <u class=\"m-clave\">reglamento</u> <mark class=\"m-personalizado\">interno</mark> y regímenes financiero y administrativo</div><div class=\"vis-rama\">c) <mark class=\"m-resp r-ia\" data-q=\"1-ia-3318,1-ia-3320,1-ia-3324\">Mayoría de los dos tercios de los representantes con derecho a participar</mark>: <u class=\"m-clave\">invitar</u> <mark class=\"m-personalizado\">Miembros</mark> y <mark class=\"m-personalizado\">Miembros</mark> <mark class=\"m-personalizado\">asociados</mark> (arts. 4 y 5)</div><div class=\"vis-rama\">d) Todas las demás: <u class=\"m-clave\">dos</u> tercios de los votos emitidos y <mark class=\"m-destacable\">mayoría</mark> de los representantes (<mark class=\"m-personalizado\">incluso</mark> el presupuesto)</div></div></div></div><div class=\"vis\"><div class=\"vis-t\"><i>⇄</i>Reuniones del Comité (art. 21)</div><div class=\"vis-comp\" style=\"--n:2\"><div class=\"vis-col\"><h5>Regla general</h5><ul><li><mark class=\"m-resp r-ia\" data-q=\"1-ia-3322\">A puerta cerrada</mark></li><li><mark class=\"m-resp r-ia\" data-q=\"1-ia-3322\">En la sede del Consejo</mark></li><li><mark class=\"m-personalizado\">Salvo</mark> <mark class=\"m-personalizado\">acuerdo</mark> en <u class=\"m-clave\">contrario</u> del <mark class=\"m-autoridad\">Comité</mark></li></ul></div><div class=\"vis-col\"><h5>Obligatoriamente</h5><ul><li><mark class=\"m-plazo\">Antes de</mark> la apertura y al comienzo de las <mark class=\"m-destacable\">reuniones</mark> de <mark class=\"m-autoridad\">la Asamblea</mark></li><li><mark class=\"m-plazo\">Además</mark>, <mark class=\"m-plazo\">cuantas veces lo estime conveniente</mark></li><li>Publicidad de <mark class=\"m-destacable\">las deliberaciones</mark>: lo decide <mark class=\"m-autoridad\">el Comité</mark> (por unanimidad y <mark class=\"m-destacable\">mayoría</mark> de representantes)</li></ul></div></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 21 — <mark class=\"m-destacable\">Reuniones</mark> del <mark class=\"m-autoridad\">Comité de Ministros</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3323\">🎯 1 pregunta más de este artículo</mark>"],["Artículos 22 y 25 — Asamblea Consultiva: naturaleza y representantes · R14 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R14</span>","<p data-r=\"R14\"><span class=\"ex-sello ex-sello-r\">R14</span> <b>Art. 22.</b> <mark class=\"m-autoridad\">La Asamblea Consultiva</mark> <mark class=\"m-personalizado\">es el</mark> <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-destacable\">deliberante</mark> <mark class=\"m-personalizado\">del</mark> <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-personalizado\">de Europa.</mark> <mark class=\"m-accion\">Deliberará</mark> <mark class=\"m-personalizado\">acerca de los</mark> asuntos que sean de su <mark class=\"m-personalizado\">competencia</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, tal como ésta queda definida en el presente Estatuto,</span></span> y <mark class=\"m-accion\">transmitirá</mark> sus conclusiones al <mark class=\"m-autoridad\">Comité de Ministros</mark> bajo la forma de <mark class=\"m-resp\" data-q=\"1-98,1-ia-3325\">recomendaciones</mark>.</p><p data-ex=\"*\"><b>Art. 25.</b> a) <mark class=\"m-autoridad\">La Asamblea Consultiva</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-destacable\">constituida</mark> <mark class=\"m-personalizado\">por</mark> <mark class=\"m-destacable\">representantes de cada Miembro,</mark> <mark class=\"m-personalizado\">elegidos por</mark> su <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"1-272\">Parlamento</mark></mark> <mark class=\"m-personalizado\">de entre los miembros de éste o designados,</mark> por nombramiento de entre los mismos con arreglo a un <mark class=\"m-personalizado\">procedimiento fijado por dicho</mark> <mark class=\"m-autoridad\">Parlamento,</mark> <mark class=\"m-personalizado\">sin perjuicio,</mark> no obstante, del derecho del <mark class=\"m-autoridad\">Gobierno</mark> de cualquier Miembro <mark class=\"m-personalizado\">a efectuar aquellos nombramientos complementarios</mark> que fueren necesarios cuando el <mark class=\"m-autoridad\">Parlamento</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">no estuviere reunido ni hubiere establecido procedimiento alguno a qué atenerse en dicho caso.</span></span></p><p><mark class=\"m-personalizado\">Cada uno</mark> de los representantes <mark class=\"m-resp r-ia\" data-q=\"1-ia-3330\">tendrá la nacionalidad del Miembro que represente y no podrá ser a la vez miembro del Comité de Ministros</mark>.</p><p>El mandato de los representantes así <span class=\"ex-plg\"><span class=\"ex-plg-t\">designados empieza con la <mark class=\"m-plazo\">apertura de la reunión ordinaria</mark> que sigue a su designación y</span></span> expira con la apertura de <mark class=\"m-resp r-ia\" data-q=\"1-ia-3331,1-ia-3335\">la reunión ordinaria siguiente o de una reunión ordinaria ulterior</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">quedando a salvo el derecho de los Miembros de proceder a nuevas designaciones después de celebrar elecciones para su <mark class=\"m-autoridad\">Parlamento.</mark></span></span></p><p data-ex=\"EX\"><b>c)</b> <mark class=\"m-personalizado\">Cada representante</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">tener</mark> <mark class=\"m-destacable\">un suplente,</mark> <mark class=\"m-personalizado\">que</mark> en su ausencia <mark class=\"m-accion\">podrá</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3333\">ocupar su puesto, tomar la palabra y votar en su lugar</mark>. Lo dispuesto en el anterior apartado a) <mark class=\"m-accion\">se aplicará</mark> asimismo a la designación <mark class=\"m-personalizado\">de suplentes.</mark></p>"],["Artículo 23 — Competencias de la Asamblea Consultiva <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 23.</b> <b>a)</b> <mark class=\"m-autoridad\">La Asamblea Consultiva</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">deliberar y formular recomendaciones acerca de cualquier cuestión</mark> que responda a la <mark class=\"m-personalizado\">finalidad <u class=\"m-clave\">y</u></mark> sea de la <mark class=\"m-personalizado\">competencia del</mark> <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-personalizado\">de Europa,</mark> tal como éstas quedan definidas en el capítulo primero; <mark class=\"m-accion\">deliberará</mark> <mark class=\"m-personalizado\">y</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">formular recomendaciones</mark> acerca de cualquier cuestión <mark class=\"m-autoridad\">que</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">le someta</u></mark> para dictamen el <mark class=\"m-autoridad\"><mark class=\"m-resp\" data-q=\"1-273\">Comité de Ministros</mark>.</mark> <b>b)</b> <mark class=\"m-autoridad\">La Asamblea</mark> <mark class=\"m-accion\">fijará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">su programa</u></mark> conforme a lo dispuesto en el precedente <mark class=\"m-personalizado\">apartado a), teniendo en cuenta las actividades de las</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">otras organizaciones</u></mark> <mark class=\"m-personalizado\">intergubernamentales</mark> europeas de las cuales <mark class=\"m-personalizado\">formen parte</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">todos o algunos</u></mark> <mark class=\"m-personalizado\">de los Miembros del</mark> <mark class=\"m-autoridad\">Consejo.</mark> <b>c)</b> <mark class=\"m-autoridad\">El <mark class=\"m-resp r-ia\" data-q=\"1-ia-3328\">Presidente de la Asamblea</mark></mark> <mark class=\"m-accion\">decidirá,</mark> en caso de duda, <mark class=\"m-personalizado\">si una cuestión</mark> suscitada en el curso de una <mark class=\"m-personalizado\">reunión se considera o no incluida en el programa</mark> de la <mark class=\"m-autoridad\">Asamblea.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3326,1-ia-3327\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 24 — Comités y Comisiones de <mark class=\"m-autoridad\">la Asamblea Consultiva</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3329,1-ia-4171\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 26 y 28 — Número de representantes y Presidente de la Asamblea <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 28.</b> a) <mark class=\"m-autoridad\">La Asamblea Consultiva</mark> <mark class=\"m-accion\">adoptará</mark> su <mark class=\"m-destacable\">Reglamento interno</mark>, y <mark class=\"m-accion\">elegirá</mark> <mark class=\"m-personalizado\">entre sus miembros a su</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Presidente</u></mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">el cual</u></mark> <mark class=\"m-accion\">permanecerá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">en el ejercicio de sus funciones hasta la siguiente reunión ordinaria.</u></mark> b) <mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Presidente</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3336\">dirigirá las deliberaciones, pero no participará en los debates ni en la votación</mark>. <mark class=\"m-destacable\">El suplente del</mark> <mark class=\"m-autoridad\">Presidente</mark> <mark class=\"m-accion\">podrá asistir</mark> a las <mark class=\"m-personalizado\"><u class=\"m-clave\">sesiones</u></mark>, <mark class=\"m-personalizado\"><u class=\"m-clave\">hacer uso de la palabra y votar</u> en su lugar.</mark> c) El <mark class=\"m-destacable\">Reglamento interno</mark> <mark class=\"m-accion\">establecerá</mark> <mark class=\"m-personalizado\">«inter alia»</mark> <mark class=\"m-destacable\">(entre otras cosas):</mark> i) <mark class=\"m-personalizado\">el quórum</mark>; (…) <mark class=\"m-resp ex-q\" data-q=\"1-274\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 27 — <u class=\"m-clave\">Representación</u> del <mark class=\"m-autoridad\">Comité de Ministros</mark> en <mark class=\"m-autoridad\">la Asamblea</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3334,1-ia-4172\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 29 a 35 — Votaciones, sesiones y publicidad de la Asamblea · R15 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R15</span>","<p data-ex=\"*\"><b>Art. 29.</b> Sin <mark class=\"m-personalizado\">perjuicio</mark> de lo dispuesto en el <mark class=\"m-personalizado\">artículo 30</mark> (cuestiones de procedimiento), <mark class=\"m-destacable\">todas las resoluciones</mark> de <mark class=\"m-autoridad\">la Asamblea Consultiva</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">tomarán</mark> <mark class=\"m-personalizado\">por</mark> <mark class=\"m-resp\" data-q=\"1-ia-3337,1-275\">mayoría de los dos tercios de los votos emitidos</mark>, incluso las que tengan por objeto: i) <mark class=\"m-personalizado\">hacer recomendaciones al</mark> <mark class=\"m-autoridad\">Comité de Ministros</mark>; ii) <mark class=\"m-personalizado\">proponer al</mark> <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-personalizado\">los asuntos que han de ser inscritos en el programa de la</mark> <mark class=\"m-autoridad\">Asamblea</mark>; iii) <mark class=\"m-personalizado\">crear Comités o Comisiones</mark>; iv) <mark class=\"m-personalizado\">fijar la fecha de la apertura de las sesiones</mark>; <mark class=\"m-personalizado\">y</mark> v) <mark class=\"m-personalizado\">determinar la mayoría requerida</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><span class=\"hueco-txt\">para las resoluciones en casos no previstos en los anteriores apar- tados i) a iv), o fijar, en caso de duda, la mayoría requerida</span></span></span>.</p><p><b>Art. 30.</b> <mark class=\"m-personalizado\">Las resoluciones de</mark> la <mark class=\"m-autoridad\">Asamblea Consultiva</mark> sobre las <mark class=\"m-personalizado\">cuestiones de procedimiento</mark>, y en particular la <mark class=\"m-personalizado\"><u class=\"m-clave\">elección</u> de los miembros de la Mesa</mark>, (…) <mark class=\"m-accion\">se adoptarán</mark> <mark class=\"m-personalizado\">por</mark> la <mark class=\"m-destacable\">mayoría</mark> <mark class=\"m-personalizado\">que</mark> la <mark class=\"m-autoridad\">Asamblea</mark> <mark class=\"m-personalizado\">determine</mark> de acuerdo con el artículo 29 (v).  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3338\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 32.</b> <mark class=\"m-autoridad\">La Asamblea Consultiva</mark> <mark class=\"m-accion\">celebrará</mark> <mark class=\"m-plazo\">cada</mark> <mark class=\"m-autoridad\">año</mark> <mark class=\"m-plazo\">una sesión</mark> ordinaria <span class=\"ex-plg\"><span class=\"ex-plg-t\">, cuya fecha y cuya duración determinará la Asamblea de manera que se evite, en cuanto sea posible, cualquier coincidencia con las sesiones parla- mentarias y con las de la Asamblea General de las Naciones Unidas</span></span>. La duración de las <mark class=\"m-autoridad\">reuniones ordinarias</mark> <mark class=\"m-resp\" data-q=\"1-276,1-ia-3340\">no excederá de un mes</mark>, a no ser que la <mark class=\"m-autoridad\">Asamblea y el Comité de Ministros</mark> <mark class=\"m-personalizado\">resuelvan en contrario de común acuerdo.</mark></p><p data-ex=\"EX\" data-r=\"R15\"><span class=\"ex-sello ex-sello-r\">R15</span> <b>Art. 33.</b> <mark class=\"m-destacable\">Las sesiones ordinarias</mark> de la <mark class=\"m-autoridad\">Asamblea</mark> Consultiva <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">celebrarán</mark> <mark class=\"m-personalizado\">en la sede del</mark> <mark class=\"m-autoridad\">Consejo,</mark> <mark class=\"m-personalizado\">salvo decisión</mark> en contrario adoptada de común acuerdo por la <mark class=\"m-autoridad\">Asamblea</mark> y el <mark class=\"m-autoridad\">Comité de Ministros.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-196,1-ia-3341\">🎯 2 preguntas</mark></p><p data-ex=\"EX\"><b>Art. 34.</b> <mark class=\"m-autoridad\">La Asamblea Consultiva</mark> <mark class=\"m-accion\">podrá convocarse</mark> para una <mark class=\"m-personalizado\">sesión extraordinaria por iniciativa del</mark> <mark class=\"m-autoridad\">Comité de Ministros</mark> o del <mark class=\"m-autoridad\">Presidente de la Asamblea,</mark> <mark class=\"m-personalizado\">previo acuerdo entre ellos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, que se extenderá asimismo a la fecha y lugar de la sesión.7</span></span>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3342\">🎯 1 pregunta</mark></p><p><b>Art. <mark class=\"m-personalizado\">35.</mark></b> <mark class=\"m-destacable\">Las deliberaciones</mark> de la <mark class=\"m-autoridad\">Asamblea Consultiva</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3343,1-ia-4199\">públicas, a menos que ella misma acuerde lo contrario</mark>.</p>"],["Artículos 36 y 37 — La Secretaría <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 36.</b> a) <mark class=\"m-autoridad\">La Secretaría</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">compuesta</u></mark> por: <mark class=\"m-personalizado\">un</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Secretario</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">General,</u> un</mark> <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">General Adjunto</u> y el personal necesario.</mark> b) <mark class=\"m-personalizado\">El</mark> <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-personalizado\">General y el</mark> <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-personalizado\">General Adjunto</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3260,1-ia-3345\">nombrados por la Asamblea Consultiva por recomendación del Comité de Ministros</mark>. c) Los <mark class=\"m-personalizado\">restantes miembros de la</mark> <mark class=\"m-autoridad\">Secretaría</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-destacable\">nombrados</mark> por <mark class=\"m-autoridad\">el Secretario General</mark> <mark class=\"m-personalizado\">con arreglo al Reglamento administrativo</mark>. <mark class=\"m-personalizado\">d)</mark> Ningún <mark class=\"m-personalizado\">miembro de la</mark> <mark class=\"m-autoridad\">Secretaría</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">desempeñar un cargo remunerado por un</mark> <mark class=\"m-autoridad\">Gobierno</mark>, <mark class=\"m-personalizado\">ser miembro de la</mark> <mark class=\"m-autoridad\">Asamblea</mark> <mark class=\"m-personalizado\">Consultiva o</mark> de un <mark class=\"m-autoridad\">Parlamento</mark> <mark class=\"m-personalizado\">nacional</mark> <mark class=\"m-personalizado\">o</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3348\">desempeñar ocupaciones <mark class=\"m-personalizado\">incompatibles</mark> con sus deberes</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-277,1-ia-3346\">🎯 2 preguntas</mark></p>"],["Artículo 36 — La Secretaría (nota: el Secretario General responde ante el Comité de Ministros) <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\">RECUERDA: El <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-personalizado\">General responde ante el</mark> <mark class=\"m-autoridad\">Comité de Ministros,</mark> <mark class=\"m-personalizado\">pero es nombrado por la</mark> <mark class=\"m-autoridad\">Asamblea</mark> <mark class=\"m-personalizado\">Consultiva por recomendación del</mark> <mark class=\"m-autoridad\">Comité de Ministros.</mark></p>"],["Artículos 38 y 39 — Financiación <span class=\"ex-sello\">✱</span>","<p><b>Art. 38.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">a) Cada miembro <mark class=\"m-accion\">sufragará</mark> <mark class=\"m-personalizado\">los gastos de su propia representación</mark> en el <mark class=\"m-autoridad\">Comité de Ministros</mark> y en la <mark class=\"m-autoridad\">Asamblea</mark> Consultiva.</span></span> b) <mark class=\"m-personalizado\">Los <u class=\"m-clave\">gastos</u> de la</mark> <mark class=\"m-autoridad\">Secretaría</mark> <mark class=\"m-personalizado\">y</mark> cualesquiera otros gastos comunes <mark class=\"m-accion\">se repartirán</mark> entre los miembros <mark class=\"m-resp r-ia\" data-q=\"1-ia-3351\">en las proporciones que fijará el Comité según el censo de la población de cada uno de los miembros</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">El <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-accion\">fijará</mark> <mark class=\"m-personalizado\">las contribuciones de los miembros asociados</mark>. <mark class=\"m-personalizado\">c) El</mark> <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-personalizado\">General</mark> <mark class=\"m-accion\">someterá</mark> <mark class=\"m-personalizado\">todos los</mark> <mark class=\"m-plazo\">años</mark> <mark class=\"m-personalizado\">el presupuesto del</mark> <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-personalizado\">a la</mark> aprobación del <mark class=\"m-autoridad\">Comité</mark> (…).</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3352,1-ia-3353\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 39.</b> <mark class=\"m-autoridad\">El Secretario General</mark> <mark class=\"m-accion\">notificará</mark> <mark class=\"m-personalizado\">todos los años a</mark> los Gobiernos de los Miembros la suma a que asciende su <mark class=\"m-destacable\">contribución</mark>. Las contribuciones <mark class=\"m-accion\">se considerarán</mark> exigibles el día mismo de esta notificación, y <mark class=\"m-accion\">se abonarán</mark> <mark class=\"m-autoridad\">al Secretario General</mark> en el <mark class=\"m-resp\" data-q=\"1-ia-3354,1-278\">plazo máximo de seis meses</mark>.</p>"],["Artículos 41 y 42 — Enmiendas y entrada en vigor <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 41.</b> a) <mark class=\"m-accion\">Podrán</mark> <mark class=\"m-personalizado\">hacerse proposiciones</mark> de <mark class=\"m-destacable\">enmienda</mark> <mark class=\"m-personalizado\">del presente Estatuto al</mark> <mark class=\"m-autoridad\">Comité de Ministros</mark> o, en las condiciones previstas en el artículo 23, a la <mark class=\"m-autoridad\">Asamblea</mark> Consultiva. b) El <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-accion\">recomendará,</mark> y <mark class=\"m-accion\">dispondrá que se incorporen a un</mark> <mark class=\"m-personalizado\">Protocolo</mark><span class=\"ex-plg\"><span class=\"ex-plg-t\">, las enmiendas al Estatuto que estime conveniente. c) Cada uno de los</span></span> Protocolos de enmienda <mark class=\"m-accion\">entrará</mark> <mark class=\"m-personalizado\">en vigor</mark> <mark class=\"m-resp\" data-q=\"1-141,1-ia-3358\">una vez firmado y ratificado por las dos terceras partes de los Miembros</mark>. d) <mark class=\"m-personalizado\">No obstante</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">lo dispuesto en los apartados precedentes de este artículo</span></span>, las <mark class=\"m-personalizado\">enmiendas</mark> <mark class=\"m-destacable\">a</mark> <mark class=\"m-personalizado\">los artículos 23 a 35, 38 y 39</mark>, que hayan sido <mark class=\"m-personalizado\">aprobadas por el</mark> <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-personalizado\">y la</mark> <mark class=\"m-autoridad\">Asamblea</mark>, <mark class=\"m-accion\">entrarán</mark> <mark class=\"m-personalizado\">en vigor</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3359\">en la fecha del acta «ad hoc» del Secretario General comunicada a los Gobiernos de los Miembros</mark> en que se certifique la aprobación otorgada a dichas enmiendas. <span class=\"ex-plg\"><span class=\"ex-plg-t\">Las disposiciones del presente apartado únicamente po- drán aplicarse a partir del final de la segunda sesión ordinaria de la Asamblea.</span></span></p><p data-ex=\"*\"><b>Art. 42.</b> a) El presente <mark class=\"m-personalizado\">Estatuto se</mark> <mark class=\"m-accion\">someterá</mark> <mark class=\"m-personalizado\">a ratificación</mark>. <mark class=\"m-destacable\">Las ratificaciones</mark> <mark class=\"m-accion\">se depositarán</mark> en <mark class=\"m-personalizado\">poder del</mark> <mark class=\"m-autoridad\">Gobierno</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">del</u> Reino <u class=\"m-clave\">Unido</u> de Gran Bretaña e Irlanda del Norte</mark>. b) El presente Estatuto <mark class=\"m-accion\">estará</mark> en vigor una vez depositados <mark class=\"m-resp\" data-q=\"1-ia-3361,1-279\">siete instrumentos de ratificación</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">El Gobier- no del Reino Unido notificará a todos los Gobiernos signatarios la entrada en vigor del Estatuto y los nombres de los Miembros del Consejo de Europa que lo sean en esa fecha.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3360\">🎯 1 pregunta</mark></p><p><mark class=\"m-personalizado\">Hecho en</mark> <mark class=\"m-resp\" data-q=\"1-248\">Londres, a los cinco días del mes de mayo de 1949</mark>, <mark class=\"m-personalizado\">en inglés y francés</mark> (…). <span class=\"ex-plg\"><span class=\"ex-plg-t\">España depositó su Instrumento de Adhesión el 24 de noviembre de 1977 y <mark class=\"m-personalizado\">es miembro</mark> de pleno derecho desde esa fecha (art. 4).</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3362\">🎯 1 pregunta</mark></p>"],["Artículos 2, 4 y 5 — Vida, trabajo forzado y libertad · R16 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX,*\"><b>Art. <mark class=\"m-personalizado\">2.</mark></b> <mark class=\"m-personalizado\">1.</mark> El derecho de toda persona a la vida <mark class=\"m-personalizado\">está protegido por la Ley</mark>. <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ser privado de</mark> su vida intencionadamente, <mark class=\"m-personalizado\">salvo en ejecución de una condena que imponga pena capital dictada por un</mark> <mark class=\"m-autoridad\">tribunal</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">al reo de un delito para el que la ley establece esa pena</span></span>. 2. <mark class=\"m-personalizado\">La muerte no se</mark> <mark class=\"m-accion\">considerará</mark> <mark class=\"m-personalizado\">infligida con infracción del presente artículo cuando se</mark> produzca como <mark class=\"m-personalizado\">consecuencia de un <u class=\"m-clave\">recurso a la fuerza</u></mark> que sea <mark class=\"m-personalizado\">absolutamente necesario</mark>: a) <mark class=\"m-resp\" data-q=\"1-173\">En defensa de una persona contra una agresión ilegítima</mark>. b) <mark class=\"m-resp r-ia\" data-q=\"1-ia-3407,1-ia-3901,1-ia-3903\">Para detener a una persona conforme a derecho o para impedir la evasión de un preso o detenido legalmente</mark>. c) <mark class=\"m-resp r-ia\" data-q=\"1-ia-3406\">Para reprimir, de acuerdo con la ley, una revuelta o insurrección</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-280,1-ia-3405\">🎯 2 preguntas</mark></p><p><b>Art. 3.</b> <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> ser sometido a <mark class=\"m-personalizado\">tortura ni a penas o tratos</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3408\">inhumanos o degradantes</mark>.</p><p data-ex=\"EXOF\"><b>Art. 4.</b> 1. <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> ser <mark class=\"m-destacable\">sometido</mark> a esclavitud o servidumbre. 2. <mark class=\"m-personalizado\">Nadie</mark> <mark class=\"m-accion\">podrá</mark> ser <mark class=\"m-destacable\">constreñido</mark> a realizar un <mark class=\"m-personalizado\">trabajo forzado u obligatorio</mark>. <mark class=\"m-personalizado\">3. No se considera</mark> como «<mark class=\"m-personalizado\"><u class=\"m-clave\">trabajo</u> forzado u obligatorio»</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">» en el sentido del presente artículo</span></span>: <mark class=\"m-personalizado\">a) todo trabajo exigido normalmente a una persona privada de libertad</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en las condiciones previstas por el artículo 5 del presente Convenio,</span></span> <mark class=\"m-personalizado\">o <mark class=\"m-resp r-ia\" data-q=\"1-ia-3411\">durante su libertad condicional</mark></mark>; <mark class=\"m-personalizado\">b) todo servicio de carácter militar o,</mark> en el caso de objetores de conciencia <span class=\"ex-plg\"><span class=\"ex-plg-t\">en los países en que la objeción de conciencia sea reconocida como legítima</span></span>, cualquier <mark class=\"m-personalizado\"><u class=\"m-clave\">otro</u></mark> servicio sustitutivo <span class=\"ex-plg\"><span class=\"ex-plg-t\">del servicio militar obligatorio</span></span>; c) <mark class=\"m-personalizado\">todo <u class=\"m-clave\">servicio</u> exigido cuando alguna emergencia o calamidad amenacen la vida o el bienestar de la comunidad</mark>; d) <mark class=\"m-personalizado\">todo trabajo o servicio</mark> que forme parte de las <mark class=\"m-resp\" data-q=\"1-84,1-ia-3412\">obligaciones cívicas normales</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3409,1-ia-3410\">🎯 2 preguntas</mark></p><p><b>a)</b> Si ha sido <mark class=\"m-destacable\">penado legalmente</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en virtud de una <mark class=\"m-personalizado\">sentencia</mark> dictada por un <mark class=\"m-autoridad\">tribunal</mark> <mark class=\"m-personalizado\">competente.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3413\">🎯 1 pregunta</mark></p><p><b>b)</b> Si ha sido <mark class=\"m-destacable\">detenido</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">preventivamente o internado, conforme a derecho, por desobediencia a una orden judicial o para asegurar el cumplimiento de una obligación</mark> establecida por la ley.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3414\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>c)</b> <mark class=\"m-personalizado\">Si ha sido</mark> detenido preventivamente o internado, conforme a derecho, <mark class=\"m-personalizado\">para hacerle comparecer ante</mark> la <mark class=\"m-autoridad\">autoridad</mark> judicial competente, cuando existan indicios <mark class=\"m-destacable\"><u class=\"m-clave\">racionales</u></mark> de que <mark class=\"m-plazo\">ha</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">cometido</u> una</mark> infracción o cuando se estime necesario <mark class=\"m-personalizado\">para impedirle</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">que</mark></span> <mark class=\"m-personalizado\">cometa</mark> una infracción o que <mark class=\"m-personalizado\">huya</mark> después de haberla cometido. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3415\">🎯 1 pregunta</mark></p><p><b>d)</b> Si se trata del <mark class=\"m-destacable\">internamiento <u class=\"m-clave\">de</u> un</mark> menor en virtud de una <mark class=\"m-personalizado\">orden legalmente</mark> acordada <mark class=\"m-resp r-ia\" data-q=\"1-ia-3416\">con el fin de vigilar su educación o de su detención, conforme a derecho, con el fin de hacerle comparecer ante la autoridad competente</mark>.</p><p data-ex=\"*\"><b>e)</b> Si se trata del internamiento, <mark class=\"m-personalizado\">conforme a derecho,</mark> de una persona susceptible de propagar una enfermedad contagiosa, de un <mark class=\"m-personalizado\">enajenado, de un alcohólico, de un <u class=\"m-clave\">toxicómano</u> o</mark> de un <mark class=\"m-resp\" data-q=\"1-281\">vagabundo</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3417\">🎯 1 pregunta</mark></p><p><b>f)</b> Si se trata de <mark class=\"m-destacable\">la <u class=\"m-clave\">detención</u></mark> <mark class=\"m-personalizado\">preventiva</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">o del internamiento,</u></mark> <mark class=\"m-personalizado\">conforme a derecho,</mark> de una persona <mark class=\"m-resp r-ia\" data-q=\"1-ia-3418\">para impedir que entre ilegalmente en el territorio o contra la que esté en curso un procedimiento de expulsión o extradición</mark>.</p><p data-ex=\"EX\"><b>2.</b> Toda <mark class=\"m-personalizado\">persona detenida preventivamente debe ser informada,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3419\">en el más breve plazo y en una lengua que comprenda</mark>, de <mark class=\"m-resp r-ia\" data-q=\"1-ia-3419,1-ia-3423,1-ia-3426\">los motivos de su detención y de cualquier acusación formulada contra ella</mark>.</p><p data-ex=\"*\"><b>3.</b> Toda <mark class=\"m-autoridad\">persona detenida</mark> <mark class=\"m-personalizado\">preventivamente o internada en</mark> las condiciones previstas en el párrafo <mark class=\"m-personalizado\">1, c),</mark> del presente artículo <mark class=\"m-accion\">deberá</mark> <mark class=\"m-personalizado\">ser <u class=\"m-clave\">conducida</u> sin dilación a <u class=\"m-clave\">presencia de un</u></mark> <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-personalizado\">o de otra</mark> <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">habilitada por la ley</mark> para ejercer poderes judiciales, y <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">derecho a ser <u class=\"m-clave\">juzgada</u></mark> en un plazo razonable <mark class=\"m-destacable\"><u class=\"m-clave\">o</u></mark> <mark class=\"m-personalizado\">a ser</mark> puesta en <mark class=\"m-personalizado\"><u class=\"m-clave\">libertad</u> durante el procedimiento.</mark> La puesta en libertad <mark class=\"m-personalizado\">puede ser condicionada a</mark> <mark class=\"m-resp\" data-q=\"1-282,1-ia-3420\">una garantía que asegure la comparecencia del interesado en juicio</mark>.</p><p><b>4.</b> <mark class=\"m-personalizado\">Toda persona</mark> <mark class=\"m-autoridad\">privada de su</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">libertad</mark></span> <mark class=\"m-destacable\">mediante</mark> <mark class=\"m-personalizado\">detención preventiva o internamiento</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">derecho</u></mark> a presentar un <mark class=\"m-personalizado\"><u class=\"m-clave\">recurso</u></mark> ante un <mark class=\"m-autoridad\">órgano</mark> <mark class=\"m-personalizado\">judicial,</mark> a fin</span></span> de que se <mark class=\"m-personalizado\"><u class=\"m-clave\">pronuncie</u> en breve plazo</mark> sobre <mark class=\"m-resp r-ia\" data-q=\"1-ia-3421\">la legalidad de su privación de libertad y ordene su puesta en libertad, si fuera ilegal</mark>.</p><p><b>5.</b> <mark class=\"m-personalizado\">Toda</mark> persona <mark class=\"m-personalizado\">víctima de una detención</mark> preventiva <span class=\"ex-plg\"><span class=\"ex-plg-t\">o de un internamiento <mark class=\"m-personalizado\">en condiciones contrarias</mark> a las disposiciones de este artículo <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">derecho a una</u> reparación.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3422\">🎯 1 pregunta</mark></p>"],["Artículos 6, 12, 15 y 16 — Proceso equitativo, matrimonio, derogación y actividad política de extranjeros <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R16</span>","<p data-ex=\"*\" data-r=\"R16\"><span class=\"ex-sello ex-sello-r\">R16</span> <b>Art. 6.</b> <mark class=\"m-destacable\">1.</mark> <mark class=\"m-autoridad\">Toda persona</mark> tiene <mark class=\"m-personalizado\">derecho a que su causa sea oída</mark> <mark class=\"m-destacable\">equitativa,</mark> <mark class=\"m-personalizado\">públicamente y dentro de un plazo razonable,</mark> por un <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-personalizado\">independiente e</mark> imparcial, establecido por la Ley <span class=\"ex-plg\"><span class=\"ex-plg-t\">, que decidirá los litigios sobre sus derechos y obligaciones de carácter civil o sobre el fundamento de cualquier acusación en ma- teria penal dirigida contra ella. La sentencia debe ser pronunciada públicamente, pero el acceso a la Sala de Audiencia puede ser prohibido a la prensa y al público durante la totalidad o parte del proceso en interés de la moralidad, del orden público o de la seguridad nacional en una sociedad democrática, cuando los intereses de los menores o la protección de la vida privada de las partes en el proceso así lo exijan o en la medida considerada necesaria por el Tribunal, cuando en circunstancias especiales la publicidad pudiera ser perjudicial para los intereses de la justicia</span></span>. 2. <mark class=\"m-personalizado\">Toda persona</mark> acusada de una infracción <mark class=\"m-personalizado\">se presume inocente</mark> hasta que su culpabilidad haya sido legalmente declarada. 3. <mark class=\"m-personalizado\">Todo acusado</mark> tiene, como mínimo, los siguientes <mark class=\"m-personalizado\">derechos</mark>: a) <mark class=\"m-personalizado\">a ser informado</mark>, en <mark class=\"m-personalizado\">el más breve plazo</mark>, en una <mark class=\"m-personalizado\">lengua</mark> que comprenda y <mark class=\"m-personalizado\">detalladamente</mark>, de <mark class=\"m-personalizado\">la naturaleza y de la causa de la acusación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">formulada contra él</span></span>; (…) <mark class=\"m-personalizado\">e)</mark> a ser asistido gratuitamente de un intérprete, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3429\">si no comprende o no habla la lengua empleada en la Audiencia</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-197\">🎯 1 pregunta</mark></p><p><b>Art. 12.</b> <mark class=\"m-resp\" data-q=\"1-66\">A partir de la edad núbil</mark>, el hombre y la mujer tienen <mark class=\"m-personalizado\">derecho a casarse y a fundar una familia</mark> <mark class=\"m-resp\" data-q=\"1-ia-3439\">según las leyes nacionales</mark> que rijan el ejercicio de este derecho.</p><p><b>Art. 15.</b> 1. <mark class=\"m-personalizado\">En caso de <u class=\"m-clave\">guerra o</u> de otro peligro público que amenace</mark> la vida de <mark class=\"m-personalizado\">la nación,</mark> <mark class=\"m-autoridad\">cualquier Alta Parte Contratante</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">tomar medidas que <u class=\"m-clave\">deroguen las</u> obligaciones previstas en el presente Convenio en la medida estricta en que lo exija la situación, y</mark> supuesto <mark class=\"m-personalizado\">que tales medidas</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3442\">no estén en contradicción con las otras obligaciones que dimanan del Derecho internacional</mark>.</p><p data-ex=\"*\"><b>2.</b> La disposición precedente <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u> autoriza</mark> ninguna <mark class=\"m-personalizado\">derogación al</mark> artículo 2, <mark class=\"m-destacable\"><u class=\"m-clave\">salvo</u></mark> para el caso de muertes resultantes de <mark class=\"m-personalizado\">actos lícitos de guerra, y a los</mark> artículos <mark class=\"m-resp\" data-q=\"1-283\">3, 4 (párrafo 1) y 7</mark>.11</p><p><b>3.</b> <mark class=\"m-autoridad\">Toda Alta Parte Contratante</mark> que ejerza este <mark class=\"m-personalizado\">derecho de derogación</mark> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">plenamente informado</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3306,1-ia-3312,1-ia-3444\">al Secretario general del Consejo de Europa</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">las <mark class=\"m-personalizado\">medidas</mark> tomadas y de <mark class=\"m-personalizado\">los motivos</mark> que las han inspirado. <mark class=\"m-accion\">Deberá</mark> igualmente informar al <mark class=\"m-autoridad\">Secretario</mark> general del <mark class=\"m-autoridad\">Consejo</mark> de Europa de <mark class=\"m-personalizado\">la fecha en</mark> que esas medidas hayan <mark class=\"m-personalizado\">dejado de estar en vigor</mark> y las disposiciones del Convenio vuelvan a tener plena aplicación.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3560\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 16.</b> <mark class=\"m-personalizado\">Ninguna de las disposiciones</mark> de los artículos 10, 11 y 14 (expresión, reunión y asociación, no discriminación) <mark class=\"m-accion\">podrá</mark> ser interpuesta en el sentido de que <mark class=\"m-personalizado\">prohíbe a las Altas</mark> Partes Contratantes <mark class=\"m-personalizado\">imponer restricciones a la actividad política de los <mark class=\"m-resp\" data-q=\"1-284\">extranjeros</mark></mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3445\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 8 — <mark class=\"m-personalizado\">Derecho</mark> al <mark class=\"m-destacable\">respeto</mark> a la vida privada y familiar: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3433\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 13 — Derecho a un recurso efectivo <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b><mark class=\"m-destacable\">Art. 13.</mark></b> <mark class=\"m-autoridad\">Toda persona</mark> <mark class=\"m-personalizado\">cuyos derechos y libertades</mark> reconocidos en el presente Convenio <mark class=\"m-personalizado\">hayan sido violados</mark> tiene derecho a <mark class=\"m-personalizado\">la</mark> concesión de un <mark class=\"m-personalizado\">recurso efectivo ante una <u class=\"m-clave\">instancia nacional,</u></mark> <span class=\"m-caja\"><mark class=\"m-personalizado\">incluso</mark></span> <mark class=\"m-personalizado\">cuando</mark> la violación haya sido <mark class=\"m-personalizado\">cometida por personas</mark> que actúen en el ejercicio de sus <mark class=\"m-personalizado\">funciones oficiales.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3440\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 7 — <u class=\"m-clave\">No</u> hay <mark class=\"m-destacable\">pena</mark> <u class=\"m-clave\">sin</u> <mark class=\"m-personalizado\">ley</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3243,1-ia-3430,1-ia-3431,1-ia-3545\">🎯 4 preguntas más de este artículo</mark>"],["Artículo 10 — Libertad de expresión <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 10.</b> <b>1.</b> Toda persona tiene <mark class=\"m-personalizado\">derecho a la libertad de expresión.</mark> Este derecho comprende la <mark class=\"m-personalizado\">libertad de opinión y</mark> la libertad de <mark class=\"m-personalizado\"><u class=\"m-clave\">recibir</u> o de comunicar informaciones o ideas sin</mark> que pueda haber <mark class=\"m-destacable\">injerencia</mark> de <mark class=\"m-autoridad\">autoridades</mark> públicas <mark class=\"m-destacable\"><u class=\"m-clave\">y</u> sin</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">consideración de fronteras.</u></mark> El presente artículo <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u> impide</mark> que los <mark class=\"m-autoridad\">Estados</mark> sometan <mark class=\"m-personalizado\">las empresas de</mark> <mark class=\"m-destacable\">radiodifusión,</mark> <mark class=\"m-personalizado\">de cinematografía o de televisión a un régimen de autorización <u class=\"m-clave\">previa.</u></mark> <b>2.</b> <mark class=\"m-personalizado\">El ejercicio</mark> de estas libertades, que entrañan deberes y responsabilidades, <mark class=\"m-accion\">podrá ser sometido</mark> <mark class=\"m-personalizado\">a ciertas formalidades, condiciones, restricciones o sanciones</mark> previstas por la <mark class=\"m-personalizado\">ley,</mark> que constituyan medidas <mark class=\"m-personalizado\">necesarias,</mark> en una sociedad democrática, para la <mark class=\"m-personalizado\">seguridad nacional, la integridad territorial</mark> o la <mark class=\"m-personalizado\">seguridad pública,</mark> la defensa del <mark class=\"m-personalizado\">orden y</mark> la <mark class=\"m-personalizado\">prevención del delito,</mark> la <mark class=\"m-personalizado\">protección de la salud o de la moral,</mark> la protección de <mark class=\"m-personalizado\">la reputación</mark> o de los derechos ajenos, para <mark class=\"m-personalizado\">impedir la divulgación de informaciones confidenciales o</mark> para <mark class=\"m-personalizado\">garantizar</mark> la <mark class=\"m-autoridad\">autoridad</mark> <mark class=\"m-personalizado\">y la imparcialidad del poder judicial.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-285,1-ia-3435,1-ia-3436\">🎯 3 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 11 — <mark class=\"m-personalizado\"><u class=\"m-clave\">Libertad</u> de</mark> <mark class=\"m-destacable\">reunión</mark> y de asociación: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3438,1-ia-3437\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 19 a 23 — Institución, jueces, elección y mandato · R17 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R17</span>","<p><b>Art. 19.</b> Con <mark class=\"m-personalizado\">el fin de asegurar el respeto de los compromisos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que resultan para las Altas Partes Contratantes del presente Convenio y sus Protocolos</span></span>, se <mark class=\"m-autoridad\">instituye</mark> un <mark class=\"m-autoridad\"><u class=\"m-clave\">Tribunal Europeo</u> de Derechos Humanos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, en lo sucesivo denominado “el Tribunal”</span></span>. <mark class=\"m-accion\">Funcionará</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3448\">de manera permanente</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-132\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 20.</b> El <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">se compondrá</mark> de un <mark class=\"m-personalizado\">número</mark> de <mark class=\"m-autoridad\">Jueces</mark> <mark class=\"m-resp\" data-q=\"1-ia-3449,1-286\">igual al de las Altas Partes Contratantes</mark>.</p><p data-ex=\"EXOF,*\"><b>Art. 21.</b> 1. <mark class=\"m-autoridad\">Los Jueces</mark> <mark class=\"m-accion\">deberán gozar</mark> <u class=\"m-clave\">de</u> la más <mark class=\"m-personalizado\"><u class=\"m-clave\">alta</u> consideración <u class=\"m-clave\">moral</u></mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y reunir las condiciones requeridas para el ejercicio de altas funciones judiciales o ser jurisconsultos de reconocida competencia</span></span>. 2. <mark class=\"m-autoridad\">Los candidatos</mark> <mark class=\"m-accion\">deberán</mark> ser <mark class=\"m-resp\" data-q=\"1-179\">menores de 65 años</mark> <mark class=\"m-personalizado\">en</mark> la fecha en <mark class=\"m-personalizado\">que la</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Asamblea</u></mark> <mark class=\"m-personalizado\">Parlamentaria reciba la lista de tres candidatos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, en virtud del artículo 22</span></span>. 3. Los <mark class=\"m-autoridad\">Jueces</mark> <mark class=\"m-accion\">formarán</mark> <mark class=\"m-personalizado\">parte del</mark> <mark class=\"m-autoridad\">tribunal</mark> <mark class=\"m-destacable\">a título individual</mark>. (…)</p><p data-ex=\"*\" data-r=\"R17\"><span class=\"ex-sello ex-sello-r\">R17</span> <b>Art. 22.</b> Los <mark class=\"m-autoridad\">Jueces</mark> <mark class=\"m-accion\">serán</mark> elegidos <mark class=\"m-resp r-ia r-vec\" data-q=\"1-ia-3735\">por la Asamblea Parlamentaria</mark> en razón de cada Alta Parte Contratante, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3735\">por mayoría absoluta de votos</mark>, <mark class=\"m-resp\" data-q=\"1-142,1-ia-3450,1-ia-3452\">de una lista de tres candidatos</mark> presentada por esa Alta Parte Contratante.</p><p data-ex=\"*\"><b>Art. 23.</b> 1. Los <mark class=\"m-autoridad\">jueces</mark> <mark class=\"m-accion\">serán</mark> elegidos por un periodo de <mark class=\"m-resp\" data-q=\"1-112,1-ia-3453\">nueve años</mark>. <mark class=\"m-accion\">No serán</mark> <mark class=\"m-resp\" data-q=\"1-143\">reelegibles</mark>. 2. Los <mark class=\"m-autoridad\">jueces</mark> <mark class=\"m-accion\">permanecerán</mark> en sus funciones hasta su sustitución. No obstante, <mark class=\"m-accion\">continuarán</mark> conociendo de los asuntos que tengan ya asignados. 3. Un <mark class=\"m-autoridad\">juez</mark> sólo <mark class=\"m-accion\">podrá</mark> ser relevado de sus funciones si <mark class=\"m-resp r-ia\" data-q=\"1-ia-3455\">los demás jueces deciden, por mayoría de dos tercios</mark>, que <mark class=\"m-destacable\">dicho</mark> <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-personalizado\">ha dejado de</mark> <mark class=\"m-destacable\">reunir</mark> las <mark class=\"m-personalizado\">condiciones requeridas para</mark> <mark class=\"m-accion\">serlo.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3454\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 24 — <mark class=\"m-autoridad\">Secretaría</mark> y ponentes: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3456,1-ia-4178\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 25 y 26 — Pleno, juez único, Comités, Salas y Gran Sala <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX,*\"><b><mark class=\"m-accion\">Art.</mark> 25.</b> El <mark class=\"m-autoridad\">Tribunal,</mark> reunido en <mark class=\"m-personalizado\">pleno: a)</mark> <mark class=\"m-accion\">Elegirá</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3457,1-ia-3752\">por un período de tres años</mark>, <mark class=\"m-personalizado\">a su</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Presidente</u></mark> <mark class=\"m-personalizado\">y a uno o dos Vicepresidentes,</mark> que <mark class=\"m-accion\">serán</mark> <mark class=\"m-resp\" data-q=\"1-143\">reelegibles</mark>; b) <mark class=\"m-accion\">constituirá</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Salas</u></mark> por un período determinado; c) <span class=\"m-circulo\"><mark class=\"m-accion\">elegirá</mark></span> <mark class=\"m-personalizado\">a los <u class=\"m-clave\">Presidentes</u> de las</mark> <mark class=\"m-autoridad\">Salas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">del Tribunal</span></span>, que <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">reelegibles</mark>; d) <mark class=\"m-accion\">aprobará</mark> <mark class=\"m-personalizado\">su reglamento</mark>; e) <mark class=\"m-accion\">elegirá</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">al</u></mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Secretario</u></mark> <mark class=\"m-personalizado\">y a uno o varios Secretarios adjuntos</mark>; f) <mark class=\"m-accion\">formulará</mark> cualquier <mark class=\"m-personalizado\">solicitud</mark> con arreglo al párrafo 2 del artículo 26 <mark class=\"m-destacable\">(reducir a cinco los</mark> <mark class=\"m-autoridad\">jueces</mark> <mark class=\"m-destacable\">de</mark> <mark class=\"m-autoridad\">Sala).</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3458\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b><mark class=\"m-destacable\">Art. 26.</mark></b> 1. <span class=\"ex-plg\"><span class=\"ex-plg-t\">1. \u0007Para el examen de los asuntos que se le sometan,</span></span> <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">actuará</mark> <mark class=\"m-personalizado\">en formación de:</mark> <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-destacable\">único</mark>, en <mark class=\"m-resp\" data-q=\"1-287\">Comités compuestos por tres jueces</mark>, en <mark class=\"m-autoridad\">Salas</mark> <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">siete</mark> <mark class=\"m-autoridad\">jueces</mark> <mark class=\"m-destacable\">y</mark> en una <mark class=\"m-resp r-ia\" data-q=\"1-ia-3459\">Gran Sala de diecisiete jueces</mark>. <mark class=\"m-personalizado\">Las</mark> <mark class=\"m-autoridad\">Salas del Tribunal</mark> <mark class=\"m-accion\">constituirán</mark> <mark class=\"m-personalizado\">los Comités</mark> <mark class=\"m-plazo\">por un</mark> periodo determinado <mark class=\"m-personalizado\">(el Pleno constituye las</mark> <mark class=\"m-autoridad\">Salas</mark> <mark class=\"m-personalizado\">y las</mark> <mark class=\"m-autoridad\">Salas</mark> constituyen los Comités).</p><p data-ex=\"EX\"><b>2.</b> Cuando el <mark class=\"m-autoridad\">Pleno del Tribunal</mark> <mark class=\"m-personalizado\">así lo solicite</mark>, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3460,1-ia-3461\">el Comité de Ministros podrá, por decisión unánime y por un periodo determinado, reducir a cinco el número de jueces de las Salas</mark>.</p><p><b>3.</b> Cuando actúe en formación de <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-destacable\">único,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3462\">ningún juez podrá examinar una solicitud contra la Alta Parte Contratante en cuya representación fue elegido</mark> <mark class=\"m-personalizado\">dicho</mark> <mark class=\"m-autoridad\">juez</mark>.</p><p data-ex=\"EX\"><b>5.</b> <mark class=\"m-accion\">Formarán</mark> <mark class=\"m-personalizado\">también parte de</mark> la <mark class=\"m-autoridad\">Gran Sala</mark>: <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">Presidente</mark> <span class=\"m-caja\"><mark class=\"m-autoridad\">del Tribunal,</mark></span> <mark class=\"m-personalizado\">los</mark> Vicepresidentes, los <mark class=\"m-personalizado\">Presidentes de las</mark> <mark class=\"m-autoridad\">Salas</mark> <mark class=\"m-destacable\">y</mark> demás <mark class=\"m-autoridad\">jueces</mark> <mark class=\"m-personalizado\">designados</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el reglamento del Tribunal. \u0007</span></span>. Cuando el <mark class=\"m-personalizado\">asunto sea deferido a la Gran</mark> <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-personalizado\">en</mark> virtud del <mark class=\"m-personalizado\">artículo 43, ningún</mark> <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-autoridad\">Sala</mark> que haya dictado la <mark class=\"m-personalizado\">sentencia</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">actuar</mark> en la misma, <mark class=\"m-personalizado\">con</mark> <mark class=\"m-destacable\">excepción</mark>: <mark class=\"m-resp r-ia\" data-q=\"1-ia-3502\">del Presidente de la Sala</mark> (no del <mark class=\"m-autoridad\">Tribunal)</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3472\">y del Juez que haya intervenido en representación de la Alta Parte Contratante interesada</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3463,1-ia-3464\">🎯 2 preguntas</mark></p>"],["Artículos 27 y 28 — Competencias del juez único y de los Comités <span class=\"ex-sello\">✱</span>","<p><b>Art. 27.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">1. El <mark class=\"m-autoridad\">juez</mark> <mark class=\"m-destacable\">único</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">declarar</mark> inadmisible <mark class=\"m-personalizado\">o</mark> <mark class=\"m-destacable\">eliminar</mark> <mark class=\"m-personalizado\">del registro de</mark> <mark class=\"m-destacable\">asuntos</mark> del <mark class=\"m-autoridad\">Tribunal</mark> una <mark class=\"m-personalizado\">demanda</mark> presentada en virtud del artículo 34 (demandas individuales), cuando <mark class=\"m-personalizado\">pueda adoptarse tal resolución sin tener que proceder</mark> a un examen complementario. 2.</span></span> La resolución <mark class=\"m-resp r-ia\" data-q=\"1-ia-3465,1-ia-3467\">será definitiva</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">3. Si el <mark class=\"m-autoridad\">juez</mark> único <mark class=\"m-personalizado\">no declara inadmisible</mark> una demanda ni la <mark class=\"m-personalizado\">elimina</mark> del registro, (…) <mark class=\"m-accion\">remitirá</mark> la misma a un <mark class=\"m-autoridad\">Comité</mark> o a una <mark class=\"m-autoridad\">Sala</mark> para <mark class=\"m-personalizado\">su examen</mark> <mark class=\"m-destacable\">complementario</mark>.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4202\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 28.</b> 1. Respecto de una <mark class=\"m-personalizado\">demanda</mark> presentada en virtud del <mark class=\"m-personalizado\">artículo 34,</mark> un <mark class=\"m-autoridad\">Comité</mark> <mark class=\"m-accion\">podrá,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3466\">por unanimidad</mark>: a) declarar la misma <mark class=\"m-personalizado\"><u class=\"m-clave\">inadmisible o eliminarla</u> del registro de</mark> asuntos <span class=\"ex-plg\"><span class=\"ex-plg-t\">, cuando pueda adoptarse tal resolución sin tener que proceder a un examen complementario</span></span>; <mark class=\"m-personalizado\">o b)</mark> <mark class=\"m-resp\" data-q=\"1-288\">declararla admisible y dictar al mismo tiempo sentencia sobre el fondo, si la cuestión subyacente al caso <span class=\"ex-plg\"><span class=\"ex-plg-t\">, relativa a la interpretación o la aplicación del Convenio o de sus Protocolos,</span></span> ya ha dado lugar a jurisprudencia bien establecida del Tribunal</mark>. 2. <mark class=\"m-personalizado\">Las resoluciones y sentencias</mark> dictadas en virtud del párrafo 1 <mark class=\"m-accion\">serán</mark> <mark class=\"m-destacable\">definitivas</mark>.</p>"],["Artículos 29 y 30 — Resoluciones de las Salas e inhibición en favor de la Gran Sala <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b><mark class=\"m-personalizado\">Art. 29.</mark></b> <b>2.</b> <mark class=\"m-personalizado\">La</mark> <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-destacable\">se</mark> <mark class=\"m-accion\">pronunciará</mark> sobre <mark class=\"m-personalizado\">la admisibilidad y</mark> el fondo <mark class=\"m-personalizado\">de las</mark> demandas de <mark class=\"m-destacable\">los</mark> <mark class=\"m-autoridad\">Estados</mark> presentadas en virtud del <mark class=\"m-personalizado\">artículo 33.</mark> Salvo decisión en <mark class=\"m-personalizado\"><u class=\"m-clave\">contrario</u> del</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-personalizado\">en casos excepcionales,</mark> la resolución <mark class=\"m-destacable\">sobre</mark> la admisibilidad <mark class=\"m-accion\">se tomará</mark> por <mark class=\"m-resp\" data-q=\"1-289\">separado</mark>.</p><p data-ex=\"*\"><b>Art. 30.</b> Si <mark class=\"m-destacable\">el asunto pendiente ante</mark> <mark class=\"m-personalizado\">una</mark> <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-personalizado\">plantea una cuestión grave</mark> relativa a la interpretación del Convenio o de sus Protocolos, <mark class=\"m-personalizado\">o si</mark> la solución dada a una cuestión pudiera <mark class=\"m-personalizado\">ser contradictoria con una sentencia</mark> dictada anteriormente por el <mark class=\"m-autoridad\">Tribunal, la Sala</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">inhibirse en favor de la Gran</mark> <mark class=\"m-autoridad\"><u class=\"m-clave\">Sala,</u></mark> <mark class=\"m-personalizado\">mientras</mark> <mark class=\"m-resp\" data-q=\"1-290\">no haya dictado sentencia</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3469\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 29 — <mark class=\"m-personalizado\">Resoluciones</mark> de las <mark class=\"m-autoridad\">salas</mark> sobre <mark class=\"m-personalizado\">la admisibilidad y</mark> el fondo del <mark class=\"m-personalizado\">asunto</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3468\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 31 — Atribuciones de la gran sala <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 31.</b> La Gran <mark class=\"m-autoridad\">Sala:</mark></p><p><b>c)</b> <mark class=\"m-accion\">examinará</mark> las <mark class=\"m-personalizado\">solicitudes de emisión de <mark class=\"m-resp\" data-q=\"1-291\">opiniones consultivas</mark></mark> presentadas en virtud del <mark class=\"m-personalizado\">artículo 47.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3470\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 32 — <mark class=\"m-personalizado\">Competencia del</mark> <mark class=\"m-autoridad\">Tribunal</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3471,1-ia-4179,1-ia-4180\">🎯 3 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 33</mark> — <mark class=\"m-destacable\">Asuntos</mark> entre <mark class=\"m-autoridad\">Estados</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3472,1-ia-4181\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 34 — Demandas individuales <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 34.</b> <mark class=\"m-destacable\">El</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-destacable\">conocer de</mark> una <mark class=\"m-destacable\">demanda</mark> presentada por <mark class=\"m-personalizado\">cualquier persona física, organización no gubernamental o grupo de particulares que se considere víctima</mark> de una violación, por una de las Altas Partes Contratantes, <mark class=\"m-personalizado\">de los derechos</mark> reconocidos en <mark class=\"m-personalizado\">el Convenio o sus Protocolos.</mark> <mark class=\"m-autoridad\">Las Altas Partes</mark> Contratantes <mark class=\"m-personalizado\">se comprometen a</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3473\">no poner traba alguna al ejercicio eficaz de este derecho</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-292\">🎯 1 pregunta</mark></p>"],["Artículos 35 y 36 — Admisibilidad e intervención de terceros <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"EX\"><b>Art. 35.</b> 1. <mark class=\"m-autoridad\">Al Tribunal</mark> <mark class=\"m-accion\">no podrá</mark> <mark class=\"m-personalizado\">recurrirse sino después de agotar las vías de recursos internas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, tal como se en- tiende según los principios de derecho internacional generalmente reconocidos</span></span> y en el <mark class=\"m-resp r-ia\" data-q=\"1-ia-3257,1-ia-3474\">plazo de cuatro meses a partir de la fecha de la resolución interna definitiva</mark>.</p><p data-ex=\"*\"><b>2.</b> El <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">no admitirá</mark> ninguna demanda individual <span class=\"ex-plg\"><span class=\"ex-plg-t\">entablada en aplicación del artículo 34,</span></span> <span class=\"ex-plg\"><span class=\"ex-plg-t\">cuando: a) sea anónima, o b) sea esencialmente la misma que una demanda examinada</span></span> anteriormente por el <mark class=\"m-autoridad\">Tribunal</mark> o ya sometida a otra instancia internacional <span class=\"ex-plg\"><span class=\"ex-plg-t\">de investigación o de arreglo,</span></span> y no contenga hechos nuevos. <mark class=\"m-resp ex-q\" data-q=\"1-293,1-ia-3475\">🎯 2 preguntas</mark></p><p><b>3.</b> El <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">declarará</mark> inadmisible cualquier demanda individual <span class=\"ex-plg\"><span class=\"ex-plg-t\">presentada en virtud del artículo 34</span></span> si considera que: a) la demanda es incompatible con las disposiciones del Convenio <span class=\"ex-plg\"><span class=\"ex-plg-t\">o de sus Protocolos</span></span><span class=\"ex-plg\"><span class=\"ex-plg-t\">, manifiestamente mal fundada o abusiva; o b) el demandante no ha sufrido</span></span> un perjuicio importante, <mark class=\"m-resp\" data-q=\"1-ia-3476,1-ia-3505\">a menos que el respeto de los derechos humanos garantizados por el Convenio y por sus Protocolos exija un examen del fondo de la demanda</mark>.</p><p><b>4.</b> El <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">rechazará</mark> cualquier demanda que considere inadmisible (…). <mark class=\"m-accion\">Podrá decidirlo</mark> así <mark class=\"m-resp r-ia\" data-q=\"1-ia-3477\">en cualquier fase del procedimiento</mark>.</p><p data-ex=\"*\"><b>Art. 36.</b> 1. En cualquier asunto que se suscite ante una <mark class=\"m-autoridad\">Sala</mark> o ante la Gran <mark class=\"m-autoridad\">Sala,</mark> la Alta Parte Contratante cuyo nacional sea demandante <mark class=\"m-accion\">tendrá</mark> derecho a <mark class=\"m-resp r-ia\" data-q=\"1-ia-3501\">presentar observaciones por escrito y a participar en la vista</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">2. En interés de la buena administración de la justicia, el Presidente del Tribunal podrá invitar a cualquier Alta Parte Contratante que no sea parte en el asunto o a cualquier persona interesada distinta del de- mandante, a que presente observaciones por escrito o a participar en la vista.</span></span> 3. En cualquier asunto que se suscite ante una <mark class=\"m-autoridad\">Sala</mark> o ante la Gran <mark class=\"m-autoridad\">Sala,</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3402,1-ia-3503\">el Comisario de Derechos Humanos del Consejo de Europa</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-resp\" data-q=\"1-294\">presentar observaciones por escrito y participar en la vista</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 37 — Cancelación: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3504,1-ia-3506\">🎯 2 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 38 — Examen del <mark class=\"m-personalizado\">asunto</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3507,1-ia-4182\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 39 — Transacción.18 <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>Art. 39.</b> 1. <mark class=\"m-plazo\">En cualquier fase del procedimiento,</mark> <mark class=\"m-autoridad\">el Tribunal</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">ponerse a disposición de las partes interesadas para conseguir una transacción</mark> sobre el asunto <mark class=\"m-personalizado\">inspirándose</mark> para ello en el <mark class=\"m-personalizado\">respeto a los derechos humanos</mark> tal como los reconocen el Convenio y sus Protocolos.</p><p><b>2.</b> El procedimiento a que se refiere el párrafo 1 <mark class=\"m-accion\">será</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3508\">confidencial</mark>.</p><p><b>4.</b> <mark class=\"m-personalizado\">Esta resolución</mark> <mark class=\"m-destacable\">se</mark> <mark class=\"m-accion\">transmitirá</mark> <mark class=\"m-personalizado\">al</mark> <mark class=\"m-autoridad\">Comité de Ministros,</mark> <mark class=\"m-personalizado\">que</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3509\">supervisará la ejecución de los términos de la transacción tal como se recojan en la resolución</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 40 — <mark class=\"m-personalizado\">Vista</mark> <mark class=\"m-personalizado\">pública</mark> y <u class=\"m-clave\">acceso a</u> los <mark class=\"m-personalizado\">documentos</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3510,1-ia-3511,1-ia-3539\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 41 — Arreglo equitativo <span class=\"ex-sello\">EX</span>","<p data-ex=\"EX\"><b>Art. 41.</b> <mark class=\"m-destacable\">Si</mark> <mark class=\"m-personalizado\">el</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">declara</u> que ha habido <u class=\"m-clave\">violación</u></mark> del Convenio o de sus Protocolos y si <mark class=\"m-personalizado\">el derecho interno</mark> de la Alta Parte Contratante <mark class=\"m-personalizado\">sólo permite de manera imperfecta reparar</mark> las consecuencias de dicha violación, <mark class=\"m-autoridad\">el Tribunal</mark> <mark class=\"m-accion\">concederá</mark> <mark class=\"m-personalizado\">a</mark> la parte perjudicada, si así procede, <mark class=\"m-personalizado\"><mark class=\"m-resp r-ia\" data-q=\"1-ia-3512\">una satisfacción equitativa</mark>.</mark></p>"],["Artículos 43, 45 y 46 — Remisión a la Gran Sala, opiniones separadas y ejecución de sentencias · R18 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R18</span>","<p data-ex=\"*\"><b>Art. 43.</b> 1. En <mark class=\"m-personalizado\">el</mark> <mark class=\"m-resp\" data-q=\"1-144,1-ia-3513,1-ia-3516\">plazo de tres meses a partir de la fecha de la sentencia de una Sala</mark>, <mark class=\"m-personalizado\">cualquier parte en el asunto</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">solicitar</mark>, <mark class=\"m-personalizado\">en <u class=\"m-clave\">casos excepcionales</u></mark>, <mark class=\"m-personalizado\">la <u class=\"m-clave\">remisión</u></mark> del asunto <mark class=\"m-personalizado\">ante la Gran</mark> <mark class=\"m-autoridad\">Sala</mark>. 2. <mark class=\"m-resp\" data-q=\"1-145,1-ia-3514\">Un colegio de cinco Jueces de la Gran Sala</mark> <mark class=\"m-accion\">aceptará</mark> <mark class=\"m-personalizado\">la</mark> demanda <mark class=\"m-destacable\"><u class=\"m-clave\">si</u></mark> el asunto plantea una <mark class=\"m-destacable\">cuestión grave</mark> relativa <mark class=\"m-destacable\">a la interpretación o a la aplicación</mark> del <mark class=\"m-personalizado\">Convenio</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">o de sus Protocolos</span></span> o una <mark class=\"m-destacable\">cuestión grave de carácter general</mark>. <mark class=\"m-personalizado\">3. Si el <u class=\"m-clave\">colegio</u> acepta la demanda</mark>, <mark class=\"m-autoridad\">la Gran Sala</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">pronunciará</mark> acerca del asunto <mark class=\"m-personalizado\">mediante</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">sentencia</u></mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3515\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>Art. 44.</b> 1. <mark class=\"m-personalizado\">La sentencia de</mark> la Gran <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-accion\">será</mark> definitiva. 2. La <mark class=\"m-personalizado\">sentencia de</mark> <mark class=\"m-autoridad\">una Sala</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">definitiva cuando:</u></mark> a) <mark class=\"m-personalizado\">las partes declaren</mark> <mark class=\"m-destacable\">que no</mark> <mark class=\"m-accion\">solicitarán</mark> <mark class=\"m-personalizado\">la remisión</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">del asunto ante la Gran Sala</span></span>, o b) no <mark class=\"m-personalizado\">haya sido <u class=\"m-clave\">solicitada</u></mark> la remisión <span class=\"ex-plg\"><span class=\"ex-plg-t\">del asunto ante la Gran Sala</span></span> <mark class=\"m-plazo\">tres meses después</mark> de la fecha de la sentencia, o c) <mark class=\"m-personalizado\"><u class=\"m-clave\">el colegio</u> de la Gran</mark> <mark class=\"m-autoridad\">Sala</mark> <mark class=\"m-personalizado\">(5</mark> <mark class=\"m-autoridad\">jueces)</mark> <mark class=\"m-personalizado\">rechace</mark> la demanda de remisión <span class=\"ex-plg\"><span class=\"ex-plg-t\">formulada en aplicación del artículo 43</span></span>. 3. <mark class=\"m-personalizado\">La sentencia definitiva</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3517\">hecha pública</mark>.</p><p data-r=\"R18\"><span class=\"ex-sello ex-sello-r\">R18</span> <b>Art. 45.</b> 1. <mark class=\"m-personalizado\">Las sentencias, así como las resoluciones</mark> por las que las demandas se <mark class=\"m-personalizado\">declaren admisibles</mark> o no <mark class=\"m-personalizado\">admisibles</mark>, <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\"><mark class=\"m-resp r-ia\" data-q=\"1-ia-3519\">motivadas</mark></u></mark>. 2. <mark class=\"m-personalizado\">Si la sentencia no</mark> expresa en todo o en parte la <mark class=\"m-personalizado\"><u class=\"m-clave\">opinión</u> unánime</mark> de los <mark class=\"m-autoridad\">Jueces,</mark> <mark class=\"m-personalizado\">cualquier</mark> <mark class=\"m-autoridad\">Juez</mark> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">derecho a</mark> <mark class=\"m-resp\" data-q=\"1-105,1-ia-3518,1-ia-4185\">unir a ella su opinión por separado</mark>.</p><p data-ex=\"*\"><b>Art. 46.</b> 1. <mark class=\"m-autoridad\">Las Altas Partes Contratantes</mark> se <mark class=\"m-personalizado\">comprometen a acatar las <u class=\"m-clave\">sentencias definitivas</u></mark> del <mark class=\"m-autoridad\">Tribunal</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en los litigios en que sean partes</span></span>. 2. <mark class=\"m-personalizado\">La sentencia definitiva del</mark> <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">transmitida</u></mark> al <mark class=\"m-resp\" data-q=\"1-ia-3520,1-ia-3523,1-ia-3528,1-295\">Comité de Ministros, que velará por su ejecución</mark>. <mark class=\"m-personalizado\">3.</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">\u0007Cuando el Comité de Ministros considere que la supervisión de la ejecución de una sentencia definitiva resulta obstaculizada por un problema de interpretación de dicha sentencia, podrá remitir el asunto al Tribunal con objeto de que éste se pronuncie sobre dicho problema de interpretación.</span></span> La decisión de remisión <span class=\"m-caja\">al</span> <mark class=\"m-autoridad\">Tribunal</mark> (por un <mark class=\"m-personalizado\">problema de interpretación</mark>) <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">tomará</mark> por <mark class=\"m-destacable\">mayoría de dos tercios</mark> de los votos de los representantes que <mark class=\"m-personalizado\">tengan derecho a</mark> formar parte <mark class=\"m-personalizado\">del</mark> <mark class=\"m-autoridad\">Comité</mark>. (…) <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3521,1-ia-3522\">🎯 2 preguntas</mark></p>"],["Artículos 47 y 50 — Opiniones consultivas y gastos del Tribunal <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 47.</b> 1. El <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">podrá emitir</mark> <mark class=\"m-destacable\">opiniones consultivas</mark>, <mark class=\"m-destacable\"><u class=\"m-clave\">a solicitud</u></mark> del <mark class=\"m-autoridad\">Comité de Ministros,</mark> <mark class=\"m-destacable\">acerca</mark> <mark class=\"m-personalizado\">de cuestiones jurídicas <u class=\"m-clave\">relativas</u></mark> a la interpretación del Convenio y de sus Protocolos. 2. Estas opiniones <mark class=\"m-accion\">no podrán</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">referirse ni a las cuestiones que guarden relación con el contenido o la extensión de los derechos y libertades definidos en</span></span> el Título I <span class=\"ex-plg\"><span class=\"ex-plg-t\">del Convenio y sus Protocolos, ni <mark class=\"m-resp r-ia\" data-q=\"1-ia-3525\">a las demás cuestiones de las que el Tribunal o el Comité de Ministros pudieran conocer de resultas de la presentación de un recurso previsto por el Convenio</mark></span></span>. 3. <mark class=\"m-personalizado\">La resolución</mark> del <mark class=\"m-autoridad\">Comité de Ministros</mark> de solicitar una opinión al <mark class=\"m-autoridad\">Tribunal,</mark> <mark class=\"m-accion\">será</mark> adoptada por <mark class=\"m-resp\" data-q=\"1-ia-3310,1-ia-3524,1-ia-3526,1-296\">voto mayoritario de los representantes que tengan el derecho de intervenir en el Comité</mark>.</p><p data-ex=\"*\"><b>Art. 50.</b> <mark class=\"m-personalizado\">Los gastos</mark> de funcionamiento del <mark class=\"m-autoridad\">Tribunal</mark> <mark class=\"m-accion\">correrán</mark> <mark class=\"m-personalizado\">a cargo del</mark> <mark class=\"m-resp\" data-q=\"1-ia-3529,1-297\">Consejo de Europa</mark>.</p>"],["Artículos 55 y 57 — Renuncia a otros modos de solución de controversias y reservas <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 55.</b> <mark class=\"m-autoridad\">Las Altas Partes Contratantes</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">renuncian recíprocamente,</u> salvo compromiso especial,</mark> a prevalerse de los tratados, convenios o declaraciones que existan entre ellas, <mark class=\"m-personalizado\">a fin de someter, por vía de demanda,</mark> una diferencia surgida de la interpretación o de la aplicación del presente Convenio <mark class=\"m-personalizado\">a un procedimiento de solución distinto</mark> de los previstos en el presente Convenio. <mark class=\"m-resp ex-q\" data-q=\"1-298,1-ia-3534\">🎯 2 preguntas</mark></p><p data-ex=\"*\"><b>Art. 57.</b> <b>1.</b> <mark class=\"m-autoridad\">Todo Estado</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">formular,</mark> <mark class=\"m-plazo\">en el momento de la firma</mark> del presente Convenio o del depósito de su instrumento de ratificación, <mark class=\"m-personalizado\">una <u class=\"m-clave\">reserva</u> a propósito de un disposición particular del Convenio</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en la medida en que una ley en vigor en su territorio esté en desacuerdo con esta</span></span> disposición. Este artículo <mark class=\"m-personalizado\">no autoriza las reservas de <u class=\"m-clave\">carácter</u> <mark class=\"m-resp\" data-q=\"1-299\">general</mark>.</mark> <b>2.</b> <mark class=\"m-personalizado\">Toda reserva</mark> formulada de conformidad con el presente artículo <mark class=\"m-personalizado\">irá acompañada</mark> de una breve <mark class=\"m-personalizado\">exposición</mark> de la ley de que se trate. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3538\">🎯 1 pregunta</mark></p>"],["Artículos 56, 58 y 59 — Aplicación territorial, denuncia, firma y ratificación <span class=\"ex-sello\">EX</span>","<p><b>Art. <mark class=\"m-destacable\">56.</mark></b> 1. Cualquier <mark class=\"m-autoridad\">Estado</mark> puede (…) declarar, en <span class=\"ex-plg\"><span class=\"ex-plg-t\">notificación dirigida al <mark class=\"m-autoridad\">Secretario</mark> general del <mark class=\"m-autoridad\">Consejo</mark> <mark class=\"m-personalizado\">de Europa,</mark> que el presente <mark class=\"m-personalizado\">Convenio</mark> <mark class=\"m-accion\">se aplicará</mark> (…) a todos los <mark class=\"m-destacable\">territorios</mark> <mark class=\"m-plazo\">o</mark> a alguno de</span></span> <mark class=\"m-personalizado\">los territorios de cuyas relaciones internacionales es responsable.</mark> 2. <mark class=\"m-personalizado\">El Convenio se</mark> <mark class=\"m-accion\">aplicará</mark> <mark class=\"m-personalizado\">al territorio o territorios designados en la notificación</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3535,1-ia-3541,1-ia-4147,1-ia-4233\">a partir del trigésimo día siguiente a la fecha en la que el Secretario general del Consejo de Europa haya recibido esta notificación</mark>.</p><p><b>3.</b> En los mencionados territorios, las disposiciones del presente Convenio <mark class=\"m-accion\">se aplicarán</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3536\">teniendo en cuenta las necesidades locales</mark>.</p><p><b>4.</b> Todo <mark class=\"m-autoridad\">Estado</mark> que haya hecho <span class=\"ex-plg\"><span class=\"ex-plg-t\">una declaración de conformidad con el primer párrafo de este artículo,</span></span> <mark class=\"m-accion\">podrá,</mark> <mark class=\"m-plazo\">en cualquier momento sucesivo,</mark> <mark class=\"m-personalizado\">declarar que acepta con respecto a uno o varios de los territorios</mark> en cuestión, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3537,1-ia-3621\">la competencia del Tribunal para conocer de las demandas de personas físicas, de organizaciones no gubernamentales o de grupos de particulares</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\">tal como se prevé en el artículo 34 del Convenio.</span></span></p><p><b>Art. 58.</b> 1. Una Alta Parte Contratante sólo <mark class=\"m-accion\">podrá denunciar</mark> el presente Convenio, <mark class=\"m-resp r-ia\" data-q=\"1-ia-3255\">al término de un plazo de cinco años a partir de la fecha de entrada en vigor del Convenio para dicha Parte, y mediante un preaviso de seis meses</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">dado en una notificación dirigida al <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-personalizado\">general</mark> del <mark class=\"m-autoridad\">Consejo</mark> de Europa (…).</span></span>  <span class=\"ex-plg\"><span class=\"ex-plg-t\">3. (…) <mark class=\"m-accion\">dejará</mark> <mark class=\"m-personalizado\">de ser parte</mark> en el presente Convenio <mark class=\"m-autoridad\">toda Alta Parte</mark> Contratante que <mark class=\"m-personalizado\">deje de ser miembro del</mark> <mark class=\"m-autoridad\">Consejo de Europa.</mark></span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3540\">🎯 1 pregunta</mark></p><p data-ex=\"EX\"><b>Art. 59.</b> 1. El presente <mark class=\"m-personalizado\">Convenio</mark> está <mark class=\"m-personalizado\">abierto a la firma de los</mark> <mark class=\"m-autoridad\">Miembros del Consejo de Europa.</mark> <mark class=\"m-accion\">Será</mark> <mark class=\"m-personalizado\">ratificado.</mark> Las ratificaciones <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">depositadas ante</mark> <mark class=\"m-autoridad\">el Secretariado general del Consejo de Europa.</mark> 2. <mark class=\"m-resp\" data-q=\"1-97,1-ia-3542\">La Unión Europea podrá adherirse al presente Convenio</mark>. 3. El presente <mark class=\"m-personalizado\">Convenio</mark> <mark class=\"m-accion\">entrará</mark> <mark class=\"m-personalizado\">en vigor</mark> después del <mark class=\"m-personalizado\">depósito de diez instrumentos</mark> de ratificación. (…) <mark class=\"m-resp ex-q\" data-q=\"1-146,1-ia-3543\">🎯 2 preguntas</mark></p><p>Hecho en <mark class=\"m-resp r-ia\" data-q=\"1-ia-3625\">Roma el 4 de noviembre de 1950</mark>, <mark class=\"m-personalizado\">en francés e inglés</mark> (…).</p>"],["Artículos 1, 2, 4, 5, 6 y 7 — Términos, personalidad, locales, pabellón, inmunidad y archivos · R30 <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R30</span>","<p><b>d)</b> Por <mark class=\"m-autoridad\">«representantes de los Estados Partes» se</mark> <mark class=\"m-accion\">entenderán</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4028\">los delegados, delegados suplentes, asesores, peritos técnicos y secretarios de delegaciones</mark>;</p><p data-ex=\"EX\"><b>f)</b> Por <mark class=\"m-autoridad\">«Magistrados»</mark> <mark class=\"m-accion\">se entenderán</mark> los <mark class=\"m-autoridad\">magistrados</mark> <mark class=\"m-personalizado\">de la</mark> <mark class=\"m-autoridad\">Corte;</mark></p><p><b><mark class=\"m-personalizado\">g)</mark></b> <mark class=\"m-personalizado\">Por «la</mark> <mark class=\"m-autoridad\">Presidencia»</mark> <mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">entenderá</mark> el <mark class=\"m-autoridad\">órgano</mark> integrado por <mark class=\"m-resp r-ia\" data-q=\"1-ia-4029\">el Presidente y los Vicepresidentes primero y segundo de la Corte</mark>;</p><p><b>o)</b> Por <mark class=\"m-personalizado\">«la Convención de Viena»</mark> <mark class=\"m-accion\">se entenderá</mark> <mark class=\"m-personalizado\">la Convención</mark> de Viena sobre <mark class=\"m-personalizado\">Relaciones Diplomáticas,</mark> de <mark class=\"m-resp r-ia\" data-q=\"1-ia-4032\">18 de abril de 1961</mark>;</p><p data-ex=\"*\" data-r=\"R30\"><span class=\"ex-sello ex-sello-r\">R30</span> <b>Art. 2.</b> <mark class=\"m-destacable\">La</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3344,1-ia-4027,1-ia-4226\">personalidad jurídica internacional y tendrá también la capacidad jurídica que sea necesaria para el desempeño de sus funciones</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">y</u></mark> el cumplimiento de <mark class=\"m-personalizado\">sus propósitos.</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Tendrá en particular capacidad jurídica para</span></span> celebrar <mark class=\"m-destacable\">contratos, adquirir bienes</mark> <mark class=\"m-personalizado\">muebles e inmuebles y</mark> <mark class=\"m-destacable\">disponer de ellos y participar en procedimientos judiciales.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-198\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>Art. 4.</b> <mark class=\"m-destacable\">Los locales de la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-resp\" data-q=\"1-110,1-ia-4035\">inviolables</mark>.</p><p><b>Art. 5.</b> <mark class=\"m-destacable\">La</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">tendrá</mark> <mark class=\"m-personalizado\">derecho a enarbolar su pabellón y a exhibir su emblema</mark> y sus señales <mark class=\"m-resp r-ia\" data-q=\"1-ia-4036\">en sus locales y en los vehículos y otros medios de transporte que utilice con fines oficiales</mark>.</p><p data-ex=\"*\"><b>Art. <mark class=\"m-destacable\">6.</mark></b> <mark class=\"m-destacable\">1. La</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-destacable\">y sus bienes, haberes y fondos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, dondequiera y en poder de quienquiera que se hallen,</span></span> <mark class=\"m-accion\">gozarán</mark> <mark class=\"m-personalizado\">de inmunidad de jurisdicción</mark> en todas sus formas, <mark class=\"m-personalizado\">salvo en la medida en que la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">renuncie</mark> expresamente a ella en un caso determinado. <mark class=\"m-accion\">Se entenderá,</mark> sin embargo, que <mark class=\"m-personalizado\">la renuncia</mark> <mark class=\"m-resp\" data-q=\"1-160,1-ia-4037\">no será extensible a ninguna medida de ejecución</mark>. 2. <span class=\"ex-plg\"><span class=\"ex-plg-t\">\u0007Los bienes, haberes y fondos de la Corte, dondequiera y en poder de quienquiera que se hallen,</span></span> <mark class=\"m-accion\">gozarán</mark> de inmunidad <mark class=\"m-personalizado\">de allanamiento, incautación, requisa, decomiso y expropiación</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">y cualquier otra forma de interferencia, ya sea de carácter ejecutivo, administrativo, judicial o legislativo</span></span>.</p><p><span class=\"ex-plg\"><span class=\"ex-plg-t\"><b>Art. <mark class=\"m-destacable\">6.</mark></b> <mark class=\"m-destacable\">1. La</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-destacable\">y sus bienes, haberes y fondos,</mark> dondequiera y <mark class=\"m-personalizado\">en poder de quienquiera que se hallen,</mark> <mark class=\"m-accion\">gozarán</mark> <mark class=\"m-personalizado\">de inmunidad de jurisdicción</mark> en todas sus formas, <mark class=\"m-personalizado\">salvo</mark> en la medida en que <mark class=\"m-personalizado\">la</mark> <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">renuncie</mark> expresamente a ella en un caso determinado.</span></span> <mark class=\"m-accion\">Se entenderá,</mark> sin embargo, que <mark class=\"m-personalizado\">la renuncia</mark> <mark class=\"m-resp\" data-q=\"1-160\">no será extensible a ninguna medida de ejecución</mark>.</p><p><b>2.</b> Los bienes, haberes y fondos <span class=\"ex-plg\"><span class=\"ex-plg-t\">de la <mark class=\"m-autoridad\">Corte,</mark> dondequiera y en poder de quienquiera que se hallen, <mark class=\"m-accion\">gozarán</mark> <mark class=\"m-personalizado\">de inmunidad de allanamiento, incautación, requisa, decomiso y expropiación y cualquier</mark> otra forma de interferencia, ya <mark class=\"m-personalizado\">sea de carácter <mark class=\"m-resp r-ia\" data-q=\"1-ia-4038\">ejecutivo, administrativo, judicial o legislativo</mark>.</mark></span></span></p><p><b>3.</b> <mark class=\"m-personalizado\">En la medida en que sea necesario</mark> para el desempeño de <span class=\"ex-plg\"><span class=\"ex-plg-t\">las <mark class=\"m-personalizado\">funciones</mark> de la <mark class=\"m-autoridad\">Corte,</mark> los bienes, haberes y fondos de la <mark class=\"m-autoridad\">Corte,</mark> dondequiera y en poder de quienquiera</span></span> que se hallen, <mark class=\"m-accion\">estarán</mark> <mark class=\"m-personalizado\">exentos de</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4039\">restricciones, reglamentaciones, controles o moratorias de toda índole</mark>.</p><p><b>Art. 7.</b> <mark class=\"m-personalizado\">Los archivos</mark> de la <mark class=\"m-autoridad\">Corte</mark> y, <span class=\"ex-plg\"><span class=\"ex-plg-t\">en general, todos los <mark class=\"m-personalizado\">papeles y documentos, cualquiera sea su forma</mark>, y todos los materiales <mark class=\"m-personalizado\">que se envíen</mark> a la <mark class=\"m-autoridad\">Corte</mark> o <mark class=\"m-personalizado\">que ésta envíe,</mark> estén <mark class=\"m-personalizado\">en poder</mark> de la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\">o le pertenezcan</mark>,</span></span> <mark class=\"m-personalizado\">dondequiera y en poder de quienquiera</mark> que se hallen, <mark class=\"m-accion\">serán</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4040\">inviolables</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">La terminación o ausencia de <mark class=\"m-personalizado\">esa</mark> inviolabilidad <mark class=\"m-accion\">no afectará</mark> a las medidas de protección que la <mark class=\"m-autoridad\">Corte</mark> ordene de conformidad con el Estatuto y las Reglas de Procedimiento y Prueba con respecto a documentos y materiales que la <mark class=\"m-autoridad\">Corte</mark> utilice o le sean facilitados.</span></span></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 2 — Condición jurídica y personalidad jurídica <mark class=\"m-autoridad\">de la corte</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4033\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 3 — Disposiciones generales acerca de los privilegios e inmunidades de la Corte <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 3.</b> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">gozará</mark> <mark class=\"m-personalizado\">en el territorio de</mark> <mark class=\"m-autoridad\">cada Estado Parte</mark> <mark class=\"m-personalizado\">de los privilegios e inmunidades</mark> que sean <mark class=\"m-personalizado\">necesarios para el cumplimiento de sus <mark class=\"m-resp\" data-q=\"1-300\">propósitos</mark>.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4034\">🎯 1 pregunta</mark></p>"],["Artículos 8 y 10 — Impuestos y fondos (disposiciones monetarias) · R31 <span class=\"ex-sello\">EXOF</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R31</span>","<p data-ex=\"*\" data-r=\"R31\"><span class=\"ex-sello ex-sello-r\">R31</span> <b>Art. 8.</b> 1. <mark class=\"m-plazo\">La</mark> <mark class=\"m-autoridad\">Corte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">1. \u0007La Corte, sus haberes, ingresos y otros bienes, así como sus operaciones y transacciones,</span></span> <mark class=\"m-accion\">estarán</mark> <mark class=\"m-destacable\">exentos de</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">todos</u> los impuestos</mark> directos <span class=\"ex-plg\"><span class=\"ex-plg-t\">, que incluyen, entre otros, el impuesto sobre la renta, el impuesto sobre el capital y el impuesto a las sociedades, así como los impuestos directos que perciban las auto- ridades locales o provinciales</span></span>. <mark class=\"m-accion\">Se entenderá,</mark> <mark class=\"m-personalizado\">sin embargo</mark>, que la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">no</u></mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">reclamar la exención del pago de los <u class=\"m-clave\">gravámenes</u> que constituyan de hecho</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4041,1-ia-4227\">la remuneración de servicios públicos prestados a una tarifa fija</mark> <mark class=\"m-personalizado\">según</mark> <mark class=\"m-destacable\">la cantidad</mark> <mark class=\"m-personalizado\">de servicios</mark> prestados <span class=\"ex-plg\"><span class=\"ex-plg-t\">y que se puedan identificar, describir y desglosar. R31</span></span>. 2. La <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">exenta</u></mark> <mark class=\"m-personalizado\">de derechos de aduana</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, impuestos sobre el volumen de las importaciones y prohibiciones o restricciones</span></span> respecto de los artículos que importe o exporte <mark class=\"m-personalizado\">para</mark> su uso oficial <mark class=\"m-destacable\">y respecto de sus publicaciones</mark>. <mark class=\"m-resp ex-q\" data-q=\"1-199\">🎯 1 pregunta</mark></p><p data-ex=\"EXOF,*\"><b><mark class=\"m-destacable\">Art.</mark> 10.</b> 1. <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">no quedará</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">sometida</u> a controles financieros</mark>, <mark class=\"m-personalizado\">reglamentos o moratorias</mark> financieros de índole alguna <mark class=\"m-personalizado\">en el desempeño de sus funciones</mark> y <mark class=\"m-accion\">podrá</mark>: a) <mark class=\"m-destacable\">tener</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">fondos, moneda</u> de cualquier tipo u oro y <mark class=\"m-resp r-ia\" data-q=\"1-ia-4046\">operar cuentas en cualquier moneda</mark>;</mark> <mark class=\"m-destacable\">b) <u class=\"m-clave\">transferir</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">libremente</mark></span> <mark class=\"m-personalizado\">sus fondos, oro o moneda</mark> de un país a otro o dentro de un país <mark class=\"m-personalizado\">y</mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">convertir</mark></span> <mark class=\"m-personalizado\">a cualesquiera <u class=\"m-clave\">otras las monedas</u></mark> que tenga en su poder; c) <span class=\"m-circulo\"><mark class=\"m-personalizado\">recibir</mark></span>, <mark class=\"m-personalizado\"><u class=\"m-clave\">tener,</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">negociar</mark></span>, <span class=\"m-circulo\"><mark class=\"m-personalizado\">transferir o</mark></span> <mark class=\"m-personalizado\">convertir bonos u otros títulos</mark> financieros o realizar cualquier transacción con ellos; d) <mark class=\"m-destacable\"><u class=\"m-clave\">las</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">transacciones</u> financieras</mark> <mark class=\"m-autoridad\">de la Corte</mark> <mark class=\"m-accion\">gozarán,</mark> en cuanto al tipo de cambio, <mark class=\"m-personalizado\">de un</mark> <mark class=\"m-resp\" data-q=\"1-87,1-ia-4047\">trato no menos favorable</mark> que el que otorgue el <mark class=\"m-autoridad\">Estado Parte</mark> de que se trate <mark class=\"m-personalizado\">a cualquier</mark> <mark class=\"m-autoridad\">organización</mark> intergubernamental o <mark class=\"m-autoridad\">misión diplomática.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-161\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 8 — <mark class=\"m-personalizado\">Exención de</mark> impuestos, <mark class=\"m-personalizado\">derechos</mark> de aduana y <u class=\"m-clave\">restricciones de</u> <mark class=\"m-personalizado\">importación o exportación</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4042,1-ia-4043\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 9 — Reembolso de derechos y/o impuestos <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 9.</b> 1. <mark class=\"m-autoridad\"><u class=\"m-clave\">La Corte, por regla</u></mark> <mark class=\"m-personalizado\">general, no</mark> <mark class=\"m-accion\">reclamará</mark> <mark class=\"m-personalizado\">la exención de los derechos y/o impuestos incluidos en el <u class=\"m-clave\">precio</u> de bienes muebles o inmuebles</mark> ni de los derechos pagados <mark class=\"m-personalizado\">por servicios prestados. Sin embargo, cuando la</mark> <mark class=\"m-autoridad\">Corte</mark> efectúe <mark class=\"m-personalizado\">compras importantes</mark> de bienes y artículos o servicios destinados a <mark class=\"m-personalizado\">uso oficial y</mark> gravados o gravables con derechos y/o impuestos identificables, <mark class=\"m-autoridad\">los Estados Partes</mark> <mark class=\"m-resp\" data-q=\"1-ia-4044,1-ia-4113,1-301\">tomarán las disposiciones administrativas del caso para eximirla de esos gravámenes o reembolsarle el monto del derecho y/o impuesto pagado</mark>.</p><p><b>2.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\">Los artículos que se adquieran o reembolsen en <mark class=\"m-personalizado\">franquicia no</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">vendidos ni se</mark> <mark class=\"m-accion\">dispondrá</mark> de ellos de otra manera <mark class=\"m-personalizado\">salvo en las condiciones establecidas por el</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte</mark> que haya concedido la exención o hecho el reembolso.</span></span> <mark class=\"m-accion\">No se concederán</mark> exenciones ni reembolsos <mark class=\"m-resp r-ia\" data-q=\"1-ia-4045\">por concepto de las tarifas de servicios públicos suministrados a la Corte</mark>.</p>"],["Artículos 11, 12 y 13 — Comunicaciones, sede y representantes en la Asamblea <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b><mark class=\"m-autoridad\">Art.</mark> 11.</b> 1. <span class=\"ex-plg\"><span class=\"ex-plg-t\">d) \u0007Las transacciones financieras de</span></span> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-accion\">gozará</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en el territorio de cada Estado Parte</span></span> de <mark class=\"m-autoridad\">un trato no</mark> menos favorable que el que éste <mark class=\"m-personalizado\">conceda</mark> a cualquier organización intergubernamental o misión diplomática <span class=\"ex-plg\"><span class=\"ex-plg-t\">en materia de prioridades, tarifas o impuestos aplicables al franqueo postal y a las diversas formas de comunicación y correspondencia</span></span>. 2. La correspondencia o las comunicaciones oficiales <mark class=\"m-personalizado\">de</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-resp\" data-q=\"1-106,1-ia-4049\">no serán sometidas a censura alguna</mark>. <mark class=\"m-destacable\">3.</mark> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">utilizar todos los medios apropiados</mark> <mark class=\"m-destacable\">de comunicación</mark>, <mark class=\"m-destacable\">incluidos los electrónicos</mark>, <mark class=\"m-destacable\">y emplear claves o cifras</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">para su correspondencia o comunicaciones oficiales</span></span>. <mark class=\"m-destacable\">La</mark> <mark class=\"m-personalizado\">correspondencia y las comunicaciones</mark> oficiales de la <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">serán</mark> inviolables. 4. <span class=\"ex-plg\"><span class=\"ex-plg-t\">L\u0007 a Corte podrá despachar y recibir correspondencia y otras piezas o comunicaciones</span></span> <mark class=\"m-personalizado\">por correo o valija</mark> sellada <span class=\"ex-plg\"><span class=\"ex-plg-t\">, los cuales gozarán de los mismos privilegios, inmunidades y facilidades que se reconocen a las valijas y los correos y diplomáticos</span></span>.</p><p><b>Art. 11.</b> 1. A los efectos de su correspondencia <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-destacable\">y comunicaciones oficiales,</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-accion\">gozará</mark> <mark class=\"m-personalizado\">en el territorio de cada</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte</mark> <mark class=\"m-destacable\">de</mark> un trato no menos favorable</span></span> que el <mark class=\"m-destacable\">que</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">éste conceda</u> a cualquier organización intergubernamental o misión diplomática en materia</mark> de <mark class=\"m-resp r-ia\" data-q=\"1-ia-3432,1-ia-4201\">prioridades, tarifas o impuestos aplicables al franqueo postal y a las diversas formas de comunicación y correspondencia</mark>.</p><p><b><mark class=\"m-personalizado\"><u class=\"m-clave\">2.</u></mark></b> <mark class=\"m-personalizado\"><u class=\"m-clave\">La</u></mark> <span class=\"m-circulo\"><mark class=\"m-personalizado\">correspondencia o</mark></span> <mark class=\"m-destacable\"><u class=\"m-clave\">las</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">comunicaciones</u> oficiales</mark> <mark class=\"m-autoridad\">de la Corte</mark> <mark class=\"m-accion\">no serán</mark> <mark class=\"m-autoridad\">sometidas</mark> <mark class=\"m-personalizado\">a</mark> <mark class=\"m-resp\" data-q=\"1-106\">censura alguna</mark>.</p><p><b>3.</b> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá utilizar</mark> <mark class=\"m-personalizado\">todos</mark> <mark class=\"m-autoridad\">los</mark> medios apropiados <mark class=\"m-personalizado\">de</mark> <mark class=\"m-destacable\">comunicación,</mark> incluidos los electrónicos, y emplear claves o cifras para su correspondencia o comunicaciones oficiales.</span></span> La correspondencia y las comunicaciones oficiales <mark class=\"m-personalizado\">de</mark> <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-resp\" data-q=\"1-110\">inviolables</mark>.</p><p><b>4.</b> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">despachar</mark> <mark class=\"m-destacable\">y recibir</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">correspondencia y otras piezas o comunicaciones por correo o valija sellada,</mark> los cuales <mark class=\"m-accion\">gozarán</mark> <mark class=\"m-personalizado\">de los <u class=\"m-clave\">mismos</u> privilegios, inmunidades y facilidades</mark> que <mark class=\"m-accion\">se reconocen</mark> a las valijas <mark class=\"m-destacable\">y los correos</mark> y diplomáticos.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4050\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b><mark class=\"m-destacable\">5.</mark></b> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">operar equipos de</mark> <mark class=\"m-destacable\">radio</mark> <mark class=\"m-personalizado\">y otro equipo de telecomunicaciones en las frecuencias que <u class=\"m-clave\">le</u> asignen</mark> <mark class=\"m-autoridad\">los Estados Partes,</mark> de <mark class=\"m-personalizado\">conformidad con sus procedimientos nacionales.</mark> <mark class=\"m-autoridad\">Los Estados Partes</mark> <mark class=\"m-resp\" data-q=\"1-ia-4051,1-302\">se esforzarán por asignar a la Corte, en la mayor medida posible, las frecuencias que haya solicitado</mark>.</p><p data-ex=\"*\"><b>Art. 13.</b> 1. Los <mark class=\"m-destacable\">representantes de</mark> <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-personalizado\">en el Estatuto que asistan a reuniones de la</mark> <mark class=\"m-autoridad\">Asamblea</mark> <mark class=\"m-personalizado\">o sus</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">subsidiarios, los representantes de otros</mark> <mark class=\"m-autoridad\">Estados</mark> que asistan a reuniones de la <mark class=\"m-autoridad\">Asamblea</mark> y sus <mark class=\"m-autoridad\">órganos</mark> subsidiarios <mark class=\"m-personalizado\">en</mark> calidad <mark class=\"m-personalizado\">de observadores</mark> de conformidad con el <mark class=\"m-destacable\">párrafo</mark> 1 del artículo 112 del Estatuto de Roma, y los representantes de los <mark class=\"m-autoridad\">Estados</mark> y de las organizaciones intergubernamentales invitados a reuniones de la <mark class=\"m-autoridad\">Asamblea</mark> y sus <mark class=\"m-autoridad\">órganos</mark> subsidiarios, <mark class=\"m-accion\">tendrán,</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">mientras se encuentren en ejercicio de sus funciones oficiales y durante el trayecto</span></span> al lugar de <mark class=\"m-destacable\">reunión</mark> y a <mark class=\"m-destacable\">su regreso,</mark> los privilegios e inmunidades siguientes: <mark class=\"m-resp ex-q\" data-q=\"1-303\">🎯 1 pregunta</mark></p><p><b>b)</b> <mark class=\"m-personalizado\"><u class=\"m-clave\">Inmunidad</u></mark> de <span class=\"m-circulo\"><mark class=\"m-personalizado\">jurisdicción</mark></span> <mark class=\"m-personalizado\">de toda índole respecto de las <u class=\"m-clave\">declaraciones</u> que hagan verbalmente o por escrito y</mark> <span class=\"m-circulo\"><mark class=\"m-destacable\">los</mark></span> <mark class=\"m-personalizado\"><u class=\"m-clave\">actos</u></mark> que realicen a <mark class=\"m-personalizado\">título oficial, la cual</mark> <mark class=\"m-accion\">subsistirá</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4053\">incluso después de que hayan cesado en el ejercicio de sus funciones como representantes</mark>;</p><p><b>g)</b> Las <mark class=\"m-personalizado\">mismas inmunidades y facilidades</mark> respecto de <span class=\"ex-plg\"><span class=\"ex-plg-t\">su <mark class=\"m-destacable\">equipaje personal</mark> <mark class=\"m-personalizado\">que</mark> se reconozcan a los <mark class=\"m-personalizado\">agentes diplomáticos</mark> con arreglo a la Convención de Viena;</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4054\">🎯 1 pregunta</mark></p><p><b>i)</b> <mark class=\"m-personalizado\">Los demás privilegios,</mark> inmunidades y facilidades compatibles <span class=\"ex-plg\"><span class=\"ex-plg-t\">con los que anteceden de que gocen los <mark class=\"m-destacable\">agentes</mark> <mark class=\"m-personalizado\">diplomáticos, con la salvedad</mark></span></span> de que <u class=\"m-clave\">no</u> <span class=\"m-caja\"><mark class=\"m-accion\">podrán</mark></span> <span class=\"m-caja\">reclamar</span> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4101,1-ia-4111\">la exención de derechos aduaneros sobre mercaderías importadas (que no sean parte de su equipaje personal) o de impuestos sobre la compraventa o el consumo</mark>.</p><p><b><mark class=\"m-personalizado\">2.</mark></b> <mark class=\"m-personalizado\">Cuando la aplicación</mark> de cualquier forma <span class=\"ex-plg\"><span class=\"ex-plg-t\">de impuesto <mark class=\"m-personalizado\">dependa de la residencia, los periodos en</mark> que los representantes descritos en el párrafo 1 <mark class=\"m-personalizado\">que asistan a reuniones</mark> de la <mark class=\"m-autoridad\">Asamblea</mark> y sus <mark class=\"m-autoridad\">órganos</mark> subsidiarios permanezcan en un <mark class=\"m-autoridad\">Estado</mark> Parte en <mark class=\"m-personalizado\">ejercicio de sus funciones</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">no</u></mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">se</u></mark> <mark class=\"m-accion\">considerarán</mark> <mark class=\"m-personalizado\"><u class=\"m-clave\">periodos de</u> residencia.</mark></span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4102\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-personalizado\">Lo dispuesto en los párrafos 1 y 2 del presente artículo</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3309,1-ia-4103\">no será aplicable entre un representante y las autoridades del Estado Parte del que sea nacional o del Estado Parte o la organización intergubernamental del que sea o haya sido representante</mark>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 14 — <mark class=\"m-destacable\">Representantes de</mark> <mark class=\"m-autoridad\">estados</mark> que <mark class=\"m-personalizado\">participen</mark> en las <mark class=\"m-personalizado\">actuaciones</mark> <mark class=\"m-autoridad\">de la corte</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4104\">🎯 1 pregunta más de este artículo</mark>"],["Artículo 15 — Magistrados, Fiscal, Fiscales Adjuntos y Secretario · R32 <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R32</span>","<p data-ex=\"*\"><b>Art. 15.</b> <mark class=\"m-destacable\">1.</mark> <mark class=\"m-autoridad\">Los Magistrados, el Fiscal, los Fiscales Adjuntos y el Secretario</mark> <mark class=\"m-accion\">gozarán,</mark> <span class=\"m-caja\">cuando</span> actúen en <mark class=\"m-personalizado\">el desempeño de sus funciones para</mark> <mark class=\"m-autoridad\">la Corte</mark> o en relación con ellas, de los <mark class=\"m-personalizado\"><u class=\"m-clave\">mismos privilegios</u> e inmunidades</mark> reconocidos <mark class=\"m-personalizado\">a</mark> <mark class=\"m-resp\" data-q=\"1-162,1-ia-4105\">los jefes de las misiones diplomáticas</mark> <mark class=\"m-autoridad\">y,</mark> una vez <mark class=\"m-personalizado\">expirado su mandato,</mark> <mark class=\"m-accion\">seguirán</mark> gozando <mark class=\"m-resp r-vec\" data-q=\"1-162,1-ia-4105\">de inmunidad de jurisdicción por las declaraciones que hayan hecho verbalmente o por escrito y los actos que hayan realizado en el desempeño de sus funciones oficiales</mark>.</p><p><b>2.</b> <mark class=\"m-autoridad\">Los Magistrados, el Fiscal, los Fiscales Adjuntos y el Secretario</mark> <mark class=\"m-destacable\">y</mark> <mark class=\"m-autoridad\">los familiares</mark> que formen <span class=\"ex-plg\"><span class=\"ex-plg-t\">parte de sus <mark class=\"m-personalizado\">hogares</mark> <mark class=\"m-accion\">recibirán</mark> todas <mark class=\"m-personalizado\">las facilidades para salir del país</mark> en que se encuentren <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> <mark class=\"m-personalizado\">para <u class=\"m-clave\">entrar</u> y salir del país en que sesione</mark> la <mark class=\"m-autoridad\">Corte.</mark> En el curso de <mark class=\"m-personalizado\">los viajes que</mark> hagan en el ejercicio de <mark class=\"m-personalizado\"><u class=\"m-clave\">sus funciones</u></mark> los <mark class=\"m-autoridad\">Magistrados, el Fiscal, los Fiscales</mark> Adjuntos y el <mark class=\"m-autoridad\">Secretario</mark> <mark class=\"m-accion\">gozarán,</mark> en <mark class=\"m-autoridad\">todos los Estados Partes</mark> por los que tengan que transitar, de los <mark class=\"m-personalizado\">privilegios, las inmunidades y</mark> las facilidades que los</span></span> <mark class=\"m-autoridad\">Estados Partes</mark> en circunstancias similares concedan <mark class=\"m-resp r-ia\" data-q=\"1-ia-4054\">a los agentes diplomáticos de conformidad con la Convención de Viena</mark>. <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-3628\">🎯 1 pregunta</mark></p><p><b>3.</b> <mark class=\"m-autoridad\">El Magistrado, el Fiscal, un Fiscal Adjunto o el Secretario</mark> <mark class=\"m-personalizado\">que, para</mark> mantenerse a <mark class=\"m-personalizado\">disposición</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de la <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-personalizado\">esté residiendo en un</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte distinto del de su nacionalidad o residencia permanente</mark> <mark class=\"m-accion\">gozará,</mark> junto con los familiares que</span></span> formen parte de sus hogares, <mark class=\"m-resp r-ia\" data-q=\"1-ia-4106,1-ia-4107\">de los privilegios, inmunidades y facilidades de los agentes diplomáticos mientras resida en ese Estado</mark>.</p><p data-ex=\"*\"><b>5.</b> <mark class=\"m-personalizado\">Los párrafos 1 a 4 del</mark> presente artículo <mark class=\"m-accion\">serán</mark> aplicables <mark class=\"m-autoridad\">a los Magistrados de la Corte</mark> <mark class=\"m-personalizado\">incluso después de terminado su mandato si</mark> <mark class=\"m-resp\" data-q=\"1-ia-4108,1-304\">siguen ejerciendo sus funciones de conformidad con el párrafo 10 del artículo 36 del Estatuto</mark>.</p><p data-r=\"R32\"><span class=\"ex-sello ex-sello-r\">R32</span> <b>6.</b> <mark class=\"m-destacable\">Los sueldos,</mark> <span class=\"m-caja\"><mark class=\"m-destacable\">los</mark></span> <mark class=\"m-destacable\">emolumentos</mark> <span class=\"m-caja\"><mark class=\"m-destacable\">y las prestaciones</mark></span> <mark class=\"m-personalizado\">que perciban</mark> <mark class=\"m-autoridad\">los Magistrados, el Fiscal, los Fiscales Adjuntos y el Secretario de la Corte</mark> <mark class=\"m-accion\">estarán</mark> <mark class=\"m-resp\" data-q=\"1-200,1-ia-4109\">exentos de impuestos</mark><span class=\"ex-plg\"><span class=\"ex-plg-t\">. Cuando la aplicación de un impuesto de cualquier índole dependa de la residencia, los períodos durante</span></span> los cuales los <mark class=\"m-autoridad\">Magistrados, el Fiscal, los Fiscales</mark> Adjuntos y el <mark class=\"m-autoridad\">Secretario</mark> se encuentren en un <mark class=\"m-autoridad\">Estado</mark> Parte a fin de desempeñar sus funciones <mark class=\"m-accion\">no serán</mark> considerados períodos de residencia a efectos tributarios. Los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-accion\">podrán</mark> <mark class=\"m-personalizado\">tener en cuenta esos sueldos,</mark> emolumentos y prestaciones a los <mark class=\"m-personalizado\">efectos de determinar</mark> la cuantía de <mark class=\"m-personalizado\">los impuestos</mark> que se han de <mark class=\"m-personalizado\">aplicar a los ingresos de otras fuentes.</mark></p><p data-ex=\"*\"><b>7.</b> Los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-resp\" data-q=\"1-305\">no estarán obligados a exonerar del impuesto a la renta</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4110\">a las pensiones <mark class=\"m-destacable\">o rentas</mark> vitalicias pagadas a los ex <mark class=\"m-autoridad\">Magistrados, Fiscales</mark> o Secretarios y a las personas <mark class=\"m-autoridad\">a su</mark> cargo</mark>.</p>"],["Artículo 16 — Secretario Adjunto, personal de la Fiscalía y personal de la Secretaría <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 16.</b> <b>2.</b> Los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-personalizado\">no</mark> <mark class=\"m-accion\">estarán</mark> obligados a eximir <mark class=\"m-personalizado\">del impuesto sobre</mark> la renta <mark class=\"m-personalizado\">a las pensiones</mark> <mark class=\"m-destacable\">o rentas</mark> vitalicias abonadas <mark class=\"m-autoridad\">a</mark> ex secretarios adjuntos, miembros del personal de la <mark class=\"m-autoridad\">Fiscalía,</mark> miembros del personal de la <mark class=\"m-autoridad\">Secretaría</mark> <mark class=\"m-personalizado\">y</mark> personas a <mark class=\"m-personalizado\">su cargo.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-306,1-ia-4114\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 17 — <mark class=\"m-destacable\">Personal contratado localmente</mark> y <u class=\"m-clave\">que no</u> esté de otro modo contemplado en el <mark class=\"m-personalizado\">presente</mark> <mark class=\"m-personalizado\">acuerdo</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4115\">🎯 1 pregunta más de este artículo</mark>"],["Artículos 18, 20 y 22 — Abogados, víctimas y otras personas <span class=\"ex-sello\">✱</span>","<p><b>Art. 18.</b> 1. <mark class=\"m-autoridad\">Los abogados</mark> <mark class=\"m-accion\">gozarán</mark> de <span class=\"ex-plg\"><span class=\"ex-plg-t\">los siguientes <mark class=\"m-personalizado\">privilegios, inmunidades y facilidades</mark> en la medida en que sea <mark class=\"m-personalizado\"><u class=\"m-clave\">necesario</u> para el ejercicio independiente de sus funciones, incluso el tiempo</mark> empleado <mark class=\"m-personalizado\">en viajes,</mark> en relación con el ejercicio de <mark class=\"m-personalizado\">sus funciones y siempre que exhiban el certificado</mark> a que se hace referencia en el párrafo 2 del presente artículo:</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4116\">🎯 1 pregunta</mark></p><p><b>f)</b> <mark class=\"m-personalizado\">Exención de la inspección del equipaje personal, a menos que haya fundadas razones</mark> para creer que el <span class=\"ex-plg\"><span class=\"ex-plg-t\">equipaje contiene artículos cuya <mark class=\"m-personalizado\">importación o exportación está prohibida</mark> por la ley o sometida a <mark class=\"m-personalizado\">control</mark> por las normas de <mark class=\"m-personalizado\">cuarentena</mark> del <mark class=\"m-autoridad\">Estado</mark> Parte de que se trate, en cuyo</span></span> caso <mark class=\"m-accion\">se hará</mark> una <mark class=\"m-personalizado\">inspección</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4112\">en presencia del abogado</mark>;</p><p><b>2.</b> Una <mark class=\"m-personalizado\">vez designado</mark> <mark class=\"m-autoridad\">un abogado</mark> de conformidad <span class=\"ex-plg\"><span class=\"ex-plg-t\">con el Estatuto, las Reglas de Procedimiento y Prueba y el Reglamento de la</span></span> <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-personalizado\">se le</mark> <mark class=\"m-accion\">extenderá</mark> <mark class=\"m-destacable\">un certificado,</mark> <mark class=\"m-personalizado\">firmado por</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-3742\">el Secretario</mark>, <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">por el período necesario</mark> para el ejercicio de sus funciones.</span></span>  El certificado <mark class=\"m-resp r-ia\" data-q=\"1-ia-4117\">se retirará si se pone término al poder o al mandato antes de que expire el certificado</mark>.</p><p><b>4.</b> <mark class=\"m-personalizado\">Lo dispuesto</mark> en el presente artículo <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">se</mark> <mark class=\"m-accion\">aplicará,</mark> mutatis mutandis, <mark class=\"m-personalizado\">a las personas que asistan a</mark> los</span></span> <mark class=\"m-autoridad\">abogados</mark> defensores de conformidad con <mark class=\"m-resp r-ia\" data-q=\"1-ia-4118\">la regla 22 de las Reglas de Procedimiento y Prueba</mark>.</p><p data-ex=\"*\"><b>Art. 20.</b> 1. <mark class=\"m-personalizado\">Se</mark> <mark class=\"m-accion\">reconocerá</mark> <mark class=\"m-personalizado\">a las víctimas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">que participen en las actuaciones judiciales de conformidad con las reglas 89 a 91 de las Reglas de</span></span> Procedimiento y Prueba, <mark class=\"m-personalizado\">en la medida en que sea necesario para su comparecencia</mark> ante la <mark class=\"m-autoridad\">Corte,</mark> los siguientes <mark class=\"m-personalizado\">privilegios, inmunidades y facilidades, incluso durante el tiempo</mark> empleado en <mark class=\"m-personalizado\">viajes</mark> relacionados con su comparecencia ante la <mark class=\"m-autoridad\">Corte,</mark> <mark class=\"m-personalizado\">siempre que exhiban el documento a</mark> que se hace referencia en el párrafo 2 del presente artículo: <mark class=\"m-resp ex-q\" data-q=\"1-307,1-ia-4126\">🎯 2 preguntas</mark></p><p><b>d)</b> <mark class=\"m-personalizado\">Exención de las restricciones</mark> en materia de <span class=\"ex-plg\"><span class=\"ex-plg-t\"><mark class=\"m-personalizado\">inmigración</mark> <mark class=\"m-destacable\"><u class=\"m-clave\">y</u></mark> las formalidades de <mark class=\"m-personalizado\">registro de extranjeros</mark> cuando viajen a la <mark class=\"m-autoridad\">Corte</mark> y desde ella por razón de su comparecencia.</span></span>  <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4122\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-autoridad\">La Corte</mark> <mark class=\"m-accion\">extenderá</mark> <mark class=\"m-personalizado\">a nombre de las víctimas</mark> que participen <span class=\"ex-plg\"><span class=\"ex-plg-t\">en las actuaciones judiciales de conformidad con las reglas 89 a 91 de las Reglas de Procedimiento y Prueba y a las que se reconozcan los privilegios, inmunidades y facilidades a que se hace referencia en el párrafo 1 del</span></span> presente artículo <mark class=\"m-destacable\">un documento</mark> <mark class=\"m-personalizado\">en el</mark> <mark class=\"m-destacable\">que</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4123\">se certifique su participación en las actuaciones de la Corte y se especifique la duración de su participación</mark>.</p><p data-ex=\"*\"><b>Art. 22.</b> 1. <mark class=\"m-personalizado\">Se</mark> <mark class=\"m-accion\">reconocerá</mark> <mark class=\"m-personalizado\">a las otras personas cuya presencia se requiera</mark> en la sede de la <mark class=\"m-autoridad\">Corte</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, en la medida en que sea necesario para su presencia en dicha sede, incluido el tiempo empleado en viajes para ello,</span></span> los <mark class=\"m-personalizado\">privilegios</mark>, <mark class=\"m-personalizado\">inmunidades y facilidades</mark> que se indican en <mark class=\"m-resp\" data-q=\"1-308\">los apartados a) a d) del párrafo 1 del artículo 20</mark> <mark class=\"m-personalizado\">del presente</mark> Acuerdo <mark class=\"m-personalizado\">(los de las víctimas)</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, por la Presidencia</span></span>.</p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 19 — <mark class=\"m-destacable\">Testigos</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4119,1-ia-4120,1-ia-4121\">🎯 3 preguntas más de este artículo</mark></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 21 — Peritos: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4124,1-ia-4125,1-ia-4030\">🎯 3 preguntas más de este artículo</mark>"],["Artículo 23 — Nacionales y residentes permanentes <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b><mark class=\"m-destacable\">Art. 23.</mark></b> <b>b)</b> <mark class=\"m-personalizado\">Las personas</mark> indicadas en los artículos 20 y 22 sólo <mark class=\"m-accion\">disfrutarán,</mark> <mark class=\"m-personalizado\">en el territorio del</mark> <mark class=\"m-autoridad\">Estado Parte</mark> <mark class=\"m-personalizado\">del que sean nacionales o residentes permanentes,</mark> de los siguientes <mark class=\"m-personalizado\">privilegios e inmunidades en la medida necesaria para su comparecencia</mark> ante la <mark class=\"m-autoridad\">Corte:</mark> <mark class=\"m-resp ex-q\" data-q=\"1-309\">🎯 1 pregunta</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 23 — <mark class=\"m-autoridad\">Nacionales</mark> y residentes permanentes (texto completo): <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4127,1-ia-4128\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 24 — Cooperación con las autoridades de estados partes <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 24.</b> 1. La <mark class=\"m-autoridad\">Corte</mark> <mark class=\"m-accion\">cooperará</mark> en todo momento <mark class=\"m-destacable\">con las</mark> <mark class=\"m-autoridad\">autoridades</mark> competentes <mark class=\"m-destacable\">de</mark> los <mark class=\"m-autoridad\">Estados Partes</mark> para facilitar el cumplimiento de sus leyes e impedir <mark class=\"m-resp\" data-q=\"1-310\">abusos</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">en relación con los privilegios, las inmunidades y las facilidades a que se hace referencia en el presente Acuerdo.</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4129\">🎯 1 pregunta</mark></p><p><b>2.</b> <mark class=\"m-personalizado\">Todas las personas</mark> que gocen de <mark class=\"m-personalizado\">privilegios e inmunidades</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el presente Acuerdo <mark class=\"m-accion\">estarán</mark> <mark class=\"m-personalizado\">obligadas,</mark> sin perjuicio de esos privilegios e inmunidades, <mark class=\"m-personalizado\">a respetar las leyes y reglamentos del</mark> <mark class=\"m-autoridad\">Estado</mark> <mark class=\"m-personalizado\">Parte en cuyo territorio se encuentren o por el que transiten en ejercicio de sus funciones</mark> para la</span></span> <mark class=\"m-autoridad\">Corte.</mark> <mark class=\"m-accion\">Estarán</mark> también obligadas <mark class=\"m-personalizado\">a</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4130\">no inmiscuirse en los asuntos internos de ese Estado</mark>.</p>"],["Artículo 25 — Renuncia a los privilegios e inmunidades previstos <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 25.</b> <mark class=\"m-destacable\">EN LOS ARTÍCULOS 13 Y 14.</mark></p><p><mark class=\"m-personalizado\">Los privilegios <u class=\"m-clave\">e inmunidades</u></mark> previstos en los artículos <mark class=\"m-personalizado\">13 y 14</mark> del presente <mark class=\"m-personalizado\">Acuerdo no se otorgan a los representantes de los</mark> <mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-personalizado\">y de las organizaciones intergubernamentales</mark> <mark class=\"m-resp\" data-q=\"1-163,1-ia-4052\">en beneficio personal, sino para salvaguardar el ejercicio independiente de sus funciones</mark> en relación con la labor de la <mark class=\"m-autoridad\">Asamblea,</mark> <mark class=\"m-personalizado\">sus</mark> <mark class=\"m-autoridad\">órganos</mark> <mark class=\"m-personalizado\">subsidiarios</mark> y la <mark class=\"m-autoridad\">Corte.</mark> En consecuencia, <mark class=\"m-autoridad\">los Estados Partes</mark> <mark class=\"m-personalizado\">no sólo tienen el derecho, sino la obligación, de</mark> <mark class=\"m-destacable\">renunciar</mark> a <mark class=\"m-personalizado\">los privilegios e inmunidades</mark> de sus representantes <mark class=\"m-personalizado\">en todo <u class=\"m-clave\">caso</u></mark> en que, en opinión de dichos <mark class=\"m-autoridad\">Estados,</mark> estos privilegios e inmunidades <mark class=\"m-personalizado\">podrían constituir un obstáculo a <u class=\"m-clave\">la</u> justicia y la</mark> renuncia <mark class=\"m-personalizado\">sea posible sin perjuicio del fin</mark> para el cual se reconocen. Se reconocen a <mark class=\"m-autoridad\">los Estados que no sean Partes</mark> en el presente <mark class=\"m-personalizado\">Acuerdo</mark> <mark class=\"m-autoridad\">y a las organizaciones intergubernamentales</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">los privilegios e inmunidades previstos en los artículos 13 y 14 del presente Acuerdo en el</span></span> entendimiento de que <mark class=\"m-accion\">asumirán</mark> <mark class=\"m-personalizado\">las mismas obligaciones con respecto a la renuncia.</mark> <mark class=\"m-resp ex-q\" data-q=\"1-311,1-ia-4131\">🎯 2 preguntas</mark></p>"],["Artículo 26 — Renuncia a los privilegios e inmunidades <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 26.</b> <mark class=\"m-destacable\">EN LOS ARTÍCULOS 15 A 22.</mark></p><p><b>1.</b> <mark class=\"m-personalizado\">Los privilegios e inmunidades</mark> previstos en los artículos <mark class=\"m-personalizado\">15 a 22</mark> del presente Acuerdo <mark class=\"m-personalizado\">se reconocen en interés de la <mark class=\"m-resp\" data-q=\"1-312\">administración de justicia</mark> y no en beneficio personal.</mark> <mark class=\"m-accion\">Podrá</mark> <mark class=\"m-destacable\">renunciarse</mark> a ellos de <mark class=\"m-personalizado\">conformidad con el</mark> párrafo 5 del artículo 48 del Estatuto y con lo dispuesto en el presente artículo y <mark class=\"m-accion\">se tendrá</mark> la <mark class=\"m-personalizado\">obligación</mark> de hacerlo en un caso <mark class=\"m-personalizado\">determinado</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4132\">cuando podrían constituir un obstáculo a la justicia y la renuncia sea posible sin perjuicio del fin para el cual se reconocen</mark>.</p><p data-ex=\"EX\"><b>2.</b> <mark class=\"m-personalizado\">Se</mark> <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">renunciar a</mark> los privilegios e inmunidades:</p><p><b>a)</b> En el caso de un <mark class=\"m-autoridad\">Magistrado</mark> <mark class=\"m-personalizado\">o d</mark><mark class=\"m-resp r-ia\" data-q=\"1-ia-4139\">el Fiscal</mark>, por <mark class=\"m-resp\" data-q=\"1-219\">mayoría absoluta de los Magistrados</mark>;</p><p><b>b)</b> En el caso <mark class=\"m-personalizado\">del</mark> <mark class=\"m-autoridad\">Secretario,</mark> por <mark class=\"m-resp r-ia\" data-q=\"1-ia-4133\">la Presidencia</mark>;</p><p><b>f)</b> En el caso de los <mark class=\"m-autoridad\">abogados</mark> <mark class=\"m-personalizado\">y de las personas que asistan</mark> a los <mark class=\"m-autoridad\">abogados</mark> defensores, <mark class=\"m-resp r-ia\" data-q=\"1-ia-4135,1-ia-4136\">por la Presidencia</mark>;</p>"],["Artículos 27, 28, 29 y 30 — Seguridad social, notificación, laissez-passer y visados <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>Art. 27.</b> <mark class=\"m-personalizado\">A partir</mark> de la fecha en que <mark class=\"m-autoridad\">la Corte</mark> <mark class=\"m-personalizado\">establezca un sistema de seguridad</mark> social, las <mark class=\"m-personalizado\">personas</mark> a que se hace referencia en los artículos 15, 16 <mark class=\"m-personalizado\">y</mark> 17 <mark class=\"m-autoridad\">(Magistrados, Fiscal…</mark> y personal) <mark class=\"m-accion\">estarán</mark> <mark class=\"m-personalizado\">exentas</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">, en relación con los servicios prestados a la Corte,</span></span> de <mark class=\"m-resp\" data-q=\"1-94,1-ia-4137\">toda contribución obligatoria a los sistemas nacionales de seguridad social</mark>.</p><p><b>Art. 28.</b> <mark class=\"m-autoridad\">El Secretario</mark> <mark class=\"m-accion\">comunicará</mark> <mark class=\"m-autoridad\">periódicamente a todos los Estados Partes</mark> <mark class=\"m-resp\" data-q=\"1-96,1-ia-4134,1-ia-4139\">los nombres de los Magistrados, el Fiscal, los Fiscales Adjuntos, el Secretario, el Secretario Adjunto, el personal de la Fiscalía, el personal de la Secretaría y los abogados</mark> a quienes se apliquen las disposiciones del presente Acuerdo. <mark class=\"m-autoridad\">El Secretario</mark> <mark class=\"m-accion\">comunicará</mark> <mark class=\"m-personalizado\">también a</mark> todos los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-resp\" data-q=\"1-164,1-ia-4138\">información acerca de cualquier cambio en la condición de esas personas</mark>.</p><p data-ex=\"*\"><b>Art. 30.</b> <mark class=\"m-personalizado\">Las solicitudes</mark> de visado o permiso de entrada o salida <span class=\"ex-plg\"><span class=\"ex-plg-t\">, en caso de que sean necesarios, presentadas por quienes sean titulares de un laissez passer de las Naciones Unidas o del documento de viaje expedido por la Corte, u otra persona de las referidas en los artículos 18 a 22 del presente Acuerdo que tenga un certificado expedido por la Corte en que conste que su viaje obedece a asuntos de ésta,</span></span> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">tramitadas por</mark> los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-resp\" data-q=\"1-ia-4140,1-313\">con la mayor rapidez posible y con carácter gratuito</mark>.</p>"],["Artículo 29 — Laissez-passer","<p><span class=\"ex-plg\"><span class=\"ex-plg-t\">Los Estados Partes reconocerán y aceptarán como documentos de viaje válidos los laissez passer de las Naciones Unidas o los documentos de viaje expedidos por la Corte a los Magistrados, el Fiscal, los Fiscales Adjuntos, el Secretario, el Secretario Adjunto, el personal de la Fiscalía y el personal de la Secretaría.</span></span> <mark class=\"m-resp ex-q\" data-q=\"1-165,1-ia-4229\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo</mark> 31 — Arreglo de controversias con terceros: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4141,1-ia-4230\">🎯 2 preguntas más de este artículo</mark>"],["Artículo 32 — Arreglo de diferencias sobre la interpretación o aplicación del Acuerdo <span class=\"ex-sello\">EX</span> <span class=\"ex-sello\">✱</span> <span class=\"ex-sello ex-sello-r\">R33</span>","<p data-ex=\"*\"><b>1.</b> <mark class=\"m-personalizado\">Todas las diferencias que</mark> surjan de la <mark class=\"m-personalizado\">interpretación o aplicación</mark> del presente <mark class=\"m-personalizado\">Acuerdo</mark> <mark class=\"m-autoridad\">entre dos o más Estados Partes</mark> <mark class=\"m-personalizado\">o entre</mark> <mark class=\"m-autoridad\">la Corte y un Estado Parte</mark> <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">resueltas</mark> <mark class=\"m-resp\" data-q=\"1-117,1-ia-4142\">mediante consultas, negociación u otro medio convenido de arreglo</mark>.</p><p><b>2.</b> <mark class=\"m-destacable\">La</mark> diferencia, de no ser resuelta <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el párrafo 1 del presente artículo</span></span> <mark class=\"m-personalizado\">dentro de los</mark> tres meses siguientes a la presentación de una <mark class=\"m-plazo\">solicitud por escrito</mark> <span class=\"hueco-txt\">por una de las partes en ella</span>, <mark class=\"m-accion\">será,</mark> <mark class=\"m-personalizado\">a petición de cualquiera</mark> de las partes, <mark class=\"m-personalizado\">sometida</mark> a un <mark class=\"m-resp\" data-q=\"1-81,1-ia-4143\">tribunal arbitral</mark> <span class=\"ex-plg\"><span class=\"ex-plg-t\">de conformidad con el procedimiento establecido en los párrafos 3 a 6 infra</span></span>.</p><p data-ex=\"EX\" data-r=\"R33\"><span class=\"ex-sello ex-sello-r\">R33</span> <b>3.</b> <mark class=\"m-autoridad\">El tribunal arbitral</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">compuesto de</mark> <mark class=\"m-destacable\">tres árbitros</mark>: <mark class=\"m-personalizado\">uno</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">elegido por</mark> <mark class=\"m-autoridad\">cada parte</mark> en la diferencia <mark class=\"m-personalizado\">y el tercero</mark>, que <mark class=\"m-accion\">actuará</mark> <mark class=\"m-personalizado\">como</mark> <mark class=\"m-autoridad\">presidente del tribunal,</mark> <mark class=\"m-accion\">será</mark> <mark class=\"m-personalizado\">elegido <u class=\"m-clave\">por</u> los otros <u class=\"m-clave\">dos.</u> Si una de las partes</mark> <mark class=\"m-destacable\">no</mark> <mark class=\"m-personalizado\">hubiere nombrado</mark> a un árbitro <span class=\"ex-plg\"><span class=\"ex-plg-t\">del tribunal</span></span> dentro de los <mark class=\"m-destacable\">dos meses</mark> <span class=\"m-caja\"><mark class=\"m-plazo\">siguientes</mark></span> al <mark class=\"m-personalizado\">nombramiento</mark> <mark class=\"m-autoridad\">de</mark> un árbitro por <mark class=\"m-autoridad\">la</mark> otra <mark class=\"m-personalizado\">parte,</mark> ésta <mark class=\"m-accion\">podrá</mark> <mark class=\"m-personalizado\">pedir</mark> <mark class=\"m-autoridad\">al</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4145\">Presidente de la Corte Internacional de Justicia</mark> que efectúe dicho <mark class=\"m-personalizado\">nombramiento</mark>. <span class=\"hueco-txt\">En caso de que los dos primeros árbitros no convinieran en el nombramiento del presidente del tribunal en los dos meses siguientes a sus nombramientos, cualquiera de las partes podrá pedir al Presidente de la Corte Internacional de Justicia que efectúe el nombramiento del presidente del tribunal.</span> <mark class=\"m-resp ex-q\" data-q=\"1-166\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>5.</b> El <mark class=\"m-autoridad\">tribunal</mark> arbitral <span class=\"ex-plg\"><span class=\"ex-plg-t\">, que</span></span> <mark class=\"m-accion\">adoptará</mark> sus decisiones por mayoría <mark class=\"m-personalizado\">de</mark> votos <span class=\"ex-plg\"><span class=\"ex-plg-t\">, llegará a una decisión sobre la diferencia de conformidad con las disposiciones del presente Acuerdo y las normas aplicables de derecho internacional</span></span>. <mark class=\"m-destacable\">El laudo</mark> del <mark class=\"m-autoridad\">tribunal</mark> arbitral <mark class=\"m-accion\">será</mark> <mark class=\"m-destacable\">definitivo y obligatorio</mark> <mark class=\"m-personalizado\">para</mark> <mark class=\"m-autoridad\">las partes</mark> en la diferencia. <mark class=\"m-resp ex-q\" data-q=\"1-314,1-ia-4146\">🎯 2 preguntas</mark></p></div></div><div class=\"ex-linea\"><mark class=\"m-personalizado\">Artículo 33</mark> — Aplicabilidad <mark class=\"m-personalizado\">del presente</mark> <mark class=\"m-personalizado\">acuerdo</mark>: <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4148,1-ia-4231\">🎯 2 preguntas más de este artículo</mark>"],["Artículos 34 y 35 — Firma y entrada en vigor · R33","<p><b>Art. 34.</b> 1. El presente <mark class=\"m-personalizado\">Acuerdo</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">abierto a la firma de todos los</mark> <mark class=\"m-autoridad\">Estados</mark> <mark class=\"m-resp r-ia\" data-q=\"1-ia-4026\">desde el 10 de septiembre de 2002 hasta el 30 de junio de 2004</mark> en la <mark class=\"m-resp r-ia\" data-q=\"1-ia-4149\">Sede de las Naciones Unidas en Nueva York</mark>. <span class=\"ex-plg\"><span class=\"ex-plg-t\">2. (…) Los instrumentos de ratificación, aceptación o aprobación <mark class=\"m-accion\">serán</mark> <mark class=\"m-personalizado\">depositados en poder del</mark> <mark class=\"m-autoridad\">Secretario General</mark>. 3. El presente <mark class=\"m-personalizado\">Acuerdo</mark> <mark class=\"m-accion\">estará</mark> <mark class=\"m-personalizado\">abierto a la adhesión de todos los</mark> <mark class=\"m-autoridad\">Estados</mark>. (…)</span></span> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4150\">🎯 1 pregunta</mark></p><p><b>Art. 35.</b> 1. El presente <mark class=\"m-personalizado\">Acuerdo</mark> <mark class=\"m-accion\">entrará</mark> en <mark class=\"m-plazo\">vigor</mark> <mark class=\"m-resp\" data-q=\"1-167,1-ia-4151,1-ia-4152,1-ia-4159\">treinta días después de la fecha en que se deposite en poder del Secretario General el décimo instrumento</mark> de ratificación, aceptación, aprobación o adhesión. 2. <span class=\"ex-plg\"><span class=\"ex-plg-t\">\u0007Respecto de cada Estado que ratifique, acepte o apruebe el presente Acuerdo o se adhiera a él después del depósito del décimo instrumento de ratificación, aceptación, aprobación o adhesión, el presente Acuerdo entrará en vigor</span></span> el trigésimo día siguiente <mark class=\"m-autoridad\">a la fecha en</mark> que deposite <span class=\"ex-plg\"><span class=\"ex-plg-t\">en poder del Secretario General</span></span> su instrumento <span class=\"ex-plg\"><span class=\"ex-plg-t\">de ratificación, aceptación, aprobación o adhesión</span></span>.</p>"],["Artículo 36 — Enmiendas <span class=\"ex-sello\">✱</span>","<p data-ex=\"*\"><b>2.</b> <mark class=\"m-plazo\">Si, dentro de los <mark class=\"m-resp\" data-q=\"1-315\">tres meses</mark> siguientes a la fecha en que la</mark> <mark class=\"m-autoridad\">secretaría</mark> <mark class=\"m-plazo\">de la</mark> <mark class=\"m-autoridad\">Asamblea</mark> <mark class=\"m-plazo\">haya distribuido la comunicación, una mayoría de los</mark> <mark class=\"m-autoridad\">Estados Partes</mark> le notifican que son partidarios de que se celebre una conferencia de examen, la <mark class=\"m-autoridad\">secretaria</mark> <mark class=\"m-accion\">informará</mark> a la Mesa de la <mark class=\"m-autoridad\">Asamblea</mark> con miras a convocar dicha conferencia en ocasión del <mark class=\"m-personalizado\">siguiente período de sesiones ordinario o extraordinario</mark> de la <mark class=\"m-autoridad\">Asamblea.</mark> <mark class=\"m-resp ex-q r-ia\" data-q=\"1-ia-4153\">🎯 1 pregunta</mark></p><p data-ex=\"*\"><b>3.</b> <mark class=\"m-personalizado\">Las enmiendas</mark> respecto de las cuales no pueda llegarse a <mark class=\"m-personalizado\">un consenso</mark> <mark class=\"m-accion\">serán aprobadas</mark> <mark class=\"m-destacable\">por mayoría de <mark class=\"m-resp\" data-q=\"1-316\">dos tercios</mark></mark> de los <mark class=\"m-autoridad\">Estados Partes</mark> <mark class=\"m-destacable\">presentes y votantes,</mark> <mark class=\"m-personalizado\">a condición de</mark> que <mark class=\"m-resp r-ia\" data-q=\"1-ia-4154\">esté presente una mayoría de los Estados Partes</mark>.</p><p><b>5.</b> <mark class=\"m-destacable\">Una enmienda</mark> <mark class=\"m-accion\">entrará</mark> <mark class=\"m-personalizado\">en vigor para</mark> los <mark class=\"m-autoridad\">Estados Partes</mark> que la hayan ratificado o aceptado <mark class=\"m-plazo\">sesenta días</mark> después del depósito de los instrumentos de ratificación o aceptación en poder del <mark class=\"m-autoridad\">Secretario</mark> General por <mark class=\"m-resp r-ia\" data-q=\"1-ia-4155\">los dos tercios de los Estados que eran Partes en la fecha en que se aprobó la enmienda</mark>.</p><p><b>b)</b> <mark class=\"m-personalizado\">Se</mark> <mark class=\"m-accion\">considerará</mark> <mark class=\"m-personalizado\">Parte</mark> en el presente Acuerdo <mark class=\"m-resp r-ia\" data-q=\"1-ia-4156\">sin la <mark class=\"m-personalizado\">enmienda</mark> introducida respecto <mark class=\"m-personalizado\">de cualquier</mark> <mark class=\"m-autoridad\">Estado</mark> Parte que <mark class=\"m-personalizado\">no</mark> esté <mark class=\"m-personalizado\">obligado</mark> por dicha enmienda</mark>.</p>"]];
